CREATE OR REPLACE FUNCTION public.check_rate_limit(p_key text, p_max_requests integer, p_window_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_timestamps timestamptz[];
    v_threshold timestamptz;
    v_retry_after int := 0;
BEGIN
    v_threshold := now() - make_interval(secs => p_window_seconds);

    -- Ensure row exists and lock it
    INSERT INTO public.ip_rate_limit_store (key, timestamps, updated_at)
    VALUES (p_key, ARRAY[]::timestamptz[], now())
    ON CONFLICT (key) DO NOTHING;

    SELECT ARRAY(
        SELECT t FROM unnest(timestamps) t WHERE t > v_threshold
    ) INTO v_timestamps
    FROM public.ip_rate_limit_store
    WHERE key = p_key FOR UPDATE;

    IF coalesce(array_length(v_timestamps, 1), 0) >= p_max_requests THEN
        -- Reject
        v_retry_after := GREATEST(0, CEIL(EXTRACT(epoch FROM (v_timestamps[1] + make_interval(secs => p_window_seconds) - now()))))::int;
        UPDATE public.ip_rate_limit_store
        SET timestamps = v_timestamps,
            updated_at = now()
        WHERE key = p_key;
        RETURN jsonb_build_object('allowed', false, 'retry_after', v_retry_after);
    ELSE
        -- Allow
        UPDATE public.ip_rate_limit_store
        SET timestamps = array_append(v_timestamps, now()),
            updated_at = now()
        WHERE key = p_key;
        RETURN jsonb_build_object('allowed', true, 'retry_after', 0);
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_crm_pipeline_stage()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.pipeline_stage := NEW.status::text;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.customer_purchase_from_merchant(p_inventory_id uuid, p_quantity integer, p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_inventory RECORD;
    v_total_cost BIGINT;
    v_customer_balance BIGINT;
    v_new_merchant_balance BIGINT;
BEGIN
    PERFORM set_config('app.internal_bypass', 'true', true);

    SELECT * INTO v_inventory FROM public.merchant_inventory WHERE id = p_inventory_id FOR UPDATE;

    IF NOT FOUND THEN
        PERFORM set_config('app.internal_bypass', 'false', true);
        RETURN jsonb_build_object('success', false, 'message', 'Inventory item not found');
    END IF;

    IF v_inventory.stock_quantity < p_quantity THEN
        PERFORM set_config('app.internal_bypass', 'false', true);
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient merchant stock');
    END IF;

    v_total_cost := v_inventory.retail_price_paise * p_quantity;

    SELECT wallet_balance_paise INTO v_customer_balance
    FROM public.user_profiles WHERE id = p_customer_id FOR UPDATE;

    IF v_customer_balance < v_total_cost THEN
        PERFORM set_config('app.internal_bypass', 'false', true);
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient wallet balance');
    END IF;

    UPDATE public.user_profiles SET wallet_balance_paise = wallet_balance_paise - v_total_cost WHERE id = p_customer_id;

    UPDATE public.merchants SET wallet_balance_paise = wallet_balance_paise + v_total_cost 
    WHERE id = v_inventory.merchant_id 
    RETURNING wallet_balance_paise INTO v_new_merchant_balance;

    UPDATE public.merchant_inventory SET stock_quantity = stock_quantity - p_quantity WHERE id = p_inventory_id;

    INSERT INTO public.shopping_orders (buyer_id, buyer_type, seller_id, seller_type, product_id, quantity, unit_price_paise, total_price_paise, order_type)
    VALUES (p_customer_id, 'customer', v_inventory.merchant_id, 'merchant', v_inventory.product_id, p_quantity, v_inventory.retail_price_paise, v_total_cost, 'retail');

    INSERT INTO public.merchant_transactions (merchant_id, transaction_type, amount_paise, balance_after_paise, description, metadata)
    VALUES (v_inventory.merchant_id, 'sale_earnings', v_total_cost, v_new_merchant_balance, 'Product sale to customer', jsonb_build_object('buyer_id', p_customer_id, 'product_id', v_inventory.product_id));

    PERFORM set_config('app.internal_bypass', 'false', true);
    RETURN jsonb_build_object('success', true, 'message', 'Order placed successfully');

EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.internal_bypass', 'false', true);
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.update_merchant_inventory_stock(p_inventory_id uuid, p_new_stock integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_item RECORD;
BEGIN
    -- 1. Validate input
    IF p_new_stock < 0 THEN
        RETURN jsonb_build_object('success', false, 'message', 'Stock quantity cannot be negative');
    END IF;

    -- 2. Fetch inventory row and verify ownership
    SELECT mi.id, mi.is_platform_product, mi.merchant_id
    INTO v_item
    FROM public.merchant_inventory mi
    WHERE mi.id = p_inventory_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Inventory item not found');
    END IF;

    -- 3. Verify the caller is the owning merchant
    IF NOT EXISTS (
        SELECT 1 FROM public.merchants
        WHERE id = v_item.merchant_id AND user_id = auth.uid()
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Unauthorized: You do not own this inventory item');
    END IF;

    -- 4. Block stock edits for platform products
    IF v_item.is_platform_product THEN
        RETURN jsonb_build_object(
            'success', false,
            'message', 'Stock for platform-sourced products cannot be edited manually. Please restock via the Wholesale Market.'
        );
    END IF;

    -- 5. Apply the update (SECURITY DEFINER bypasses the trigger check)
    UPDATE public.merchant_inventory
    SET stock_quantity = p_new_stock
    WHERE id = p_inventory_id;

    RETURN jsonb_build_object('success', true, 'message', 'Stock updated successfully');
END;
$function$

CREATE OR REPLACE FUNCTION public.enforce_flash_sale_max_active()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_active_count integer;
BEGIN
  -- Only enforce when the resulting row will be active
  IF NEW.is_active = true THEN
    SELECT COUNT(*) INTO v_active_count
    FROM public.flash_sale_items
    WHERE is_active = true
      AND id IS DISTINCT FROM NEW.id;  -- exclude self on UPDATE
    IF v_active_count >= 5 THEN
      RAISE EXCEPTION 'Flash sale already has 5 active items (max allowed)';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.purchase_platform_products(p_product_id uuid, p_quantity integer, p_merchant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_wholesale_price BIGINT;
    v_total_cost BIGINT;
    v_merchant_balance BIGINT;
    v_admin_stock INTEGER;
    v_new_balance BIGINT;
BEGIN
    PERFORM set_config('app.internal_bypass', 'true', true);

    IF NOT EXISTS (
        SELECT 1 FROM public.merchants 
        WHERE id = p_merchant_id AND user_id = auth.uid()
    ) THEN
        PERFORM set_config('app.internal_bypass', 'false', true);
        RETURN jsonb_build_object('success', false, 'message', 'Unauthorized: Merchant identity mismatch');
    END IF;

    SELECT wholesale_price_paise, admin_stock INTO v_wholesale_price, v_admin_stock
    FROM public.shopping_products WHERE id = p_product_id FOR UPDATE;

    IF v_admin_stock < p_quantity THEN
        PERFORM set_config('app.internal_bypass', 'false', true);
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient admin stock');
    END IF;

    v_total_cost := v_wholesale_price * p_quantity;

    SELECT wallet_balance_paise INTO v_merchant_balance
    FROM public.merchants WHERE id = p_merchant_id FOR UPDATE;

    IF v_merchant_balance < v_total_cost THEN
        PERFORM set_config('app.internal_bypass', 'false', true);
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient merchant balance');
    END IF;

    UPDATE public.merchants SET wallet_balance_paise = wallet_balance_paise - v_total_cost 
    WHERE id = p_merchant_id 
    RETURNING wallet_balance_paise INTO v_new_balance;

    UPDATE public.shopping_products SET admin_stock = admin_stock - p_quantity WHERE id = p_product_id;

    INSERT INTO public.merchant_inventory (
        merchant_id, product_id, stock_quantity, retail_price_paise, 
        is_platform_product, is_active, custom_title, custom_description
    )
    SELECT 
        p_merchant_id, p_product_id, p_quantity, suggested_retail_price_paise, 
        true, false, title, description
    FROM public.shopping_products WHERE id = p_product_id
    ON CONFLICT (merchant_id, product_id) DO UPDATE
    SET stock_quantity      = public.merchant_inventory.stock_quantity + p_quantity,
        retail_price_paise  = EXCLUDED.retail_price_paise,
        is_platform_product = true,
        is_active           = EXCLUDED.is_active,
        custom_title        = EXCLUDED.custom_title,
        custom_description  = EXCLUDED.custom_description,
        updated_at          = now();

    INSERT INTO public.shopping_orders (buyer_id, buyer_type, seller_id, seller_type, product_id, quantity, unit_price_paise, total_price_paise, order_type)
    VALUES (p_merchant_id, 'merchant', NULL, 'admin', p_product_id, p_quantity, v_wholesale_price, v_total_cost, 'wholesale');

    INSERT INTO public.merchant_transactions (merchant_id, transaction_type, amount_paise, balance_after_paise, description, metadata)
    VALUES (p_merchant_id, 'purchase', -v_total_cost, v_new_balance, 'Wholesale purchase of products', jsonb_build_object('product_id', p_product_id, 'quantity', p_quantity));

    PERFORM set_config('app.internal_bypass', 'false', true);
    RETURN jsonb_build_object('success', true, 'message', 'Purchase successful');

EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.internal_bypass', 'false', true);
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.encrypt_pii(data text, secret_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF data IS NULL THEN RETURN NULL; END IF;
    RETURN encode(pgp_sym_encrypt(data, secret_key), 'base64');
END;
$function$

CREATE OR REPLACE FUNCTION public.decrypt_pii(encrypted_data text, secret_key text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF encrypted_data IS NULL THEN RETURN NULL; END IF;
    RETURN pgp_sym_decrypt(decode(encrypted_data, 'base64'), secret_key);
END;
$function$

CREATE OR REPLACE FUNCTION public.wallet_activate_gold_subscription(p_user_id uuid, p_package_key text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_price_paise          bigint;
    v_duration_months      int;
    v_cashback_paise       bigint;
    v_label                text;

    v_current_balance_paise bigint;
    v_current_expiry        timestamptz;
    v_is_gold_verified      boolean;
    v_base_date             timestamptz;
    v_new_expiry            timestamptz;

    v_debit_txn_id         uuid;
BEGIN
    -- 1. Resolve canonical plan constants server-side (no trust of client amounts)
    CASE p_package_key
        WHEN 'GOLD_1M' THEN
            v_price_paise    := 99900;   -- ₹999
            v_duration_months := 1;
            v_cashback_paise := 19900;   -- ₹199
            v_label          := '1 Month';
        WHEN 'GOLD_3M' THEN
            v_price_paise    := 249900;  -- ₹2,499
            v_duration_months := 3;
            v_cashback_paise := 49900;   -- ₹499
            v_label          := '3 Months';
        WHEN 'GOLD_1Y' THEN
            v_price_paise    := 799900;  -- ₹7,999
            v_duration_months := 12;
            v_cashback_paise := 149900;  -- ₹1,499
            v_label          := '12 Months';
        ELSE
            RETURN json_build_object(
                'success', false,
                'message', 'Invalid package selection'
            );
    END CASE;

    -- 2. Idempotency guard — bail early if already processed
    IF p_idempotency_key IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM customer_wallet_transactions
            WHERE user_id      = p_user_id
              AND reference_id   = p_idempotency_key
              AND reference_type = 'GOLD_SUBSCRIPTION'
              AND transaction_type = 'DEBIT'
        ) THEN
            RETURN json_build_object(
                'success', true,
                'replayed', true,
                'message', 'Idempotent replay — subscription already activated'
            );
        END IF;
    END IF;

    -- 3. Lock customer wallet row to prevent concurrent debits
    SELECT balance_paise INTO v_current_balance_paise
    FROM customer_wallets
    WHERE user_id = p_user_id
    FOR UPDATE;

    IF v_current_balance_paise IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Wallet not found');
    END IF;

    IF v_current_balance_paise < v_price_paise THEN
        RETURN json_build_object(
            'success', false,
            'message', format(
                'Insufficient balance. Required: ₹%s, Available: ₹%s',
                (v_price_paise / 100.0)::numeric(10,2),
                (v_current_balance_paise / 100.0)::numeric(10,2)
            )
        );
    END IF;

    -- 4. Debit wallet
    UPDATE customer_wallets
    SET balance_paise = balance_paise - v_price_paise,
        updated_at    = now()
    WHERE user_id = p_user_id;

    -- 5. Record debit transaction (also serves as idempotency anchor)
    INSERT INTO customer_wallet_transactions (
        user_id,
        amount_paise,
        transaction_type,
        description,
        reference_id,
        reference_type,
        balance_after_paise,
        created_at
    )
    VALUES (
        p_user_id,
        v_price_paise,
        'DEBIT',
        'Elite Gold ' || v_label || ' Subscription (Wallet Pay)',
        COALESCE(p_idempotency_key, p_package_key),
        'GOLD_SUBSCRIPTION',
        v_current_balance_paise - v_price_paise,
        now()
    )
    RETURNING id INTO v_debit_txn_id;

    -- 6. Determine new expiry (extend from current if still active)
    SELECT is_gold_verified, subscription_expiry
    INTO v_is_gold_verified, v_current_expiry
    FROM user_profiles
    WHERE id = p_user_id;

    v_base_date := now();
    IF v_is_gold_verified AND v_current_expiry IS NOT NULL AND v_current_expiry > now() THEN
        v_base_date := v_current_expiry;
    END IF;

    v_new_expiry := v_base_date + (v_duration_months || ' months')::interval;

    -- 7. Activate / extend subscription on profile
    UPDATE user_profiles
    SET is_gold_verified   = true,
        subscription_expiry = v_new_expiry,
        updated_at          = now()
    WHERE id = p_user_id;

    -- 8. Credit cashback wallet
    UPDATE customer_wallets
    SET balance_paise = balance_paise + v_cashback_paise,
        updated_at    = now()
    WHERE user_id = p_user_id;

    INSERT INTO customer_wallet_transactions (
        user_id,
        amount_paise,
        transaction_type,
        description,
        reference_id,
        reference_type,
        balance_after_paise,
        created_at
    )
    SELECT
        p_user_id,
        v_cashback_paise,
        'CREDIT',
        'Gold ' || v_label || ' Subscription Cashback Reward',
        v_debit_txn_id::text,
        'CASHBACK',
        cw.balance_paise,
        now()
    FROM customer_wallets cw
    WHERE cw.user_id = p_user_id;

    -- 9. In-app notification
    INSERT INTO notifications (user_id, title, body, type, reference_type, reference_id)
    VALUES (
        p_user_id,
        'Elite Gold Activated! 🎉',
        'Your Elite Gold subscription has been activated using your wallet. Expiry: '
            || to_char(v_new_expiry, 'DD Mon YYYY'),
        'success',
        'gold_subscription',
        p_package_key
    );

    RETURN json_build_object(
        'success',     true,
        'new_expiry',  v_new_expiry,
        'message',     'Gold subscription activated successfully'
    );

EXCEPTION WHEN OTHERS THEN
    -- Any unhandled error rolls back the entire transaction
    RETURN json_build_object(
        'success', false,
        'message', 'Unexpected error: ' || SQLERRM
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_team(p_team_id uuid, p_expected_version integer DEFAULT NULL::integer, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_region_level text DEFAULT NULL::text, p_state text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_area text DEFAULT NULL::text, p_parent_team_id uuid DEFAULT NULL::uuid, p_team_lead_id uuid DEFAULT NULL::uuid, p_color text DEFAULT NULL::text, p_retain_old_lead boolean DEFAULT true, p_caller_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_caller_id UUID;
    v_caller_role TEXT;
    v_curr_team RECORD;
    v_old_lead_id UUID;
    v_new_lead_role TEXT;
    v_new_version INT;
BEGIN
    v_caller_id := p_caller_id;
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'UNAUTHENTICATED', 'error', 'Caller ID required');
    END IF;

    SELECT role::text INTO v_caller_role FROM public.user_profiles WHERE id = v_caller_id;
    IF v_caller_role NOT IN ('admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN_SCOPE', 'error', 'Only admins can update team details');
    END IF;

    SELECT * INTO v_curr_team FROM public.teams WHERE id = p_team_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'code', 'TEAM_NOT_FOUND', 'error', 'Team not found');
    END IF;

    IF NOT v_curr_team.is_active THEN
        RETURN jsonb_build_object('success', false, 'code', 'TEAM_INACTIVE', 'error', 'Cannot update inactive team');
    END IF;

    -- Optimistic Concurrency Control
    IF p_expected_version IS NOT NULL AND v_curr_team.version != p_expected_version THEN
        RETURN jsonb_build_object(
            'success', false,
            'code', 'VERSION_CONFLICT',
            'error', 'Team has been modified by another request. Current version is ' || v_curr_team.version
        );
    END IF;

    v_old_lead_id := v_curr_team.team_lead_id;

    IF p_team_lead_id IS DISTINCT FROM v_old_lead_id AND p_team_lead_id IS NOT NULL THEN
        SELECT role::text INTO v_new_lead_role FROM public.user_profiles WHERE id = p_team_lead_id;
        IF v_new_lead_role IS NULL THEN
            RETURN jsonb_build_object('success', false, 'code', 'USER_NOT_FOUND', 'error', 'New team lead not found');
        END IF;
        IF v_new_lead_role NOT IN ('relationship_manager', 'admin', 'super_admin') THEN
            RETURN jsonb_build_object('success', false, 'code', 'USER_INELIGIBLE', 'error', 'Team lead must have manager or admin role');
        END IF;
    END IF;

    v_new_version := v_curr_team.version + 1;

    UPDATE public.teams
    SET name = COALESCE(TRIM(p_name), name),
        description = COALESCE(p_description, description),
        region_level = COALESCE(p_region_level, region_level),
        state = COALESCE(p_state, state),
        city = COALESCE(p_city, city),
        area = COALESCE(p_area, area),
        parent_team_id = CASE WHEN p_parent_team_id IS NOT NULL THEN p_parent_team_id ELSE parent_team_id END,
        team_lead_id = CASE WHEN p_team_lead_id IS NOT NULL THEN p_team_lead_id ELSE team_lead_id END,
        color = COALESCE(p_color, color),
        version = v_new_version,
        updated_at = NOW()
    WHERE id = p_team_id;

    -- Handle lead change
    IF p_team_lead_id IS DISTINCT FROM v_old_lead_id THEN
        -- Add new lead to team members if specified
        IF p_team_lead_id IS NOT NULL THEN
            INSERT INTO public.team_members (team_id, user_id)
            VALUES (p_team_id, p_team_lead_id)
            ON CONFLICT (user_id) DO UPDATE SET team_id = p_team_id, joined_at = NOW();
        END IF;

        -- If explicit request not to retain old lead, remove old lead from team members
        IF v_old_lead_id IS NOT NULL AND NOT p_retain_old_lead THEN
            DELETE FROM public.team_members WHERE user_id = v_old_lead_id AND team_id = p_team_id;
        END IF;
    END IF;

    -- Audit Log
    INSERT INTO public.audit_logs_crm (
        actor_id, action, table_name, record_id, old_data, new_data
    ) VALUES (
        v_caller_id,
        'UPDATE_TEAM',
        'teams',
        p_team_id,
        to_jsonb(v_curr_team),
        jsonb_build_object(
            'name', COALESCE(p_name, v_curr_team.name),
            'parent_team_id', p_parent_team_id,
            'team_lead_id', p_team_lead_id,
            'old_lead_id', v_old_lead_id,
            'retain_old_lead', p_retain_old_lead,
            'version', v_new_version,
            'reason', p_reason,
            'request_id', p_request_id
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'team_id', p_team_id,
        'version', v_new_version,
        'message', 'Team updated successfully'
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'code', SQLSTATE, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_bulk_transfer_members(p_source_team_id uuid, p_target_team_id uuid, p_user_ids uuid[], p_caller_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_caller_id UUID;
    v_caller_role TEXT;
    v_uid UUID;
    v_res JSONB;
    v_transferred_count INT := 0;
BEGIN
    v_caller_id := p_caller_id;
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'UNAUTHENTICATED', 'error', 'Caller ID required');
    END IF;

    SELECT role::text INTO v_caller_role FROM public.user_profiles WHERE id = v_caller_id;
    IF v_caller_role NOT IN ('admin', 'super_admin', 'relationship_manager') THEN
        RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN_SCOPE', 'error', 'Unauthorized access');
    END IF;

    FOREACH v_uid IN ARRAY p_user_ids LOOP
        v_res := public.admin_add_team_member(p_target_team_id, v_uid, v_caller_id, p_reason, p_request_id);
        IF (v_res->>'success')::boolean IS TRUE THEN
            v_transferred_count := v_transferred_count + 1;
        ELSE
            RAISE EXCEPTION 'BULK_TRANSFER_FAILED: Failed to transfer user %: %', v_uid, (v_res->>'error');
        END IF;
    END LOOP;

    RETURN jsonb_build_object(
        'success', true,
        'transferred_count', v_transferred_count,
        'message', 'Transferred ' || v_transferred_count || ' members successfully'
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'code', SQLSTATE, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_create_team(p_name text, p_region_level text, p_description text DEFAULT NULL::text, p_state text DEFAULT 'Madhya Pradesh'::text, p_city text DEFAULT NULL::text, p_area text DEFAULT NULL::text, p_parent_team_id uuid DEFAULT NULL::uuid, p_team_lead_id uuid DEFAULT NULL::uuid, p_color text DEFAULT '#6366f1'::text, p_caller_id uuid DEFAULT NULL::uuid, p_request_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_caller_id UUID;
    v_caller_role TEXT;
    v_new_team_id UUID;
    v_lead_role TEXT;
BEGIN
    v_caller_id := p_caller_id;
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'UNAUTHENTICATED', 'error', 'Caller ID required');
    END IF;

    SELECT role::text INTO v_caller_role FROM public.user_profiles WHERE id = v_caller_id;
    IF v_caller_role NOT IN ('admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN_SCOPE', 'error', 'Only admins can create teams');
    END IF;

    IF p_team_lead_id IS NOT NULL THEN
        SELECT role::text INTO v_lead_role FROM public.user_profiles WHERE id = p_team_lead_id;
        IF v_lead_role IS NULL THEN
            RETURN jsonb_build_object('success', false, 'code', 'USER_NOT_FOUND', 'error', 'Target team lead not found');
        END IF;
        IF v_lead_role NOT IN ('relationship_manager', 'admin', 'super_admin') THEN
            RETURN jsonb_build_object('success', false, 'code', 'USER_INELIGIBLE', 'error', 'Target lead must have manager or admin role');
        END IF;
    END IF;

    INSERT INTO public.teams (
        name, description, region_level, state, city, area,
        parent_team_id, team_lead_id, color, created_by, version
    ) VALUES (
        TRIM(p_name), p_description, p_region_level, p_state, p_city, p_area,
        p_parent_team_id, p_team_lead_id, p_color, v_caller_id, 1
    ) RETURNING id INTO v_new_team_id;

    -- If lead specified, ensure lead is added as a team member
    IF p_team_lead_id IS NOT NULL THEN
        INSERT INTO public.team_members (team_id, user_id)
        VALUES (v_new_team_id, p_team_lead_id)
        ON CONFLICT (user_id) DO UPDATE SET team_id = v_new_team_id, joined_at = NOW();
    END IF;

    -- Audit Log
    INSERT INTO public.audit_logs_crm (
        actor_id, action, table_name, record_id, old_data, new_data
    ) VALUES (
        v_caller_id,
        'CREATE_TEAM',
        'teams',
        v_new_team_id,
        NULL,
        jsonb_build_object(
            'team_id', v_new_team_id,
            'name', TRIM(p_name),
            'region_level', p_region_level,
            'state', p_state,
            'city', p_city,
            'area', p_area,
            'parent_team_id', p_parent_team_id,
            'team_lead_id', p_team_lead_id,
            'request_id', p_request_id
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'team_id', v_new_team_id,
        'version', 1,
        'message', 'Team created successfully'
    );
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'code', SQLSTATE, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_add_team_member(p_team_id uuid, p_user_id uuid, p_caller_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_caller_id UUID;
    v_caller_role TEXT;
    v_target_role TEXT;
    v_old_team_id UUID;
    v_team RECORD;
    v_authorized_scope UUID[];
BEGIN
    v_caller_id := p_caller_id;
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'UNAUTHENTICATED', 'error', 'Caller ID required');
    END IF;

    SELECT role::text INTO v_caller_role FROM public.user_profiles WHERE id = v_caller_id;
    IF v_caller_role NOT IN ('admin', 'super_admin', 'relationship_manager') THEN
        RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN_SCOPE', 'error', 'Unauthorized access');
    END IF;

    -- Target Team Check
    SELECT * INTO v_team FROM public.teams WHERE id = p_team_id AND is_active = true;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'code', 'TEAM_NOT_FOUND', 'error', 'Target team does not exist or is inactive');
    END IF;

    -- Target User Role & Protection Check
    SELECT role::text, team_id INTO v_target_role, v_old_team_id
    FROM public.user_profiles WHERE id = p_user_id;

    IF v_target_role IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'USER_NOT_FOUND', 'error', 'Target user not found');
    END IF;

    -- Protect super_admin / admin from manager-initiated reassignment
    IF v_caller_role = 'relationship_manager' AND v_target_role IN ('admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'code', 'PROTECTED_USER', 'error', 'Managers cannot reassign administrator profiles');
    END IF;

    -- Subtree Scope Check for Relationship Managers
    IF v_caller_role = 'relationship_manager' THEN
        SELECT ARRAY_AGG(team_id) INTO v_authorized_scope FROM public.team_get_user_subtree(v_caller_id);
        IF NOT (p_team_id = ANY(v_authorized_scope)) THEN
            RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN_SCOPE', 'error', 'Target team is outside your managed subtree');
        END IF;
        IF v_old_team_id IS NOT NULL AND NOT (v_old_team_id = ANY(v_authorized_scope)) THEN
            RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN_SCOPE', 'error', 'Source team is outside your managed subtree');
        END IF;
    END IF;

    -- Perform Assignment
    INSERT INTO public.team_members (team_id, user_id)
    VALUES (p_team_id, p_user_id)
    ON CONFLICT (user_id) DO UPDATE SET team_id = p_team_id, joined_at = NOW();

    -- Audit Log
    INSERT INTO public.audit_logs_crm (
        actor_id, action, table_name, record_id, old_data, new_data
    ) VALUES (
        v_caller_id,
        'ASSIGN_TEAM_MEMBER',
        'team_members',
        p_user_id,
        jsonb_build_object('old_team_id', v_old_team_id),
        jsonb_build_object(
            'new_team_id', p_team_id,
            'user_id', p_user_id,
            'reason', p_reason,
            'request_id', p_request_id
        )
    );

    RETURN jsonb_build_object('success', true, 'message', 'User assigned to team successfully');
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'code', SQLSTATE, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_remove_team_member(p_user_id uuid, p_caller_id uuid DEFAULT NULL::uuid, p_team_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_caller_id UUID;
    v_caller_role TEXT;
    v_old_team_id UUID;
    v_authorized_scope UUID[];
BEGIN
    v_caller_id := p_caller_id;
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'UNAUTHENTICATED', 'error', 'Caller ID required');
    END IF;

    SELECT role::text INTO v_caller_role FROM public.user_profiles WHERE id = v_caller_id;
    IF v_caller_role NOT IN ('admin', 'super_admin', 'relationship_manager') THEN
        RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN_SCOPE', 'error', 'Unauthorized access');
    END IF;

    SELECT team_id INTO v_old_team_id FROM public.team_members WHERE user_id = p_user_id;
    IF v_old_team_id IS NULL THEN
        RETURN jsonb_build_object('success', true, 'message', 'User is not currently assigned to any team');
    END IF;

    -- Subtree Scope Check for Relationship Managers
    IF v_caller_role = 'relationship_manager' THEN
        SELECT ARRAY_AGG(team_id) INTO v_authorized_scope FROM public.team_get_user_subtree(v_caller_id);
        IF NOT (v_old_team_id = ANY(v_authorized_scope)) THEN
            RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN_SCOPE', 'error', 'Member is outside your managed subtree');
        END IF;
    END IF;

    DELETE FROM public.team_members WHERE user_id = p_user_id;

    -- Clear lead status ONLY for the team from which user is being removed
    UPDATE public.teams SET team_lead_id = NULL WHERE id = v_old_team_id AND team_lead_id = p_user_id;

    -- Audit Log
    INSERT INTO public.audit_logs_crm (
        actor_id, action, table_name, record_id, old_data, new_data
    ) VALUES (
        v_caller_id,
        'REMOVE_TEAM_MEMBER',
        'team_members',
        p_user_id,
        jsonb_build_object('removed_from_team_id', v_old_team_id),
        jsonb_build_object('reason', p_reason, 'request_id', p_request_id)
    );

    RETURN jsonb_build_object('success', true, 'message', 'User removed from team successfully');
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'code', SQLSTATE, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_deactivate_team(p_team_id uuid, p_expected_version integer DEFAULT NULL::integer, p_caller_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text, p_request_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_caller_id UUID;
    v_caller_role TEXT;
    v_curr_team RECORD;
    v_active_children_count INT;
    v_active_members_count INT;
BEGIN
    v_caller_id := p_caller_id;
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'UNAUTHENTICATED', 'error', 'Caller ID required');
    END IF;

    SELECT role::text INTO v_caller_role FROM public.user_profiles WHERE id = v_caller_id;
    IF v_caller_role NOT IN ('admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN_SCOPE', 'error', 'Only admins can deactivate teams');
    END IF;

    SELECT * INTO v_curr_team FROM public.teams WHERE id = p_team_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'code', 'TEAM_NOT_FOUND', 'error', 'Team not found');
    END IF;

    IF NOT v_curr_team.is_active THEN
        RETURN jsonb_build_object('success', true, 'message', 'Team is already inactive');
    END IF;

    -- Concurrency check
    IF p_expected_version IS NOT NULL AND v_curr_team.version != p_expected_version THEN
        RETURN jsonb_build_object(
            'success', false,
            'code', 'VERSION_CONFLICT',
            'error', 'Team version conflict. Refresh and try again.'
        );
    END IF;

    -- Reject if active child teams exist
    SELECT COUNT(*) INTO v_active_children_count FROM public.teams WHERE parent_team_id = p_team_id AND is_active = true;
    IF v_active_children_count > 0 THEN
        RETURN jsonb_build_object(
            'success', false,
            'code', 'TEAM_HAS_CHILDREN',
            'error', 'Cannot deactivate team with ' || v_active_children_count || ' active child team(s). Reassign or deactivate children first.'
        );
    END IF;

    -- Deactivate team
    UPDATE public.teams
    SET is_active = false,
        version = version + 1,
        updated_at = NOW()
    WHERE id = p_team_id;

    -- Remove members from team_members
    SELECT COUNT(*) INTO v_active_members_count FROM public.team_members WHERE team_id = p_team_id;
    DELETE FROM public.team_members WHERE team_id = p_team_id;

    -- Clear lead
    UPDATE public.teams SET team_lead_id = NULL WHERE id = p_team_id;

    -- Audit Log
    INSERT INTO public.audit_logs_crm (
        actor_id, action, table_name, record_id, old_data, new_data
    ) VALUES (
        v_caller_id,
        'DEACTIVATE_TEAM',
        'teams',
        p_team_id,
        to_jsonb(v_curr_team),
        jsonb_build_object(
            'removed_members_count', v_active_members_count,
            'reason', p_reason,
            'request_id', p_request_id
        )
    );

    RETURN jsonb_build_object('success', true, 'message', 'Team deactivated successfully');
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'code', SQLSTATE, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.award_team_incentive(p_team_id uuid, p_incentive_type text, p_allocation_mode text, p_input_amount_paise bigint, p_include_lead boolean DEFAULT true, p_description text DEFAULT NULL::text, p_internal_note text DEFAULT NULL::text, p_effective_date date DEFAULT CURRENT_DATE, p_payroll_month integer DEFAULT NULL::integer, p_payroll_year integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text, p_caller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_actor_id UUID;
    v_actor_role TEXT;
    v_actor_name TEXT;
    v_team_name TEXT;
    v_team_lead_id UUID;
    v_team_active BOOLEAN;
    v_existing_batch_id UUID;
    v_batch_id UUID;
    v_eligible_count INT := 0;
    v_excluded_count INT := 0;
    v_member_record RECORD;
    v_per_person_paise BIGINT := 0;
    v_total_cost_paise BIGINT := 0;
    v_remainder_paise BIGINT := 0;
    v_alloc_amount_paise BIGINT := 0;
    v_member_idx INT := 0;
BEGIN
    -- Authenticate & Authorize caller
    v_actor_id := COALESCE(p_caller_id, auth.uid());
    IF v_actor_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'UNAUTHORIZED', 'error', 'Authentication required');
    END IF;

    SELECT role::text, full_name INTO v_actor_role, v_actor_name
    FROM public.user_profiles
    WHERE id = v_actor_id;

    IF v_actor_role NOT IN ('hr_manager', 'admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN', 'error', 'HR permissions required');
    END IF;

    -- Idempotency check
    IF p_idempotency_key IS NOT NULL THEN
        SELECT id INTO v_existing_batch_id
        FROM public.incentive_batches
        WHERE created_by = v_actor_id AND idempotency_key = p_idempotency_key;

        IF v_existing_batch_id IS NOT NULL THEN
            RETURN jsonb_build_object('success', true, 'code', 'DUPLICATE_IDEMPOTENT', 'batch_id', v_existing_batch_id);
        END IF;
    END IF;

    -- Lock team row
    SELECT name, team_lead_id, is_active INTO v_team_name, v_team_lead_id, v_team_active
    FROM public.teams
    WHERE id = p_team_id
    FOR SHARE;

    IF v_team_name IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'TEAM_NOT_FOUND', 'error', 'Target team does not exist');
    END IF;

    IF NOT v_team_active THEN
        RETURN jsonb_build_object('success', false, 'code', 'TEAM_INACTIVE', 'error', 'Target team is inactive');
    END IF;

    -- Validate input amount
    IF p_input_amount_paise <= 0 OR p_input_amount_paise > 1000000000 THEN
        RETURN jsonb_build_object('success', false, 'code', 'AMOUNT_OUT_OF_RANGE', 'error', 'Amount out of allowed policy range');
    END IF;

    -- Count eligible / excluded members
    FOR v_member_record IN (
        SELECT up.id, up.full_name, up.employee_id AS emp_code, up.is_suspended
        FROM public.team_members tm
        JOIN public.user_profiles up ON up.id = tm.user_id
        WHERE tm.team_id = p_team_id
        ORDER BY up.id ASC
    ) LOOP
        IF v_member_record.is_suspended THEN
            v_excluded_count := v_excluded_count + 1;
        ELSIF NOT p_include_lead AND v_member_record.id = v_team_lead_id THEN
            v_excluded_count := v_excluded_count + 1;
        ELSE
            v_eligible_count := v_eligible_count + 1;
        END IF;
    END LOOP;

    IF v_eligible_count = 0 THEN
        RETURN jsonb_build_object('success', false, 'code', 'NO_ELIGIBLE_MEMBERS', 'error', 'Team has no active eligible members');
    END IF;

    -- Calculate allocations & total pool paise exact division
    IF p_allocation_mode = 'per_person' THEN
        v_per_person_paise := p_input_amount_paise;
        v_total_cost_paise := p_input_amount_paise * v_eligible_count;
    ELSIF p_allocation_mode = 'total_pool' THEN
        v_total_cost_paise := p_input_amount_paise;
        v_per_person_paise := p_input_amount_paise / v_eligible_count;
        v_remainder_paise := p_input_amount_paise % v_eligible_count;
    ELSE
        RETURN jsonb_build_object('success', false, 'code', 'INVALID_ALLOCATION_MODE', 'error', 'Invalid allocation mode');
    END IF;

    -- Insert Batch
    INSERT INTO public.incentive_batches (
        recipient_mode, team_id, team_name_snapshot, allocation_mode, incentive_type,
        description, internal_note, effective_date, payroll_month, payroll_year,
        total_amount_paise, per_person_amount_paise, eligible_member_count, excluded_member_count,
        status, created_by, idempotency_key
    ) VALUES (
        'team', p_team_id, v_team_name, p_allocation_mode, p_incentive_type,
        p_description, p_internal_note, COALESCE(p_effective_date, CURRENT_DATE), p_payroll_month, p_payroll_year,
        v_total_cost_paise, v_per_person_paise, v_eligible_count, v_excluded_count,
        'pending', v_actor_id, p_idempotency_key
    )
    RETURNING id INTO v_batch_id;

    -- Create allocations for eligible members
    FOR v_member_record IN (
        SELECT up.id, up.full_name, up.employee_id AS emp_code, up.is_suspended
        FROM public.team_members tm
        JOIN public.user_profiles up ON up.id = tm.user_id
        WHERE tm.team_id = p_team_id
        ORDER BY up.id ASC
    ) LOOP
        IF NOT v_member_record.is_suspended AND (p_include_lead OR v_member_record.id != v_team_lead_id) THEN
            v_member_idx := v_member_idx + 1;
            v_alloc_amount_paise := v_per_person_paise;

            -- Distribute remainder deterministically to first N members by sorted UUID
            IF p_allocation_mode = 'total_pool' AND v_member_idx <= v_remainder_paise THEN
                v_alloc_amount_paise := v_alloc_amount_paise + 1;
            END IF;

            INSERT INTO public.incentive_allocations (
                batch_id, employee_id, employee_name_snapshot, employee_code_snapshot,
                team_id_snapshot, team_name_snapshot, amount_paise, status
            ) VALUES (
                v_batch_id, v_member_record.id, v_member_record.full_name, v_member_record.emp_code,
                p_team_id, v_team_name, v_alloc_amount_paise, 'pending'
            );

            -- Employee notification
            INSERT INTO public.notifications (
                user_id, title, body, type, reference_id, reference_type
            ) VALUES (
                v_member_record.id, 'Team Incentive Awarded',
                format('Your team (%s) received a bonus award of ₹%s.', v_team_name, (v_alloc_amount_paise::numeric / 100.0)::text),
                'info', v_batch_id, 'incentive_batch'
            );
        END IF;
    END LOOP;

    -- Write Batch Audit Log
    INSERT INTO public.audit_logs_hrm (
        actor_id, actor_name, action, table_name, record_id,
        new_data, module, severity
    ) VALUES (
        v_actor_id, COALESCE(v_actor_name, 'HR Manager'), 'CREATE_TEAM_INCENTIVE', 'incentive_batches', v_batch_id,
        jsonb_build_object('batch_id', v_batch_id, 'team_id', p_team_id, 'total_cost_paise', v_total_cost_paise, 'eligible_count', v_eligible_count),
        'Incentives', 'high'
    );

    RETURN jsonb_build_object(
        'success', true,
        'batch_id', v_batch_id,
        'eligible_count', v_eligible_count,
        'excluded_count', v_excluded_count,
        'total_cost_paise', v_total_cost_paise
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.transition_incentive_batch(p_batch_id uuid, p_target_action text, p_expected_status text, p_expected_version integer, p_reason text DEFAULT NULL::text, p_caller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_actor_id UUID;
    v_actor_role TEXT;
    v_actor_name TEXT;
    v_batch RECORD;
    v_new_status TEXT;
    v_high_value BOOLEAN;
BEGIN
    -- Authenticate caller
    v_actor_id := COALESCE(p_caller_id, auth.uid());
    IF v_actor_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'UNAUTHORIZED', 'error', 'Authentication required');
    END IF;

    SELECT role::text, full_name INTO v_actor_role, v_actor_name
    FROM public.user_profiles
    WHERE id = v_actor_id;

    IF v_actor_role NOT IN ('hr_manager', 'admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN', 'error', 'Privileged role required');
    END IF;

    -- Lock batch row
    SELECT * INTO v_batch
    FROM public.incentive_batches
    WHERE id = p_batch_id
    FOR UPDATE;

    IF v_batch.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'BATCH_NOT_FOUND', 'error', 'Incentive batch not found');
    END IF;

    -- Verify status & optimistic version
    IF v_batch.status != p_expected_status THEN
        RETURN jsonb_build_object('success', false, 'code', 'STATUS_CONFLICT', 'error', format('Batch status is %s, expected %s', v_batch.status, p_expected_status));
    END IF;

    IF v_batch.version != p_expected_version THEN
        RETURN jsonb_build_object('success', false, 'code', 'VERSION_CONFLICT', 'error', format('Batch version is %s, expected %s', v_batch.version, p_expected_version));
    END IF;

    v_high_value := (v_batch.total_amount_paise > 10000000); -- > ₹1,00,000

    -- Action state machine logic
    CASE p_target_action
        WHEN 'approve' THEN
            IF v_batch.status != 'pending' THEN
                RETURN jsonb_build_object('success', false, 'code', 'INVALID_TRANSITION', 'error', 'Only pending awards can be approved');
            END IF;
            -- Maker-Checker enforcement: Creator cannot approve their own high-value award unless admin/super_admin
            IF v_batch.created_by = v_actor_id AND v_high_value AND v_actor_role NOT IN ('admin', 'super_admin') THEN
                RETURN jsonb_build_object('success', false, 'code', 'MAKER_CHECKER_VIOLATION', 'error', 'Creator cannot approve self-awarded high-value incentive');
            END IF;
            v_new_status := 'approved';

            UPDATE public.incentive_batches
            SET status = v_new_status, approved_by = v_actor_id, approved_at = now(), version = version + 1, updated_at = now()
            WHERE id = p_batch_id;

        WHEN 'reject' THEN
            IF v_batch.status != 'pending' THEN
                RETURN jsonb_build_object('success', false, 'code', 'INVALID_TRANSITION', 'error', 'Only pending awards can be rejected');
            END IF;
            IF p_reason IS NULL OR length(trim(p_reason)) < 3 THEN
                RETURN jsonb_build_object('success', false, 'code', 'REASON_REQUIRED', 'error', 'Reason is required for rejection');
            END IF;
            v_new_status := 'rejected';

            UPDATE public.incentive_batches
            SET status = v_new_status, rejected_by = v_actor_id, rejected_at = now(), rejection_reason = p_reason, version = version + 1, updated_at = now()
            WHERE id = p_batch_id;

        WHEN 'cancel' THEN
            IF v_batch.status NOT IN ('pending', 'approved') THEN
                RETURN jsonb_build_object('success', false, 'code', 'INVALID_TRANSITION', 'error', 'Paid/reversed awards cannot be cancelled');
            END IF;
            IF p_reason IS NULL OR length(trim(p_reason)) < 3 THEN
                RETURN jsonb_build_object('success', false, 'code', 'REASON_REQUIRED', 'error', 'Reason is required for cancellation');
            END IF;
            v_new_status := 'cancelled';

            UPDATE public.incentive_batches
            SET status = v_new_status, cancelled_by = v_actor_id, cancelled_at = now(), cancellation_reason = p_reason, version = version + 1, updated_at = now()
            WHERE id = p_batch_id;

        WHEN 'mark_paid' THEN
            IF v_batch.status != 'approved' THEN
                RETURN jsonb_build_object('success', false, 'code', 'INVALID_TRANSITION', 'error', 'Only approved awards can be marked paid');
            END IF;
            v_new_status := 'paid';

            UPDATE public.incentive_batches
            SET status = v_new_status, paid_by = v_actor_id, paid_at = now(), version = version + 1, updated_at = now()
            WHERE id = p_batch_id;

        WHEN 'reverse' THEN
            IF v_batch.status != 'paid' THEN
                RETURN jsonb_build_object('success', false, 'code', 'INVALID_TRANSITION', 'error', 'Only paid awards can be reversed');
            END IF;
            IF v_actor_role NOT IN ('admin', 'super_admin') THEN
                RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN', 'error', 'Only Admins can reverse paid financial awards');
            END IF;
            IF p_reason IS NULL OR length(trim(p_reason)) < 3 THEN
                RETURN jsonb_build_object('success', false, 'code', 'REASON_REQUIRED', 'error', 'Reason is required for reversal');
            END IF;
            v_new_status := 'reversed';

            UPDATE public.incentive_batches
            SET status = v_new_status, reversed_by = v_actor_id, reversed_at = now(), reversal_reason = p_reason, version = version + 1, updated_at = now()
            WHERE id = p_batch_id;

        ELSE
            RETURN jsonb_build_object('success', false, 'code', 'INVALID_ACTION', 'error', 'Unknown action');
    END CASE;

    -- Synchronize status to all child allocations
    UPDATE public.incentive_allocations
    SET status = v_new_status,
        paid_at = CASE WHEN v_new_status = 'paid' THEN now() ELSE paid_at END,
        updated_at = now()
    WHERE batch_id = p_batch_id;

    -- Audit Log
    INSERT INTO public.audit_logs_hrm (
        actor_id, actor_name, action, table_name, record_id,
        old_data, new_data, module, severity
    ) VALUES (
        v_actor_id, COALESCE(v_actor_name, 'HR Actor'), upper(p_target_action), 'incentive_batches', p_batch_id,
        jsonb_build_object('status', v_batch.status, 'version', v_batch.version),
        jsonb_build_object('status', v_new_status, 'version', v_batch.version + 1, 'reason', p_reason),
        'Incentives', 'high'
    );

    RETURN jsonb_build_object('success', true, 'batch_id', p_batch_id, 'new_status', v_new_status, 'version', v_batch.version + 1);
END;
$function$

CREATE OR REPLACE FUNCTION public.preview_team_incentive(p_team_id uuid, p_allocation_mode text, p_input_amount_paise bigint, p_include_lead boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_team_name TEXT;
    v_team_lead_id UUID;
    v_team_active BOOLEAN;
    v_eligible_count INT := 0;
    v_excluded_count INT := 0;
    v_member_record RECORD;
    v_eligible_list JSONB := '[]'::jsonb;
    v_excluded_list JSONB := '[]'::jsonb;
    v_per_person_paise BIGINT := 0;
    v_total_cost_paise BIGINT := 0;
    v_remainder_paise BIGINT := 0;
BEGIN
    SELECT name, team_lead_id, is_active INTO v_team_name, v_team_lead_id, v_team_active
    FROM public.teams
    WHERE id = p_team_id;

    IF v_team_name IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'TEAM_NOT_FOUND', 'error', 'Target team does not exist');
    END IF;

    IF NOT v_team_active THEN
        RETURN jsonb_build_object('success', false, 'code', 'TEAM_INACTIVE', 'error', 'Target team is inactive');
    END IF;

    -- Loop over members joining team_members and user_profiles
    FOR v_member_record IN (
        SELECT up.id, up.full_name, up.employee_id AS emp_code, up.role::text, up.is_suspended
        FROM public.team_members tm
        JOIN public.user_profiles up ON up.id = tm.user_id
        WHERE tm.team_id = p_team_id
        ORDER BY up.id ASC
    ) LOOP
        IF v_member_record.is_suspended THEN
            v_excluded_count := v_excluded_count + 1;
            v_excluded_list := v_excluded_list || jsonb_build_object('id', v_member_record.id, 'name', v_member_record.full_name, 'reason', 'Suspended');
        ELSIF NOT p_include_lead AND v_member_record.id = v_team_lead_id THEN
            v_excluded_count := v_excluded_count + 1;
            v_excluded_list := v_excluded_list || jsonb_build_object('id', v_member_record.id, 'name', v_member_record.full_name, 'reason', 'Excluded Team Lead');
        ELSE
            v_eligible_count := v_eligible_count + 1;
            v_eligible_list := v_eligible_list || jsonb_build_object('id', v_member_record.id, 'name', v_member_record.full_name, 'code', v_member_record.emp_code);
        END IF;
    END LOOP;

    IF v_eligible_count = 0 THEN
        RETURN jsonb_build_object('success', false, 'code', 'NO_ELIGIBLE_MEMBERS', 'error', 'Team has no active eligible members');
    END IF;

    IF p_allocation_mode = 'per_person' THEN
        v_per_person_paise := p_input_amount_paise;
        v_total_cost_paise := p_input_amount_paise * v_eligible_count;
    ELSIF p_allocation_mode = 'total_pool' THEN
        v_total_cost_paise := p_input_amount_paise;
        v_per_person_paise := p_input_amount_paise / v_eligible_count;
        v_remainder_paise := p_input_amount_paise % v_eligible_count;
    ELSE
        RETURN jsonb_build_object('success', false, 'code', 'INVALID_ALLOCATION_MODE', 'error', 'Invalid allocation mode');
    END IF;

    RETURN jsonb_build_object(
        'success', true,
        'team_id', p_team_id,
        'team_name', v_team_name,
        'allocation_mode', p_allocation_mode,
        'eligible_count', v_eligible_count,
        'excluded_count', v_excluded_count,
        'per_person_amount_paise', v_per_person_paise,
        'total_cost_paise', v_total_cost_paise,
        'remainder_paise', v_remainder_paise,
        'eligible_members', v_eligible_list,
        'excluded_members', v_excluded_list
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.clock_in_attendance(p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric, p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_actor_id uuid;
    v_user_role text;
    v_policy record;
    v_now timestamptz := now();
    v_work_date date;
    v_existing record;
    v_dist_meters numeric;
    v_is_onsite boolean := false;
    v_location_status text := 'offsite';
    v_status text := 'present';
    v_record record;
BEGIN
    v_actor_id := COALESCE(p_employee_id, auth.uid());
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized call: No authenticated user or employee_id provided.';
    END IF;

    -- Check internal active role
    SELECT role::text INTO v_user_role FROM public.user_profiles WHERE id = v_actor_id;
    IF v_user_role IS NULL THEN
        RAISE EXCEPTION 'User profile not found';
    END IF;

    -- Load policy
    SELECT * INTO v_policy FROM public.organization_policy LIMIT 1;
    IF v_policy.id IS NULL THEN
        RAISE EXCEPTION 'Organization policy not configured';
    END IF;

    -- Compute local business work date in configured timezone
    v_work_date := (v_now AT TIME ZONE v_policy.timezone)::date;

    -- Check for an open shift for this employee
    SELECT * INTO v_existing FROM public.attendance 
    WHERE employee_id = v_actor_id AND check_out IS NULL 
    LIMIT 1;

    IF v_existing.id IS NOT NULL THEN
        IF v_existing.work_date = v_work_date THEN
            RETURN jsonb_build_object('success', true, 'record', row_to_json(v_existing), 'idempotent', true);
        ELSE
            -- Auto-close previous stale shift
            UPDATE public.attendance
            SET 
                check_out = v_existing.check_in + interval '9 hours',
                closure_source = 'automatic',
                closure_reason = 'Previous shift left open; auto-closed on new clock-in',
                needs_review = true,
                updated_at = v_now
            WHERE id = v_existing.id;

            INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, old_data, new_data, module, severity)
            VALUES (
                v_actor_id, 'Stale shift auto-closed', 'attendance', v_existing.id,
                jsonb_build_object('check_out', v_existing.check_out),
                jsonb_build_object('check_out', v_existing.check_in + interval '9 hours', 'closure_source', 'automatic'),
                'Attendance', 'medium'
            );
        END IF;
    END IF;

    -- Check if shift for today was already completed
    SELECT * INTO v_existing FROM public.attendance 
    WHERE employee_id = v_actor_id AND work_date = v_work_date AND check_out IS NOT NULL 
    LIMIT 1;

    IF v_existing.id IS NOT NULL THEN
        RAISE EXCEPTION 'Shift for % has already been completed.', v_work_date;
    END IF;

    -- Server-side distance computation for on-site geofencing
    IF p_lat IS NOT NULL AND p_lng IS NOT NULL AND v_policy.office_lat IS NOT NULL AND v_policy.office_lng IS NOT NULL THEN
        v_dist_meters := 6371000 * acos(
            cos(radians(v_policy.office_lat)) * cos(radians(p_lat)) *
            cos(radians(p_lng) - radians(v_policy.office_lng)) +
            sin(radians(v_policy.office_lat)) * sin(radians(p_lat))
        );

        IF v_dist_meters <= v_policy.geofence_radius_meters THEN
            v_is_onsite := true;
            v_location_status := 'onsite';
        ELSE
            v_is_onsite := false;
            v_location_status := 'offsite';
        END IF;
    ELSE
        v_location_status := 'no_gps';
    END IF;

    IF v_policy.geofence_required AND NOT v_is_onsite THEN
        RAISE EXCEPTION 'Clock-in rejected: On-site geofence validation required.';
    END IF;

    -- Late calculation
    IF (v_now AT TIME ZONE v_policy.timezone)::time > (v_policy.standard_start_time + (v_policy.grace_minutes || ' minutes')::interval) THEN
        v_status := 'late';
    ELSE
        v_status := 'present';
    END IF;

    -- Insert attendance record
    INSERT INTO public.attendance (
        employee_id, date, work_date, check_in, status,
        check_in_lat, check_in_lng, is_onsite,
        check_in_location_status, closure_source
    ) VALUES (
        v_actor_id, v_work_date, v_work_date, v_now, v_status,
        p_lat, p_lng, v_is_onsite,
        v_location_status, 'employee'
    ) RETURNING * INTO v_record;

    INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, new_data, module, severity)
    VALUES (
        v_actor_id, 'Clocked in', 'attendance', v_record.id,
        jsonb_build_object('work_date', v_work_date, 'check_in', v_now, 'status', v_status, 'is_onsite', v_is_onsite),
        'Attendance', 'low'
    );

    RETURN jsonb_build_object('success', true, 'record', row_to_json(v_record));
END;
$function$

CREATE OR REPLACE FUNCTION public.clock_out_attendance(p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric, p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_actor_id uuid;
    v_policy record;
    v_now timestamptz := now();
    v_existing record;
    v_dist_meters numeric;
    v_location_status text := 'offsite';
    v_record record;
BEGIN
    v_actor_id := COALESCE(p_employee_id, auth.uid());
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized call: No authenticated user or employee_id provided.';
    END IF;

    SELECT * INTO v_existing FROM public.attendance 
    WHERE employee_id = v_actor_id AND check_out IS NULL 
    LIMIT 1;

    IF v_existing.id IS NULL THEN
        SELECT * INTO v_existing FROM public.attendance 
        WHERE employee_id = v_actor_id AND work_date = ((v_now AT TIME ZONE 'Asia/Kolkata')::date) AND check_out IS NOT NULL 
        LIMIT 1;

        IF v_existing.id IS NOT NULL THEN
            RETURN jsonb_build_object('success', true, 'record', row_to_json(v_existing), 'idempotent', true);
        END IF;

        RAISE EXCEPTION 'No active open shift found to clock out.';
    END IF;

    SELECT * INTO v_policy FROM public.organization_policy LIMIT 1;
    IF p_lat IS NOT NULL AND p_lng IS NOT NULL AND v_policy.office_lat IS NOT NULL AND v_policy.office_lng IS NOT NULL THEN
        v_dist_meters := 6371000 * acos(
            cos(radians(v_policy.office_lat)) * cos(radians(p_lat)) *
            cos(radians(p_lng) - radians(v_policy.office_lng)) +
            sin(radians(v_policy.office_lat)) * sin(radians(p_lat))
        );
        IF v_dist_meters <= v_policy.geofence_radius_meters THEN
            v_location_status := 'onsite';
        ELSE
            v_location_status := 'offsite';
        END IF;
    ELSE
        v_location_status := 'no_gps';
    END IF;

    UPDATE public.attendance
    SET 
        check_out = v_now,
        check_out_lat = p_lat,
        check_out_lng = p_lng,
        check_out_location_status = v_location_status,
        updated_at = v_now
    WHERE id = v_existing.id
    RETURNING * INTO v_record;

    INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, old_data, new_data, module, severity)
    VALUES (
        v_actor_id, 'Clocked out', 'attendance', v_record.id,
        jsonb_build_object('check_in', v_existing.check_in),
        jsonb_build_object('check_out', v_now, 'duration_minutes', EXTRACT(EPOCH FROM (v_now - v_existing.check_in))/60),
        'Attendance', 'low'
    );

    RETURN jsonb_build_object('success', true, 'record', row_to_json(v_record));
END;
$function$

CREATE OR REPLACE FUNCTION public.review_leave_request(p_request_id uuid, p_action text, p_note text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_actor_id uuid;
    v_actor_role text;
    v_request record;
    v_balance record;
    v_chargeable numeric(5,2);
    v_updated record;
BEGIN
    v_actor_id := COALESCE(p_actor_id, auth.uid());
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized call';
    END IF;

    SELECT role::text INTO v_actor_role FROM public.user_profiles WHERE id = v_actor_id;
    IF v_actor_role NOT IN ('hr_manager', 'admin', 'super_admin') THEN
        RAISE EXCEPTION 'Forbidden: Only HR managers or Admins can review leave requests';
    END IF;

    IF p_action NOT IN ('approved', 'rejected') THEN
        RAISE EXCEPTION 'Invalid review action: %. Must be approved or rejected.', p_action;
    END IF;

    SELECT * INTO v_request FROM public.leave_requests WHERE id = p_request_id FOR UPDATE;
    IF v_request.id IS NULL THEN
        RAISE EXCEPTION 'Leave request not found';
    END IF;

    IF v_request.status != 'pending' THEN
        RAISE EXCEPTION 'Conflict: Leave request has already been processed (status: %).', v_request.status;
    END IF;

    v_chargeable := COALESCE(v_request.chargeable_days, 1);

    IF v_request.leave_type IN ('casual', 'sick', 'earned') THEN
        SELECT * INTO v_balance 
        FROM public.employee_leave_balances 
        WHERE employee_id = v_request.employee_id 
          AND policy_year = COALESCE(v_request.policy_year, EXTRACT(YEAR FROM v_request.from_date)::int)
          AND leave_type = v_request.leave_type
        FOR UPDATE;

        IF v_balance.id IS NOT NULL THEN
            IF p_action = 'approved' THEN
                UPDATE public.employee_leave_balances
                SET 
                    reserved_days = GREATEST(0, reserved_days - v_chargeable),
                    used_days = used_days + v_chargeable,
                    version = version + 1,
                    updated_at = now()
                WHERE id = v_balance.id;
            ELSE
                UPDATE public.employee_leave_balances
                SET 
                    reserved_days = GREATEST(0, reserved_days - v_chargeable),
                    version = version + 1,
                    updated_at = now()
                WHERE id = v_balance.id;
            END IF;
        END IF;
    END IF;

    UPDATE public.leave_requests
    SET 
        status = p_action,
        reviewed_by = v_actor_id,
        review_note = p_note,
        reviewed_at = now(),
        updated_at = now()
    WHERE id = p_request_id
    RETURNING * INTO v_updated;

    INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, old_data, new_data, module, severity)
    VALUES (
        v_actor_id, 'Leave request reviewed', 'leave_requests', p_request_id,
        jsonb_build_object('status', 'pending'),
        jsonb_build_object('status', p_action, 'review_note', p_note, 'reviewed_by', v_actor_id),
        'Leaves', 'medium'
    );

    RETURN jsonb_build_object('success', true, 'request', row_to_json(v_updated));
END;
$function$

CREATE OR REPLACE FUNCTION public.hr_override_attendance(p_attendance_id uuid, p_status text, p_reason text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_actor_id uuid;
    v_actor_role text;
    v_existing record;
    v_updated record;
BEGIN
    v_actor_id := COALESCE(p_actor_id, auth.uid());
    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized call';
    END IF;

    SELECT role::text INTO v_actor_role FROM public.user_profiles WHERE id = v_actor_id;
    IF v_actor_role NOT IN ('hr_manager', 'admin', 'super_admin') THEN
        RAISE EXCEPTION 'Forbidden: Only HR or Admins can override attendance';
    END IF;

    IF p_reason IS NULL OR TRIM(p_reason) = '' THEN
        RAISE EXCEPTION 'Override reason is required for audit trail.';
    END IF;

    SELECT * INTO v_existing FROM public.attendance WHERE id = p_attendance_id FOR UPDATE;
    IF v_existing.id IS NULL THEN
        RAISE EXCEPTION 'Attendance record not found';
    END IF;

    UPDATE public.attendance
    SET 
        status = p_status,
        override_by = v_actor_id,
        override_reason = p_reason,
        needs_review = false,
        updated_at = now()
    WHERE id = p_attendance_id
    RETURNING * INTO v_updated;

    INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, old_data, new_data, module, severity)
    VALUES (
        v_actor_id, 'Attendance overridden', 'attendance', p_attendance_id,
        jsonb_build_object('status', v_existing.status),
        jsonb_build_object('status', p_status, 'override_reason', p_reason, 'override_by', v_actor_id),
        'Attendance', 'medium'
    );

    RETURN jsonb_build_object('success', true, 'record', row_to_json(v_updated));
END;
$function$

CREATE OR REPLACE FUNCTION public.recalculate_user_tier(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_tree_size INTEGER;
    v_active_downline INTEGER;
    v_current_tier TEXT;
    v_new_tier TEXT;
    v_tier_config RECORD;
    v_bonus_multiplier NUMERIC;
    v_tier_order TEXT[] := ARRAY['bronze', 'silver', 'gold', 'platinum'];
    v_current_tier_index INTEGER;
    v_qualifying_tier TEXT := 'bronze';
    v_qualifying_index INTEGER := 0;
    v_highest_qualifying_index INTEGER := 0;
    v_notification_body TEXT;
BEGIN
    -- 1. Read current stats from reward_points_balance
    SELECT tree_size, active_downline, tier
    INTO v_tree_size, v_active_downline, v_current_tier
    FROM public.reward_points_balance
    WHERE user_id = p_user_id;

    -- If no balance row exists, return early
    IF NOT FOUND THEN
        RETURN jsonb_build_object('upgraded', false, 'old_tier', NULL, 'new_tier', NULL);
    END IF;

    -- 2. Evaluate tiers in descending order (platinum → gold → silver → bronze)
    FOR v_tier_config IN
        SELECT config_key, config_value
        FROM public.reward_configuration
        WHERE config_key IN ('tier_platinum', 'tier_gold', 'tier_silver', 'tier_bronze')
          AND is_active = true
        ORDER BY
            CASE config_key
                WHEN 'tier_platinum' THEN 4
                WHEN 'tier_gold' THEN 3
                WHEN 'tier_silver' THEN 2
                WHEN 'tier_bronze' THEN 1
            END DESC
    LOOP
        DECLARE
            v_min_tree_size INTEGER := COALESCE((v_tier_config.config_value->>'min_tree_size')::INTEGER, 0);
            v_min_active_referrals INTEGER := COALESCE((v_tier_config.config_value->>'min_active_referrals')::INTEGER, 0);
            v_tier_name TEXT := REPLACE(v_tier_config.config_key, 'tier_', '');
            v_tier_idx INTEGER;
        BEGIN
            -- Check if user qualifies
            IF v_tree_size >= v_min_tree_size AND v_active_downline >= v_min_active_referrals THEN
                -- Find index in tier_order array
                v_tier_idx := array_position(v_tier_order, v_tier_name);
                IF v_tier_idx IS NOT NULL AND v_tier_idx - 1 > v_highest_qualifying_index THEN
                    v_highest_qualifying_index := v_tier_idx - 1;
                    v_qualifying_tier := v_tier_name;
                END IF;
            END IF;
        END;
    END LOOP;

    -- 3. No-downgrade guard: new tier = max(current, qualifying)
    v_current_tier_index := COALESCE(array_position(v_tier_order, v_current_tier), 1) - 1;
    v_qualifying_index := array_position(v_tier_order, v_qualifying_tier);
    IF v_qualifying_index IS NULL THEN
        v_qualifying_index := 1; -- default to bronze (index 0)
    ELSE
        v_qualifying_index := v_qualifying_index - 1;
    END IF;

    v_new_tier := v_tier_order[GREATEST(v_current_tier_index, v_qualifying_index) + 1];

    -- 4. If no change, return early
    IF v_new_tier = v_current_tier THEN
        RETURN jsonb_build_object('upgraded', false, 'old_tier', v_current_tier, 'new_tier', v_new_tier);
    END IF;

    -- 5. Fetch bonus_multiplier from the new tier's config
    SELECT (config_value->>'bonus_multiplier')::NUMERIC
    INTO v_bonus_multiplier
    FROM public.reward_configuration
    WHERE config_key = 'tier_' || v_new_tier AND is_active = true;

    -- 6. Update reward_points_balance
    UPDATE public.reward_points_balance
    SET tier = v_new_tier,
        updated_at = now()
    WHERE user_id = p_user_id;

    -- 7. Update user_profiles
    UPDATE public.user_profiles
    SET reward_tier = v_new_tier,
        updated_at = now()
    WHERE id = p_user_id;

    -- 8. Build notification body with multiplier
    v_notification_body := CASE v_new_tier
        WHEN 'silver' THEN '🎉 You''ve been promoted to Silver tier! Enjoy a ' || COALESCE(v_bonus_multiplier, 1.2)::TEXT || '× bonus multiplier on all future rewards.'
        WHEN 'gold' THEN '🎉 You''ve been promoted to Gold tier! Enjoy a ' || COALESCE(v_bonus_multiplier, 1.5)::TEXT || '× bonus multiplier on all future rewards.'
        WHEN 'platinum' THEN '🎉 You''ve been promoted to Platinum tier! Enjoy a ' || COALESCE(v_bonus_multiplier, 2.0)::TEXT || '× bonus multiplier on all future rewards.'
        ELSE 'You''ve been promoted to ' || INITCAP(v_new_tier) || ' tier!'
    END;

    -- 9. Idempotent notification insert (guard with NOT EXISTS)
    INSERT INTO public.notifications (user_id, title, body, type, reference_type, reference_id)
    SELECT
        p_user_id,
        '🎉 Tier Upgrade!',
        v_notification_body,
        'success',
        'tier_upgrade',
        gen_random_uuid()
    WHERE NOT EXISTS (
        SELECT 1
        FROM public.notifications
        WHERE user_id = p_user_id
          AND reference_type = 'tier_upgrade'
          AND body ILIKE '%' || v_new_tier || '%'
    );

    -- 10. Return result
    RETURN jsonb_build_object('upgraded', true, 'old_tier', v_current_tier, 'new_tier', v_new_tier);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_user_role(p_target_user_id uuid, p_new_role text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id   UUID;
    v_caller_role TEXT;
    v_old_role    TEXT;
    v_valid_roles TEXT[] := ARRAY[
        'customer', 'merchant', 'admin', 'super_admin',
        'hr_manager', 'employee',
        'relationship_exec', 'relationship_manager',
        'freelancer', 'video_editor', 'social_media_manager',
        'seo_specialist', 'advertiser', 'support_agent'
    ];
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    SELECT role::text INTO v_caller_role
    FROM public.user_profiles WHERE id = v_caller_id;

    IF v_caller_role NOT IN ('admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin access required');
    END IF;

    IF NOT (p_new_role = ANY(v_valid_roles)) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid role: ' || p_new_role);
    END IF;

    IF p_new_role = 'super_admin' AND v_caller_role != 'super_admin' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Only super_admin can grant super_admin role');
    END IF;

    IF v_caller_id = p_target_user_id AND p_new_role NOT IN ('admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot remove your own admin privileges');
    END IF;

    SELECT role::text INTO v_old_role
    FROM public.user_profiles WHERE id = p_target_user_id;

    IF v_old_role IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Target user not found');
    END IF;

    IF v_old_role = p_new_role THEN
        RETURN jsonb_build_object('success', true, 'message', 'Role unchanged');
    END IF;

    UPDATE public.user_profiles
    SET role = p_new_role::user_role,
        updated_at = NOW()
    WHERE id = p_target_user_id;

    UPDATE auth.users
    SET raw_user_meta_data = COALESCE(raw_user_meta_data, '{}'::jsonb)
        || jsonb_build_object('role', p_new_role),
        updated_at = NOW()
    WHERE id = p_target_user_id;

    INSERT INTO public.audit_logs_crm (actor_id, action, table_name, record_id, old_data, new_data)
    VALUES (
        v_caller_id,
        'ROLE_CHANGE',
        'user_profiles',
        p_target_user_id,
        jsonb_build_object('role', v_old_role),
        jsonb_build_object('role', p_new_role)
    );

    RETURN jsonb_build_object(
        'success', true,
        'message', 'Role updated from ' || v_old_role || ' to ' || p_new_role
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_reassign_lead(p_lead_id uuid, p_new_rep_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id    UUID;
    v_caller_role  TEXT;
    v_old_rep_id   UUID;
    v_rep_role     TEXT;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    SELECT role::text INTO v_caller_role
    FROM public.user_profiles WHERE id = v_caller_id;

    IF v_caller_role NOT IN ('admin', 'super_admin', 'relationship_manager') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin or Relationship Manager access required');
    END IF;

    SELECT assigned_to INTO v_old_rep_id
    FROM public.crm_leads
    WHERE id = p_lead_id AND archived_at IS NULL;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Lead not found or archived');
    END IF;

    IF p_new_rep_id IS NOT NULL THEN
        SELECT role::text INTO v_rep_role
        FROM public.user_profiles WHERE id = p_new_rep_id;

        IF v_rep_role IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'Target representative not found');
        END IF;

        IF v_rep_role NOT IN ('relationship_exec', 'relationship_manager', 'admin', 'super_admin') THEN
            RETURN jsonb_build_object('success', false, 'error', 'Target user is not a relationship representative');
        END IF;
    END IF;

    IF v_old_rep_id IS NOT DISTINCT FROM p_new_rep_id THEN
        RETURN jsonb_build_object('success', true, 'message', 'Assignment unchanged');
    END IF;

    UPDATE public.crm_leads
    SET assigned_to = p_new_rep_id,
        updated_at  = NOW()
    WHERE id = p_lead_id;

    INSERT INTO public.crm_lead_activities (lead_id, actor_id, action_type, metadata)
    VALUES (
        p_lead_id,
        v_caller_id,
        'assignment_change',
        jsonb_build_object(
            'old_rep_id', v_old_rep_id,
            'new_rep_id', p_new_rep_id,
            'changed_by', v_caller_id
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'message', CASE
            WHEN p_new_rep_id IS NULL THEN 'Lead unassigned'
            ELSE 'Lead reassigned successfully'
        END
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_unlist_from_marketplace(p_coupon_id uuid)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_merchant_id uuid;
BEGIN
  SELECT id INTO v_merchant_id
  FROM public.merchants
  WHERE user_id = auth.uid() AND status = 'approved'
  LIMIT 1;

  IF v_merchant_id IS NULL THEN
    RAISE EXCEPTION 'Merchant not found or not approved';
  END IF;

  UPDATE public.coupons
  SET 
    listed_on_marketplace = false,
    merchant_selling_price_paise = NULL,
    updated_at = NOW()
  WHERE id = p_coupon_id
    AND merchant_id = v_merchant_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Coupon not found';
  END IF;

  RETURN json_build_object('success', true, 'message', 'Unlisted successfully');
END;
$function$

CREATE OR REPLACE FUNCTION public.submit_leave_request(p_leave_type text, p_from_date date, p_to_date date, p_reason text DEFAULT NULL::text, p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_actor_id uuid;
    v_actor_role text;
    v_policy_year int;
    v_year_rec record;
    v_policy_rec record;
    v_breakdown jsonb;
    v_chargeable numeric(5,2);
    v_overlap int;
    v_balance record;
    v_initial_status text;
    v_request record;
    v_available numeric(6,2);
    v_consec_days numeric(6,2);
    v_notice_days int;
BEGIN
    IF auth.uid() IS NOT NULL THEN
        v_actor_id := auth.uid();
    ELSE
        v_actor_id := p_employee_id;
    END IF;

    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized: Actor identity missing.';
    END IF;

    SELECT role::text INTO v_actor_role FROM public.user_profiles WHERE id = v_actor_id;
    IF v_actor_role IS NULL THEN
        RAISE EXCEPTION 'User profile not found.';
    END IF;

    IF p_to_date < p_from_date THEN
        RAISE EXCEPTION 'End date cannot be earlier than start date.';
    END IF;

    v_policy_year := EXTRACT(YEAR FROM p_from_date)::int;

    SELECT * INTO v_year_rec FROM public.leave_policy_years 
    WHERE policy_year = v_policy_year AND status = 'published';

    IF v_year_rec.id IS NULL THEN
        RAISE EXCEPTION 'Leave policy year % is not configured or not published.', v_policy_year;
    END IF;

    SELECT * INTO v_policy_rec FROM public.leave_policies 
    WHERE policy_year_id = v_year_rec.id AND leave_type_key = p_leave_type AND is_active = true;

    IF v_policy_rec.id IS NULL THEN
        RAISE EXCEPTION 'Leave type "%" is not active or configured for policy year %.', p_leave_type, v_policy_year;
    END IF;

    v_notice_days := (p_from_date - CURRENT_DATE)::int;
    IF v_policy_rec.min_notice_days > 0 AND v_notice_days < v_policy_rec.min_notice_days THEN
        RAISE EXCEPTION 'Leave request requires at least % day(s) advance notice.', v_policy_rec.min_notice_days;
    END IF;

    v_breakdown := public.calculate_leave_days_breakdown(p_from_date, p_to_date, v_actor_id);
    v_chargeable := (v_breakdown->>'chargeable_days')::numeric;

    IF v_chargeable <= 0 AND v_policy_rec.requires_balance THEN
        RAISE EXCEPTION 'Selected date range contains 0 chargeable work days.';
    END IF;

    v_consec_days := (v_breakdown->>'calendar_days')::numeric;
    IF v_policy_rec.max_consecutive_days IS NOT NULL AND v_consec_days > v_policy_rec.max_consecutive_days THEN
        RAISE EXCEPTION 'Leave duration exceeds maximum consecutive limit of % days.', v_policy_rec.max_consecutive_days;
    END IF;

    SELECT COUNT(*) INTO v_overlap
    FROM public.leave_requests
    WHERE employee_id = v_actor_id
      AND status IN ('pending_hr_review', 'pending_admin_confirmation', 'approved')
      AND (from_date <= p_to_date AND to_date >= p_from_date);

    IF v_overlap > 0 THEN
        RAISE EXCEPTION 'Leave request overlaps with an existing pending or approved leave request.';
    END IF;

    IF v_policy_rec.requires_balance THEN
        SELECT * INTO v_balance 
        FROM public.employee_leave_balances 
        WHERE employee_id = v_actor_id AND policy_year = v_policy_year AND leave_type = p_leave_type
        FOR UPDATE;

        IF v_balance.id IS NULL THEN
            INSERT INTO public.employee_leave_balances (
                employee_id, policy_year, leave_type, policy_id, entitled_days
            ) VALUES (
                v_actor_id, v_policy_year, p_leave_type, v_policy_rec.id, v_policy_rec.annual_entitlement
            )
            ON CONFLICT (employee_id, policy_year, leave_type) DO NOTHING;

            SELECT * INTO v_balance 
            FROM public.employee_leave_balances 
            WHERE employee_id = v_actor_id AND policy_year = v_policy_year AND leave_type = p_leave_type
            FOR UPDATE;
        END IF;

        v_available := (v_balance.entitled_days + v_balance.carried_forward_days + v_balance.accrued_days + v_balance.adjustment_days) - (v_balance.used_days + v_balance.reserved_days);

        IF NOT v_policy_rec.allow_negative_balance AND v_available < v_chargeable THEN
            RAISE EXCEPTION 'Insufficient leave balance. Available: %, Requested: %', v_available, v_chargeable;
        END IF;

        UPDATE public.employee_leave_balances
        SET 
            reserved_days = reserved_days + v_chargeable,
            version = version + 1,
            updated_at = now()
        WHERE id = v_balance.id;
    END IF;

    IF v_actor_role = 'hr_manager' THEN
        v_initial_status := 'pending_admin_confirmation';
    ELSE
        v_initial_status := 'pending_hr_review';
    END IF;

    INSERT INTO public.leave_requests (
        employee_id, policy_id, leave_type, from_date, to_date, reason,
        status, requested_days, chargeable_days, calendar_breakdown, policy_year,
        requester_role_snapshot
    ) VALUES (
        v_actor_id, v_policy_rec.id, p_leave_type, p_from_date, p_to_date, p_reason,
        v_initial_status, (v_breakdown->>'calendar_days')::numeric, v_chargeable, v_breakdown, v_policy_year,
        v_actor_role
    ) RETURNING * INTO v_request;

    INSERT INTO public.leave_request_actions (
        leave_request_id, actor_id, actor_role, action, from_status, to_status, note
    ) VALUES (
        v_request.id, v_actor_id, v_actor_role, 'submitted', NULL, v_initial_status, p_reason
    );

    INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, new_data, module, severity)
    VALUES (
        v_actor_id, 'Leave request submitted', 'leave_requests', v_request.id,
        jsonb_build_object('leave_type', p_leave_type, 'from_date', p_from_date, 'to_date', p_to_date, 'chargeable_days', v_chargeable, 'status', v_initial_status),
        'Leaves', 'low'
    );

    RETURN jsonb_build_object('success', true, 'request', row_to_json(v_request));
END;
$function$

CREATE OR REPLACE FUNCTION public.adjust_employee_leave_balance(p_balance_id uuid, p_delta_days numeric, p_reason text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_actor_id uuid;
    v_actor_role text;
    v_balance record;
    v_policy record;
    v_new_adj numeric(6,2);
    v_available numeric(6,2);
    v_adj_rec record;
    v_updated record;
BEGIN
    IF auth.uid() IS NOT NULL THEN
        v_actor_id := auth.uid();
    ELSE
        v_actor_id := p_actor_id;
    END IF;

    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized call.';
    END IF;

    SELECT role::text INTO v_actor_role FROM public.user_profiles WHERE id = v_actor_id;
    IF v_actor_role NOT IN ('admin', 'super_admin') THEN
        RAISE EXCEPTION 'Forbidden: Only Admins can manually adjust leave balances.';
    END IF;

    IF p_delta_days IS NULL OR p_delta_days = 0 THEN
        RAISE EXCEPTION 'Delta days must be a non-zero number.';
    END IF;

    IF p_reason IS NULL OR TRIM(p_reason) = '' THEN
        RAISE EXCEPTION 'Adjustment reason is required for audit trail.';
    END IF;

    SELECT * INTO v_balance FROM public.employee_leave_balances WHERE id = p_balance_id FOR UPDATE;
    IF v_balance.id IS NULL THEN
        RAISE EXCEPTION 'Leave balance record not found.';
    END IF;

    IF v_balance.policy_id IS NOT NULL THEN
        SELECT * INTO v_policy FROM public.leave_policies WHERE id = v_balance.policy_id;
    END IF;

    v_new_adj := v_balance.adjustment_days + p_delta_days;
    v_available := (v_balance.entitled_days + v_balance.carried_forward_days + v_balance.accrued_days + v_new_adj) - (v_balance.used_days + v_balance.reserved_days);

    IF v_policy.id IS NOT NULL AND NOT v_policy.allow_negative_balance AND v_available < 0 THEN
        RAISE EXCEPTION 'Adjustment rejected: Available balance cannot become negative (calculated: %).', v_available;
    END IF;

    UPDATE public.employee_leave_balances
    SET 
        adjustment_days = v_new_adj,
        version = version + 1,
        updated_at = now()
    WHERE id = p_balance_id
    RETURNING * INTO v_updated;

    INSERT INTO public.leave_balance_adjustments (
        employee_leave_balance_id, employee_id, policy_id, delta_days, reason, actor_id
    ) VALUES (
        p_balance_id, v_balance.employee_id, v_balance.policy_id, p_delta_days, p_reason, v_actor_id
    ) RETURNING * INTO v_adj_rec;

    INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, old_data, new_data, module, severity)
    VALUES (
        v_actor_id, 'Leave balance adjusted', 'employee_leave_balances', p_balance_id,
        jsonb_build_object('old_adjustment_days', v_balance.adjustment_days),
        jsonb_build_object('delta_days', p_delta_days, 'new_adjustment_days', v_new_adj, 'reason', p_reason),
        'Leaves', 'medium'
    );

    RETURN jsonb_build_object('success', true, 'balance', row_to_json(v_updated), 'adjustment', row_to_json(v_adj_rec));
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_review_leave_request(p_request_id uuid, p_action text, p_note text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_actor_id uuid;
    v_actor_role text;
    v_request record;
    v_balance record;
    v_chargeable numeric(5,2);
    v_to_status text;
    v_updated record;
BEGIN
    IF auth.uid() IS NOT NULL THEN
        v_actor_id := auth.uid();
    ELSE
        v_actor_id := p_actor_id;
    END IF;

    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized call.';
    END IF;

    SELECT role::text INTO v_actor_role FROM public.user_profiles WHERE id = v_actor_id;
    IF v_actor_role NOT IN ('admin', 'super_admin') THEN
        RAISE EXCEPTION 'Forbidden: Only Admins can perform admin review.';
    END IF;

    IF p_action NOT IN ('approve', 'reject') THEN
        RAISE EXCEPTION 'Invalid Admin review action: %. Must be "approve" or "reject".', p_action;
    END IF;

    SELECT * INTO v_request FROM public.leave_requests WHERE id = p_request_id FOR UPDATE;
    IF v_request.id IS NULL THEN
        RAISE EXCEPTION 'Leave request not found.';
    END IF;

    IF v_request.status <> 'pending_admin_confirmation' THEN
        RAISE EXCEPTION 'Conflict: Leave request is not pending admin confirmation (current status: %).', v_request.status;
    END IF;

    IF p_action = 'reject' AND (p_note IS NULL OR TRIM(p_note) = '') THEN
        RAISE EXCEPTION 'Rejection note is mandatory.';
    END IF;

    v_chargeable := COALESCE(v_request.chargeable_days, 1);

    SELECT * INTO v_balance 
    FROM public.employee_leave_balances 
    WHERE employee_id = v_request.employee_id 
      AND policy_year = COALESCE(v_request.policy_year, EXTRACT(YEAR FROM v_request.from_date)::int)
      AND leave_type = v_request.leave_type
    FOR UPDATE;

    IF p_action = 'approve' THEN
        v_to_status := 'approved';
        IF v_balance.id IS NOT NULL THEN
            UPDATE public.employee_leave_balances
            SET 
                reserved_days = GREATEST(0, reserved_days - v_chargeable),
                used_days = used_days + v_chargeable,
                version = version + 1,
                updated_at = now()
            WHERE id = v_balance.id;
        END IF;
    ELSE
        v_to_status := 'rejected_by_admin';
        IF v_balance.id IS NOT NULL THEN
            UPDATE public.employee_leave_balances
            SET 
                reserved_days = GREATEST(0, reserved_days - v_chargeable),
                version = version + 1,
                updated_at = now()
            WHERE id = v_balance.id;
        END IF;
    END IF;

    UPDATE public.leave_requests
    SET 
        status = v_to_status,
        admin_reviewed_by = v_actor_id,
        admin_reviewed_at = now(),
        admin_review_note = p_note,
        reviewed_by = v_actor_id,
        reviewed_at = now(),
        review_note = p_note,
        workflow_version = workflow_version + 1,
        updated_at = now()
    WHERE id = p_request_id
    RETURNING * INTO v_updated;

    INSERT INTO public.leave_request_actions (
        leave_request_id, actor_id, actor_role, action, from_status, to_status, note
    ) VALUES (
        p_request_id, v_actor_id, v_actor_role, p_action, 'pending_admin_confirmation', v_to_status, p_note
    );

    INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, old_data, new_data, module, severity)
    VALUES (
        v_actor_id, 'Admin review executed', 'leave_requests', p_request_id,
        jsonb_build_object('status', 'pending_admin_confirmation'),
        jsonb_build_object('status', v_to_status, 'admin_review_note', p_note, 'admin_action', p_action),
        'Leaves', 'medium'
    );

    RETURN jsonb_build_object('success', true, 'request', row_to_json(v_updated));
END;
$function$

CREATE OR REPLACE FUNCTION public.hr_review_leave_request(p_request_id uuid, p_action text, p_note text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid)
