        jsonb_build_object('status', 'pending_hr_review'),
        jsonb_build_object('status', v_to_status, 'hr_review_note', p_note, 'hr_action', p_action),
        'Leaves', 'medium'
    );

    RETURN jsonb_build_object('success', true, 'request', row_to_json(v_updated));
END;
$function$

CREATE OR REPLACE FUNCTION public.cancel_leave_request(p_request_id uuid, p_reason text DEFAULT NULL::text, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_actor_id uuid;
    v_actor_role text;
    v_request record;
    v_balance record;
    v_chargeable numeric(5,2);
    v_updated record;
BEGIN
    IF auth.uid() IS NOT NULL THEN
        v_actor_id := auth.uid();
    ELSE
        v_actor_id := p_actor_id;
    END IF;

    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized call.';
    END IF;

    SELECT role::text INTO v_actor_role FROM public.user_profiles WHERE id = v_actor_id;

    SELECT * INTO v_request FROM public.leave_requests WHERE id = p_request_id FOR UPDATE;
    IF v_request.id IS NULL THEN
        RAISE EXCEPTION 'Leave request not found.';
    END IF;

    IF v_request.employee_id <> v_actor_id THEN
        RAISE EXCEPTION 'Forbidden: You can only cancel your own leave requests.';
    END IF;

    IF v_request.status NOT IN ('pending_hr_review', 'pending_admin_confirmation') THEN
        RAISE EXCEPTION 'Cannot cancel leave request with status "%".', v_request.status;
    END IF;

    v_chargeable := COALESCE(v_request.chargeable_days, 1);

    SELECT * INTO v_balance 
    FROM public.employee_leave_balances 
    WHERE employee_id = v_actor_id 
      AND policy_year = COALESCE(v_request.policy_year, EXTRACT(YEAR FROM v_request.from_date)::int)
      AND leave_type = v_request.leave_type
    FOR UPDATE;

    IF v_balance.id IS NOT NULL THEN
        UPDATE public.employee_leave_balances
        SET 
            reserved_days = GREATEST(0, reserved_days - v_chargeable),
            version = version + 1,
            updated_at = now()
        WHERE id = v_balance.id;
    END IF;

    UPDATE public.leave_requests
    SET 
        status = 'cancelled',
        cancelled_by = v_actor_id,
        cancelled_at = now(),
        cancel_reason = p_reason,
        workflow_version = workflow_version + 1,
        updated_at = now()
    WHERE id = p_request_id
    RETURNING * INTO v_updated;

    INSERT INTO public.leave_request_actions (
        leave_request_id, actor_id, actor_role, action, from_status, to_status, note
    ) VALUES (
        p_request_id, v_actor_id, v_actor_role, 'cancel', v_request.status, 'cancelled', p_reason
    );

    INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, old_data, new_data, module, severity)
    VALUES (
        v_actor_id, 'Leave request cancelled', 'leave_requests', p_request_id,
        jsonb_build_object('status', v_request.status),
        jsonb_build_object('status', 'cancelled', 'cancel_reason', p_reason),
        'Leaves', 'low'
    );

    RETURN jsonb_build_object('success', true, 'request', row_to_json(v_updated));
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_bulk_assign_leads(p_lead_ids uuid[], p_new_rep_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id     UUID;
    v_caller_role   TEXT;
    v_rep_role      TEXT;
    v_affected_rows INTEGER;
BEGIN
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    -- Validate caller role
    SELECT role::text INTO v_caller_role
    FROM public.user_profiles WHERE id = v_caller_id;

    IF v_caller_role NOT IN ('admin', 'super_admin', 'relationship_manager') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin or Relationship Manager access required');
    END IF;

    -- Validate target representative if provided
    IF p_new_rep_id IS NOT NULL THEN
        SELECT role::text INTO v_rep_role
        FROM public.user_profiles WHERE id = p_new_rep_id;

        IF v_rep_role IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'Target representative not found');
        END IF;

        IF v_rep_role NOT IN ('relationship_exec', 'relationship_manager', 'admin', 'super_admin') THEN
            RETURN jsonb_build_object('success', false, 'error', 'Target user is not a relationship representative');
        END IF;
    END IF;

    -- Protect against excessively large arrays
    IF array_length(p_lead_ids, 1) > 5000 THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot assign more than 5000 leads at once');
    END IF;

    IF p_lead_ids IS NULL OR array_length(p_lead_ids, 1) = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'No leads provided');
    END IF;

    -- Perform bulk update (only for non-archived leads)
    UPDATE public.crm_leads
    SET assigned_to = p_new_rep_id,
        updated_at  = NOW()
    WHERE id = ANY(p_lead_ids) 
      AND archived_at IS NULL
      AND (assigned_to IS DISTINCT FROM p_new_rep_id);

    GET DIAGNOSTICS v_affected_rows = ROW_COUNT;

    -- Audit the bulk operation in a single event for efficiency
    INSERT INTO public.audit_logs_crm (actor_id, action, table_name, record_id, new_data)
    VALUES (
        v_caller_id,
        'BULK_ASSIGNMENT',
        'crm_leads',
        NULL, -- It's a bulk operation
        jsonb_build_object(
            'new_rep_id', p_new_rep_id,
            'affected_count', v_affected_rows,
            'lead_ids', p_lead_ids
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'affected_count', v_affected_rows,
        'message', 'Successfully assigned ' || v_affected_rows || ' leads'
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_preview_team_for_location(p_pincode text, p_zone text, p_area text, p_city text, p_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
