CREATE OR REPLACE FUNCTION public.purchase_coupon(p_coupon_id uuid, p_payment_reference text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID;
    v_user_role user_role;
    v_is_suspended BOOLEAN;
    v_kyc_status kyc_status;
    v_coupon RECORD;
    v_buyer_fee_paise BIGINT;
    v_total_paid_paise BIGINT;
    v_transaction_id UUID;
    v_current_balance BIGINT;
    v_new_balance BIGINT;
BEGIN
    -- Get current user
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;
    
    -- Check user status
    SELECT role, is_suspended INTO v_user_role, v_is_suspended
    FROM public.user_profiles
    WHERE id = v_user_id;
    
    IF v_user_role != 'user' THEN
        RAISE EXCEPTION 'Only regular users can purchase coupons';
    END IF;
    
    IF v_is_suspended THEN
        RAISE EXCEPTION 'Account is suspended';
    END IF;
    
    -- Check KYC status
    SELECT status INTO v_kyc_status
    FROM public.kyc_records
    WHERE user_id = v_user_id;
    
    IF v_kyc_status IS NULL THEN
        RAISE EXCEPTION 'KYC not submitted';
    END IF;
    
    IF v_kyc_status != 'approved' THEN
        RAISE EXCEPTION 'KYC not approved. Current status: %', v_kyc_status;
    END IF;
    
    -- CRITICAL: Lock the coupon row to prevent race conditions
    SELECT 
        id, brand, title, selling_price_paise, status, 
        valid_until, purchased_by
    INTO v_coupon
    FROM public.coupons
    WHERE id = p_coupon_id
    FOR UPDATE; -- LOCK THE ROW
    
    -- Validate coupon exists
    IF v_coupon.id IS NULL THEN
        RAISE EXCEPTION 'Coupon not found';
    END IF;
    
    -- Validate coupon is available
    IF v_coupon.status != 'available' THEN
        RAISE EXCEPTION 'Coupon is not available. Current status: %', v_coupon.status;
    END IF;
    
    -- Validate coupon is not expired
    IF v_coupon.valid_until <= NOW() THEN
        RAISE EXCEPTION 'Coupon has expired';
    END IF;
    
    -- Double-check no buyer (redundant but critical)
    IF v_coupon.purchased_by IS NOT NULL THEN
        RAISE EXCEPTION 'Coupon already purchased';
    END IF;
    
    -- Calculate fees (MUST be done in SQL, not frontend)
    v_buyer_fee_paise := FLOOR(v_coupon.selling_price_paise * 0.03);
    v_total_paid_paise := v_coupon.selling_price_paise + v_buyer_fee_paise;
    
    -- Create transaction record
    INSERT INTO public.transactions (
        user_id,
        coupon_id,
        coupon_price_paise,
        buyer_fee_paise,
        total_paid_paise,
        payment_method,
        payment_reference,
        status,
        completed_at
    ) VALUES (
        v_user_id,
        p_coupon_id,
        v_coupon.selling_price_paise,
        v_buyer_fee_paise,
        v_total_paid_paise,
        'upi',
        p_payment_reference,
        'completed',
        NOW()
    )
    RETURNING id INTO v_transaction_id;
    
    -- Mark coupon as sold
    UPDATE public.coupons
    SET 
        status = 'sold',
        purchased_by = v_user_id,
        purchased_at = NOW(),
        updated_at = NOW()
    WHERE id = p_coupon_id;
    
    -- Get current platform balance
    SELECT COALESCE(balance_after_paise, 0)
    INTO v_current_balance
    FROM public.platform_ledger
    ORDER BY created_at DESC
    LIMIT 1;
    
    v_new_balance := v_current_balance + v_buyer_fee_paise;
    
    -- Record platform revenue in ledger
    INSERT INTO public.platform_ledger (
        transaction_id,
        entry_type,
        amount_paise,
        balance_after_paise,
        description
    ) VALUES (
        v_transaction_id,
        'buyer_fee',
        v_buyer_fee_paise,
        v_new_balance,
        FORMAT('Buyer fee from transaction %s', v_transaction_id)
    );
    
    -- Log the purchase
    INSERT INTO public.audit_logs (
        actor_id,
        actor_role,
        action,
        entity_type,
        entity_id,
        description,
        metadata
    ) VALUES (
        v_user_id,
        'user',
        'coupon_sold',
        'coupon',
        p_coupon_id,
        FORMAT('User purchased coupon: %s - %s', v_coupon.brand, v_coupon.title),
        jsonb_build_object(
            'transaction_id', v_transaction_id,
            'amount_paise', v_total_paid_paise
        )
    );
    
    -- Return success response
    RETURN jsonb_build_object(
        'success', true,
        'transaction_id', v_transaction_id,
        'coupon_id', p_coupon_id,
        'total_paid_paise', v_total_paid_paise,
        'buyer_fee_paise', v_buyer_fee_paise,
        'message', 'Purchase successful'
    );
    
EXCEPTION
    WHEN OTHERS THEN
        -- Log the error
        INSERT INTO public.audit_logs (
            actor_id,
            actor_role,
            action,
            entity_type,
            entity_id,
            description,
            metadata
        ) VALUES (
            v_user_id,
            COALESCE(v_user_role, 'user'),
            'transaction_created',
            'transaction',
            NULL,
            'Purchase failed: ' || SQLERRM,
            jsonb_build_object(
                'coupon_id', p_coupon_id,
                'error', SQLERRM
            )
        );
        
        -- Re-raise the exception
        RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_kyc_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF NEW.kyc_status = 'approved' THEN
        NEW.kyc_status := 'verified';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.add_to_shopping_cart(p_customer_id uuid, p_inventory_id uuid, p_product_id uuid, p_quantity integer, p_is_platform boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_product_id UUID := p_product_id;
    v_existing_id UUID;
    v_cart_count INTEGER;
    v_existing_is_platform BOOLEAN;
    v_existing_merchant_id UUID;
    v_new_merchant_id UUID;
BEGIN
    -- 1. Get the merchant ID of the item being added
    IF NOT p_is_platform THEN
        IF p_inventory_id IS NULL THEN
            RETURN jsonb_build_object('success', false, 'message', 'Inventory ID required for merchant items');
        END IF;

        SELECT merchant_id, product_id INTO v_new_merchant_id, v_product_id
        FROM public.merchant_inventory
        WHERE id = p_inventory_id;

        IF v_product_id IS NULL THEN
            RETURN jsonb_build_object('success', false, 'message', 'Inventory item not found');
        END IF;
    ELSE
        IF v_product_id IS NULL THEN
             RETURN jsonb_build_object('success', false, 'message', 'Product ID required for platform items');
        END IF;
    END IF;

    -- 2. Check for mixed merchant conflict
    -- Check if cart already has items
    SELECT COUNT(*), COALESCE(MAX(is_platform_item::int)::boolean, false) INTO v_cart_count, v_existing_is_platform
    FROM public.shopping_cart
    WHERE customer_id = p_customer_id;

    IF v_cart_count > 0 THEN
        -- Check if we are mixing platform and merchant
        IF p_is_platform <> v_existing_is_platform THEN
            RETURN jsonb_build_object('success', false, 'message', 'MIXED_SELLER_ERROR', 'seller_type_conflict', true);
        END IF;

        -- If both are merchant items, check if it's the same merchant
        IF NOT p_is_platform THEN
            SELECT DISTINCT mi.merchant_id INTO v_existing_merchant_id
            FROM public.shopping_cart sc
            JOIN public.merchant_inventory mi ON sc.inventory_id = mi.id
            WHERE sc.customer_id = p_customer_id
            LIMIT 1;

            IF v_existing_merchant_id IS NOT NULL AND v_existing_merchant_id <> v_new_merchant_id THEN
                RETURN jsonb_build_object('success', false, 'message', 'MIXED_SELLER_ERROR', 'merchant_conflict', true);
            END IF;
        END IF;
    END IF;

    -- 3. Check if item already exists in cart for this customer
    SELECT id INTO v_existing_id
    FROM public.shopping_cart
    WHERE customer_id = p_customer_id 
      AND (inventory_id IS NOT DISTINCT FROM p_inventory_id)
      AND product_id = v_product_id
      AND is_platform_item = p_is_platform;

    IF v_existing_id IS NOT NULL THEN
        UPDATE public.shopping_cart
        SET quantity = quantity + p_quantity,
            updated_at = now()
        WHERE id = v_existing_id;
    ELSE
        INSERT INTO public.shopping_cart (customer_id, inventory_id, product_id, quantity, is_platform_item)
        VALUES (p_customer_id, p_inventory_id, v_product_id, p_quantity, p_is_platform);
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_bulk_insert_coupons_v2(coupons_data jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  coupon_item jsonb;
  inserted_id uuid;
  result_ids uuid[] := '{}';
  tags_text text[];
BEGIN
  FOR coupon_item IN SELECT * FROM jsonb_array_elements(coupons_data)
  LOOP
    -- Handle tags conversion properly
    IF (coupon_item ? 'tags') AND (jsonb_typeof(coupon_item->'tags') = 'array') THEN
      SELECT ARRAY_AGG(x)::text[] INTO tags_text FROM jsonb_array_elements_text(coupon_item->'tags') x;
    ELSE
      tags_text := '{}'::text[];
    END IF;

    -- 1. Insert into coupons table
    INSERT INTO coupons (
      brand, title, description, category, face_value_paise, 
      selling_price_paise, encrypted_code, masked_code, valid_until, 
      terms_and_conditions, usage_instructions, image_url, tags, created_by
    ) VALUES (
      (coupon_item->>'brand'),
      (coupon_item->>'title'),
      (coupon_item->>'description'),
      (coupon_item->>'category'),
      (coupon_item->>'face_value_paise')::bigint,
      (coupon_item->>'selling_price_paise')::bigint,
      (coupon_item->>'encrypted_code'), 
      (coupon_item->>'masked_code'),
      (coupon_item->>'valid_until')::timestamp with time zone,
      (coupon_item->>'terms_and_conditions'),
      (coupon_item->>'usage_instructions'),
      (coupon_item->>'image_url'),
      tags_text,
      COALESCE((coupon_item->>'created_by')::uuid, auth.uid())
    )
    RETURNING id INTO inserted_id;

    -- 2. Insert into coupon_codes table
    INSERT INTO coupon_codes (coupon_id, plain_code)
    VALUES (inserted_id, coupon_item->>'encrypted_code');

    result_ids := array_append(result_ids, inserted_id);
  END LOOP;

  RETURN jsonb_build_object('success', true, 'inserted_count', array_length(result_ids, 1), 'ids', result_ids);
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_gateway_orders(p_group_id uuid, p_customer_id uuid, p_amount_paise bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_group              RECORD;
    v_item               RECORD;
    v_item_total         BIGINT;
    v_commission_paise   BIGINT;
    v_merchant_credit    BIGINT;
    v_product_cost       BIGINT;
    v_merchant_profit    BIGINT;
    v_total_platform_cut BIGINT := 0;
BEGIN
    SELECT * INTO v_group
    FROM public.shopping_order_groups
    WHERE id = p_group_id
      AND customer_id = p_customer_id
      AND payment_status = 'pending';

    IF v_group.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Invalid or already processed order group');
    END IF;

    IF v_group.total_amount_paise != p_amount_paise THEN
        RETURN jsonb_build_object('success', false, 'message', 'Amount mismatch');
    END IF;

    UPDATE public.shopping_order_groups
    SET payment_status = 'paid',
        status         = 'completed'
    WHERE id = p_group_id;

    FOR v_item IN
        SELECT i.*, p.admin_stock, p.wholesale_price_paise, mi.stock_quantity AS merchant_stock
        FROM public.shopping_order_items i
        JOIN public.shopping_products    p  ON i.product_id  = p.id
        LEFT JOIN public.merchant_inventory mi ON i.inventory_id = mi.id
        WHERE i.group_id = p_group_id
    LOOP
        v_item_total := v_item.unit_price_paise * v_item.quantity;

        IF v_group.is_platform_order THEN
            UPDATE public.shopping_products
            SET admin_stock = admin_stock - v_item.quantity,
                updated_at  = now()
            WHERE id = v_item.product_id;

            UPDATE public.shopping_products
            SET platform_listed = false
            WHERE id = v_item.product_id
              AND admin_stock = 0;

        ELSE
            v_product_cost     := COALESCE(v_item.wholesale_price_paise, 0);
            v_commission_paise := GREATEST(0, (v_item.unit_price_paise - v_product_cost))
                                  * v_item.quantity * 30 / 100;
            v_total_platform_cut := v_total_platform_cut + v_commission_paise;
            v_merchant_credit  := v_item_total - v_commission_paise;
            v_merchant_profit  := v_merchant_credit - (v_product_cost * v_item.quantity);

            UPDATE public.merchant_inventory
            SET stock_quantity = stock_quantity - v_item.quantity,
                updated_at     = now()
            WHERE id = v_item.inventory_id;

            UPDATE public.shopping_order_items
            SET cost_price_paise        = v_product_cost,
                profit_paise            = v_merchant_profit,
                commission_amount_paise = v_commission_paise
            WHERE id = v_item.id;

            INSERT INTO public.notifications (user_id, title, body, type, reference_id, reference_type)
            SELECT user_id,
                   'New Order Received 🛒',
                   'Order #' || substring(p_group_id::text from 1 for 8) || ' has been paid.',
                   'success', p_group_id, 'shopping_order'
            FROM public.merchants
            WHERE id = v_item.seller_id;
        END IF;
    END LOOP;

    IF NOT v_group.is_platform_order THEN
        UPDATE public.shopping_order_groups
        SET commission_rate       = 0.30,
            platform_cut_paise    = v_total_platform_cut,
            merchant_profit_paise = (
                SELECT SUM((i.unit_price_paise - COALESCE(p.wholesale_price_paise, 0)) * i.quantity)
                       - v_total_platform_cut
                FROM public.shopping_order_items i
                JOIN public.shopping_products    p ON i.product_id = p.id
                WHERE i.group_id = p_group_id
            ),
            settlement_status = 'pending'
        WHERE id = p_group_id;
    END IF;

    DELETE FROM public.shopping_cart WHERE customer_id = p_customer_id;

    RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.get_user_id_by_phone(phone_number text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  _clean   text;
  _user_id uuid;
BEGIN
  _clean := right(regexp_replace(phone_number, '\D', '', 'g'), 10);

  IF _clean IS NULL OR length(_clean) < 10 THEN
    RETURN NULL;
  END IF;

  -- Priority 1: phone-only users (pseudo-email pattern)
  SELECT id INTO _user_id
  FROM auth.users
  WHERE right(regexp_replace(phone, '\D', '', 'g'), 10) = _clean
    AND phone IS NOT NULL
    AND email ~ '^p[0-9]+@phone\.intrust\.internal$'
  LIMIT 1;

  IF _user_id IS NOT NULL THEN
    RETURN _user_id;
  END IF;

  -- Priority 2: any auth.users with matching phone (fallback)
  SELECT id INTO _user_id
  FROM auth.users
  WHERE right(regexp_replace(phone, '\D', '', 'g'), 10) = _clean
    AND phone IS NOT NULL
  LIMIT 1;

  IF _user_id IS NOT NULL THEN
    RETURN _user_id;
  END IF;

  -- Priority 3: user_profiles (Google users who linked phone)
  SELECT id INTO _user_id
  FROM public.user_profiles
  WHERE right(regexp_replace(phone, '\D', '', 'g'), 10) = _clean
    AND phone IS NOT NULL
  LIMIT 1;

  RETURN _user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_mark_expired_coupons()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID;
    v_user_role user_role;
    v_updated_count INT;
BEGIN
    v_user_id := auth.uid();
    
    -- Check admin role
    SELECT role INTO v_user_role
    FROM public.user_profiles
    WHERE id = v_user_id;
    
    IF v_user_role != 'admin' THEN
        RAISE EXCEPTION 'Only admins can mark expired coupons';
    END IF;
    
    -- Update expired coupons
    UPDATE public.coupons
    SET 
        status = 'expired',
        updated_at = NOW()
    WHERE status = 'available'
        AND valid_until <= NOW();
    
    GET DIAGNOSTICS v_updated_count = ROW_COUNT;
    
    -- Log the action
    INSERT INTO public.audit_logs (
        actor_id, actor_role, action, entity_type,
        description, metadata
    ) VALUES (
        v_user_id, 'admin', 'coupon_expired', 'coupon',
        FORMAT('Marked %s coupons as expired', v_updated_count),
        jsonb_build_object('count', v_updated_count)
    );
    
    RETURN jsonb_build_object(
        'success', true,
        'expired_count', v_updated_count
    );
END;
$function$

