CREATE OR REPLACE FUNCTION public.add_to_shopping_cart(p_customer_id uuid, p_inventory_id uuid, p_quantity integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_product_id UUID;
    v_existing_id UUID;
BEGIN
    -- Get product_id from inventory record
    SELECT product_id INTO v_product_id
    FROM public.merchant_inventory
    WHERE id = p_inventory_id;

    IF v_product_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Inventory item not found');
    END IF;

    -- Check if item already exists in cart for this customer
    SELECT id INTO v_existing_id
    FROM public.shopping_cart
    WHERE customer_id = p_customer_id AND inventory_id = p_inventory_id;

    IF v_existing_id IS NOT NULL THEN
        UPDATE public.shopping_cart
        SET quantity = quantity + p_quantity,
            updated_at = now()
        WHERE id = v_existing_id;
    ELSE
        INSERT INTO public.shopping_cart (customer_id, inventory_id, product_id, quantity)
        VALUES (p_customer_id, p_inventory_id, v_product_id, p_quantity);
    END IF;

    RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_and_distribute_rewards(p_event_type text, p_source_user_id uuid, p_reference_id uuid DEFAULT NULL::uuid, p_reference_type text DEFAULT NULL::text, p_amount_paise bigint DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_config JSONB;
    v_points BIGINT;
    v_tier_multiplier NUMERIC;
    v_daily_cap BIGINT;
    v_earned_today BIGINT;
    v_balance_record RECORD;
    v_eligibility JSONB;
    v_event_eligibility JSONB;
    v_require_kyc BOOLEAN;
    v_source_profile RECORD;
    v_total_distributed BIGINT := 0;
    v_rows_inserted INT;
    v_ancestor RECORD;
BEGIN
    -- 1. Fetch active configuration for this event
    SELECT config_value INTO v_config
    FROM public.reward_configuration
    WHERE config_key = p_event_type || '_reward' AND is_active = true;

    IF NOT FOUND THEN
        -- Check for short-form key as fallback
        SELECT config_value INTO v_config
        FROM public.reward_configuration
        WHERE config_key = p_event_type AND is_active = true;

        IF NOT FOUND THEN
            INSERT INTO public.reward_distribution_log (event_type, source_user_id, reference_id, reference_type, amount_paise, success, error_message) 
            VALUES (p_event_type, p_source_user_id, p_reference_id, p_reference_type, p_amount_paise, false, 'No active config for event: ' || p_event_type);
            RETURN jsonb_build_object('success', false, 'message', 'No active config for event: ' || p_event_type);
        END IF;
    END IF;

    -- 2. Check Daily Login Frequency (Once per day)
    IF p_event_type = 'daily_login' THEN
        IF EXISTS (
            SELECT 1 FROM public.reward_transactions 
            WHERE user_id = p_source_user_id 
              AND event_type = 'daily_login' 
              AND created_at >= CURRENT_DATE
        ) THEN
            INSERT INTO public.reward_distribution_log (event_type, source_user_id, reference_id, reference_type, amount_paise, success, error_message) 
            VALUES (p_event_type, p_source_user_id, p_reference_id, p_reference_type, p_amount_paise, true, 'Daily login reward already claimed for today');
            RETURN jsonb_build_object('success', true, 'message', 'Daily login reward already claimed for today');
        END IF;
    END IF;

    -- 3. Fetch eligibility rules
    SELECT config_value INTO v_eligibility
    FROM public.reward_configuration
    WHERE config_key = 'eligibility' AND is_active = true;

    -- 4. Get source user profile
    SELECT kyc_status, created_at INTO v_source_profile
    FROM public.user_profiles
    WHERE id = p_source_user_id;

    -- 5. Prepare a virtual list of reward targets (Source User + Ancestors)
    FOR v_ancestor IN
        (
            -- Source User (Level 0)
            SELECT p_source_user_id as target_id, 0 as level
            UNION ALL
            -- Ancestors (Level 1+)
            SELECT ancestor_id as target_id, level
            FROM public.reward_tree_paths
            WHERE descendant_id = p_source_user_id
        )
        ORDER BY level
    LOOP
        -- 6. Determine base points for this level
        v_points := 0;
        IF v_ancestor.level = 0 THEN
            IF v_config->>'direct' IS NOT NULL THEN
                v_points := (v_config->>'direct')::BIGINT;
            END IF;
            -- FIX: inline rate_per_100rs for Level 0 purchase and wallet_topup
            IF v_points = 0
               AND p_event_type IN ('purchase', 'wallet_topup')
               AND p_amount_paise > 0
               AND v_config->>'rate_per_100rs' IS NOT NULL
            THEN
                v_points := (p_amount_paise * (v_config->>'rate_per_100rs')::BIGINT / 10000);
            END IF;
        ELSE
            IF v_config->>('L' || v_ancestor.level) IS NOT NULL THEN
                v_points := (v_config->>('L' || v_ancestor.level))::BIGINT;
            END IF;
        END IF;

        IF v_points = 0 THEN CONTINUE; END IF;

        -- 7. For rate-based events, scale Level 1+ upline points by amount
        IF p_event_type IN ('purchase', 'wallet_topup') AND p_amount_paise > 0 THEN
            IF v_ancestor.level = 0 AND v_config->>'rate_per_100rs' IS NOT NULL THEN
                -- Level 0 already computed above; no-op here to avoid double-scaling
                NULL;
            ELSE
                v_points := (p_amount_paise * v_points / 10000);
            END IF;
        END IF;

        -- 8. Get target balance/tier info
        SELECT * INTO v_balance_record
        FROM public.reward_points_balance
        WHERE user_id = v_ancestor.target_id;

        IF NOT FOUND THEN
            INSERT INTO public.reward_points_balance (user_id) VALUES (v_ancestor.target_id)
            ON CONFLICT (user_id) DO NOTHING;
            SELECT * INTO v_balance_record
            FROM public.reward_points_balance
            WHERE user_id = v_ancestor.target_id;
        END IF;

        -- 9. Check event/level eligibility. Default to the global KYC rule,
        --    with per-event overrides for direct and upline payouts.
        v_event_eligibility := COALESCE(v_eligibility->'events'->p_event_type, '{}'::jsonb);
        IF v_ancestor.level = 0 THEN
            v_require_kyc := COALESCE(
                (v_event_eligibility->>'direct_require_kyc')::BOOLEAN,
                (v_eligibility->>'require_kyc')::BOOLEAN,
                false
            );
        ELSE
            v_require_kyc := COALESCE(
                (v_event_eligibility->>'upline_require_kyc')::BOOLEAN,
                (v_eligibility->>'require_kyc')::BOOLEAN,
                false
            );
        END IF;

        IF v_require_kyc THEN
            DECLARE
                v_target_kyc TEXT;
            BEGIN
                SELECT kyc_status INTO v_target_kyc
                FROM public.user_profiles
                WHERE id = v_ancestor.target_id;
                IF v_target_kyc NOT IN ('approved', 'verified') THEN
                    CONTINUE;
                END IF;
            END;
        END IF;

        -- 10. Apply tier multiplier
        SELECT (config_value->>'bonus_multiplier')::NUMERIC INTO v_tier_multiplier
        FROM public.reward_configuration
        WHERE config_key = 'tier_' || COALESCE(v_balance_record.tier, 'bronze') AND is_active = true;

        v_points := ROUND(v_points * COALESCE(v_tier_multiplier, 1));

        IF v_points <= 0 THEN CONTINUE; END IF;

        -- 11. Check daily cap
        SELECT points_earned_today INTO v_earned_today
        FROM public.reward_daily_caps
        WHERE user_id = v_ancestor.target_id AND cap_date = CURRENT_DATE;

        SELECT (config_value->>'max_points')::BIGINT INTO v_daily_cap
        FROM public.reward_configuration WHERE config_key = 'daily_cap';

        IF COALESCE(v_earned_today, 0) + v_points > COALESCE(v_daily_cap, 999999999) THEN
            v_points := GREATEST(0, COALESCE(v_daily_cap, 999999999) - COALESCE(v_earned_today, 0));
        END IF;

        IF v_points <= 0 THEN CONTINUE; END IF;

        -- 12. Insert transaction with idempotency guard and auto-scratch for daily login
        INSERT INTO public.reward_transactions (
            user_id, source_user_id, event_type, points, points_before, points_after,
            level, reference_id, reference_type, description, is_scratched
        )
        VALUES (
            v_ancestor.target_id, p_source_user_id, p_event_type::reward_event_type,
            v_points, v_balance_record.current_balance, v_balance_record.current_balance + v_points,
            v_ancestor.level, p_reference_id, p_reference_type,
            CASE 
                WHEN v_ancestor.level = 0 THEN 'Direct reward for ' || p_event_type
                ELSE 'Referral reward from ' || p_event_type || ' at level ' || v_ancestor.level
            END,
            (p_event_type = 'daily_login') -- Mark as scratched for daily login to bypass scratch card UI
        )
        ON CONFLICT DO NOTHING;

        GET DIAGNOSTICS v_rows_inserted = ROW_COUNT;

        IF v_rows_inserted = 0 THEN
            CONTINUE;
        END IF;

        -- 13. Update balance
        UPDATE public.reward_points_balance
        SET current_balance = current_balance + v_points,
            total_earned = total_earned + v_points,
            updated_at = now()
        WHERE user_id = v_ancestor.target_id;

        -- 14. Update user_profiles total
        UPDATE public.user_profiles
        SET total_reward_points_earned = COALESCE(total_reward_points_earned, 0) + v_points
        WHERE id = v_ancestor.target_id;

        -- 15. Update daily cap tracking
        INSERT INTO public.reward_daily_caps (user_id, cap_date, points_earned_today, transactions_today)
        VALUES (v_ancestor.target_id, CURRENT_DATE, v_points, 1)
        ON CONFLICT (user_id, cap_date)
        DO UPDATE SET
            points_earned_today = reward_daily_caps.points_earned_today + v_points,
            transactions_today = reward_daily_caps.transactions_today + 1,
            last_updated = now();

        v_total_distributed := v_total_distributed + v_points;
    END LOOP;

    INSERT INTO public.reward_distribution_log (event_type, source_user_id, reference_id, reference_type, amount_paise, success, total_distributed, error_message) 
    VALUES (p_event_type, p_source_user_id, p_reference_id, p_reference_type, p_amount_paise, true, v_total_distributed, 'Rewards distributed successfully');

    RETURN jsonb_build_object(
        'success', true, 
        'total_distributed', v_total_distributed, 
        'message', 'Rewards distributed successfully'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_platform_inventory_stock_update()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Block any stock_quantity change when caller is a client role (authenticated/anon)
    -- SECURITY DEFINER functions run as postgres, bypassing this check.
    IF NEW.stock_quantity <> OLD.stock_quantity THEN
        IF current_user IN ('authenticated', 'anon') THEN
            RAISE EXCEPTION 'Direct stock updates are not permitted. Platform stock is managed via purchase_platform_products_bulk. Custom product stock can be updated via update_merchant_inventory_stock RPC.';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_crm_leads_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    actor_id_val UUID;
BEGIN
    actor_id_val := auth.uid();

    IF (TG_OP = 'UPDATE') THEN
        INSERT INTO public.audit_logs_crm (actor_id, action, table_name, record_id, old_data, new_data)
        VALUES (
            actor_id_val,
            'UPDATE',
            'crm_leads',
            NEW.id,
            to_jsonb(OLD),
            to_jsonb(NEW)
        );
        RETURN NEW;
    ELSIF (TG_OP = 'INSERT') THEN
        INSERT INTO public.audit_logs_crm (actor_id, action, table_name, record_id, old_data, new_data)
        VALUES (
            actor_id_val,
            'INSERT',
            'crm_leads',
            NEW.id,
            NULL,
            to_jsonb(NEW)
        );
        RETURN NEW;
    ELSIF (TG_OP = 'DELETE') THEN
        INSERT INTO public.audit_logs_crm (actor_id, action, table_name, record_id, old_data, new_data)
        VALUES (
            actor_id_val,
            'DELETE',
            'crm_leads',
            OLD.id,
            to_jsonb(OLD),
            NULL
        );
        RETURN OLD;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_bulk_preview_team_for_location(p_locations jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_loc_record JSONB;
    v_result JSONB = '[]'::JSONB;
    v_team_id UUID;
    v_match_type territory_area_type;
    v_team_name TEXT;
BEGIN
    FOR v_loc_record IN SELECT * FROM jsonb_array_elements(p_locations)
    LOOP
        v_team_id := NULL;
        v_match_type := NULL;
        v_team_name := NULL;

        -- Look up routing using the existing matching function
        SELECT out_team_id, out_match_type
        INTO v_team_id, v_match_type
        FROM public.crm_match_team_for_location(
            (v_loc_record->>'pincode')::text,
            (v_loc_record->>'zone')::text,
            (v_loc_record->>'area')::text,
            (v_loc_record->>'city')::text,
            (v_loc_record->>'state')::text
        );

        IF v_team_id IS NOT NULL THEN
            SELECT name INTO v_team_name FROM public.teams WHERE id = v_team_id;

            v_result := v_result || jsonb_build_object(
                'index', (v_loc_record->>'index')::int,
                'matched', true,
                'team_id', v_team_id,
                'match_type', v_match_type,
                'team_name', COALESCE(v_team_name, 'Unknown Team')
            );
        ELSE
            v_result := v_result || jsonb_build_object(
                'index', (v_loc_record->>'index')::int,
                'matched', false
            );
        END IF;
    END LOOP;

    RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.customer_checkout_v4(p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_total_paise        BIGINT := 0;
    v_wallet_balance     BIGINT;
    v_cart_items         RECORD;
    v_group_id           UUID;
    v_item               RECORD;
    v_merchant_id        UUID;
    v_is_platform        BOOLEAN;
    v_delivery_address   TEXT;
    v_customer_name      TEXT;
    v_customer_phone     TEXT;
    v_item_total         BIGINT;
    v_product_cost       BIGINT;
    v_commission_paise   BIGINT;
    v_total_platform_cut BIGINT := 0;
    v_delivery_fee_paise BIGINT;
BEGIN
    SELECT balance_paise INTO v_wallet_balance
    FROM public.customer_wallets
    WHERE user_id = p_customer_id;

    IF v_wallet_balance IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Wallet not found');
    END IF;

    SELECT full_name, phone, address
    INTO v_customer_name, v_customer_phone, v_delivery_address
    FROM public.user_profiles
    WHERE id = p_customer_id;

    IF v_delivery_address IS NULL OR v_delivery_address = '' THEN
        SELECT full_address INTO v_delivery_address
        FROM public.kyc_records
        WHERE user_id = p_customer_id;
    END IF;

    SELECT is_platform_item INTO v_is_platform
    FROM public.shopping_cart
    WHERE customer_id = p_customer_id
    LIMIT 1;

    IF v_is_platform IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Cart is empty');
    END IF;

    IF NOT v_is_platform THEN
        SELECT mi.merchant_id INTO v_merchant_id
        FROM public.shopping_cart sc
        JOIN public.merchant_inventory mi ON sc.inventory_id = mi.id
        WHERE sc.customer_id = p_customer_id
        LIMIT 1;
    END IF;

    -- Fetch delivery fee dynamically from platform_settings
    SELECT COALESCE(value::BIGINT, 9900) INTO v_delivery_fee_paise
    FROM public.platform_settings
    WHERE key = 'delivery_fee_paise';

    IF v_delivery_fee_paise IS NULL THEN
        v_delivery_fee_paise := 9900;
    END IF;

    -- ── Totalling loop: validate stock + compute total ───────────────
    FOR v_cart_items IN
        SELECT
            c.*,
            CASE WHEN c.is_platform_item
                 THEN COALESCE(p.platform_price_paise, p.suggested_retail_price_paise)
                 ELSE COALESCE(NULLIF(mi.retail_price_paise, 0), p.suggested_retail_price_paise)
            END                    AS effective_price,
            mi.stock_quantity      AS merchant_stock,
            p.admin_stock          AS platform_stock,
            p.title                AS product_title,
            p.gst_percentage       AS gst_pct
        FROM public.shopping_cart c
        LEFT JOIN public.merchant_inventory mi ON c.inventory_id = mi.id
        JOIN  public.shopping_products      p  ON c.product_id  = p.id
        WHERE c.customer_id = p_customer_id
    LOOP
        v_total_paise := v_total_paise
            + (v_cart_items.effective_price * v_cart_items.quantity)
            + ROUND(v_cart_items.effective_price * v_cart_items.quantity
                    * COALESCE(v_cart_items.gst_pct, 0) / 100);

        IF v_cart_items.is_platform_item THEN
            IF v_cart_items.platform_stock < v_cart_items.quantity THEN
                RETURN jsonb_build_object('success', false, 'message',
                    'Insufficient platform stock for ' || v_cart_items.product_title);
            END IF;
        ELSE
            IF v_cart_items.merchant_stock < v_cart_items.quantity THEN
                RETURN jsonb_build_object('success', false, 'message',
                    'Insufficient merchant stock for ' || v_cart_items.product_title);
            END IF;
        END IF;
    END LOOP;

    v_total_paise := v_total_paise + v_delivery_fee_paise;

    IF v_wallet_balance < v_total_paise THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient wallet balance');
    END IF;

    -- Defer settlement: settlement_status stays 'pending'
    -- status = 'completed' because wallet orders are pre-paid
    INSERT INTO public.shopping_order_groups (
        customer_id, customer_name, customer_phone,
        total_amount_paise, status, payment_status, delivery_status,
        merchant_id, is_platform_order, delivery_address,
        delivery_fee_paise, payment_method, settlement_status
    )
    VALUES (
        p_customer_id, v_customer_name, v_customer_phone,
        v_total_paise, 'completed', 'paid', 'pending',
        v_merchant_id, v_is_platform, v_delivery_address,
        v_delivery_fee_paise, 'wallet',
        'pending'
    )
    RETURNING id INTO v_group_id;

    -- ── Item-processing loop: deduct stock + insert order items ──────
    FOR v_item IN
        SELECT
            c.*,
            CASE WHEN c.is_platform_item
                 THEN COALESCE(p.platform_price_paise, p.suggested_retail_price_paise)
                 ELSE COALESCE(NULLIF(mi.retail_price_paise, 0), p.suggested_retail_price_paise)
            END                    AS effective_price,
            mi.merchant_id,
            p.wholesale_price_paise AS platform_cost,
            p.gst_percentage        AS gst_pct
        FROM public.shopping_cart c
        LEFT JOIN public.merchant_inventory mi ON c.inventory_id = mi.id
        JOIN  public.shopping_products      p  ON c.product_id  = p.id
        WHERE c.customer_id = p_customer_id
    LOOP
        v_item_total := v_item.effective_price * v_item.quantity;

        IF v_item.is_platform_item THEN
            UPDATE public.shopping_products
            SET admin_stock = admin_stock - v_item.quantity, updated_at = now()
            WHERE id = v_item.product_id;

            -- auto-delist when stock reaches zero after this sale
            UPDATE public.shopping_products
            SET platform_listed = false
            WHERE id = v_item.product_id
              AND admin_stock = 0;

            INSERT INTO public.shopping_order_items (
                group_id, seller_id, product_id, inventory_id,
                quantity, unit_price_paise, cost_price_paise, profit_paise, gst_amount_paise
            ) VALUES (
                v_group_id, NULL, v_item.product_id, NULL,
                v_item.quantity, v_item.effective_price, v_item.platform_cost,
                (v_item.effective_price - COALESCE(v_item.platform_cost, 0)) * v_item.quantity,
                ROUND(v_item.effective_price * v_item.quantity * COALESCE(v_item.gst_pct, 0) / 100)
            );

        ELSE
            -- 30% commission on profit margin
            v_product_cost     := COALESCE(v_item.platform_cost, 0);
            v_commission_paise := GREATEST(0,
                (v_item.effective_price - v_product_cost) * v_item.quantity * 30 / 100);
            v_total_platform_cut := v_total_platform_cut + v_commission_paise;

            UPDATE public.merchant_inventory
            SET stock_quantity = stock_quantity - v_item.quantity, updated_at = now()
            WHERE id = v_item.inventory_id;

            INSERT INTO public.shopping_order_items (
                group_id, seller_id, product_id, inventory_id,
                quantity, unit_price_paise, cost_price_paise,
                profit_paise, commission_amount_paise, gst_amount_paise
            ) VALUES (
                v_group_id, v_item.merchant_id, v_item.product_id, v_item.inventory_id,
                v_item.quantity, v_item.effective_price, v_product_cost,
                (v_item_total - v_commission_paise) - (v_product_cost * v_item.quantity),
                v_commission_paise,
                ROUND(v_item.effective_price * v_item.quantity * COALESCE(v_item.gst_pct, 0) / 100)
            );

            INSERT INTO public.notifications (
                user_id, title, body, type, reference_id, reference_type
            )
            SELECT user_id, 'New Order Received 🛒',
                   'A customer placed an order. Check your orders page.',
                   'success', v_group_id, 'shopping_order'
            FROM public.merchants WHERE id = v_item.merchant_id;
        END IF;
    END LOOP;

    IF NOT v_is_platform THEN
        UPDATE public.shopping_order_groups
        SET commission_rate       = 0.30,
            platform_cut_paise    = v_total_platform_cut,
            merchant_profit_paise = (
                SELECT SUM((i.unit_price_paise - COALESCE(p.wholesale_price_paise, 0))
                           * i.quantity) - v_total_platform_cut
                FROM public.shopping_order_items i
                JOIN public.shopping_products    p ON i.product_id = p.id
                WHERE i.group_id = v_group_id
            )
        WHERE id = v_group_id;
    END IF;

    UPDATE public.customer_wallets
    SET balance_paise = balance_paise - v_total_paise, updated_at = now()
    WHERE user_id = p_customer_id;

    INSERT INTO public.customer_wallet_transactions (
        wallet_id, user_id, type, amount_paise,
        balance_before_paise, balance_after_paise, description
    ) VALUES (
        (SELECT id FROM public.customer_wallets WHERE user_id = p_customer_id),
        p_customer_id, 'DEBIT', v_total_paise,
        v_wallet_balance, v_wallet_balance - v_total_paise,
        'Shopping Purchase: Order Group ' || v_group_id
    );

    DELETE FROM public.shopping_cart WHERE customer_id = p_customer_id;

    RETURN jsonb_build_object('success', true, 'group_id', v_group_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.distribute_merchant_referral_reward(p_new_merchant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_prize_paise BIGINT;
    v_referrer_id UUID;
    v_balance_before BIGINT;
    v_balance_after BIGINT;
    v_already_paid BOOLEAN;
BEGIN
    -- Guard: check if referral reward already paid
    SELECT referral_reward_paid INTO v_already_paid
    FROM public.merchants
    WHERE id = p_new_merchant_id;

    IF v_already_paid IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Merchant not found');
    END IF;

    IF v_already_paid THEN
        RETURN jsonb_build_object('success', false, 'message', 'Referral reward already distributed');
    END IF;

    -- Get prize amount
    SELECT value::BIGINT INTO v_prize_paise
    FROM public.platform_settings
    WHERE key = 'merchant_referral_prize_paise';

    IF v_prize_paise IS NULL THEN
        RAISE EXCEPTION 'platform_settings key merchant_referral_prize_paise missing or invalid';
    END IF;

    -- Get level-1 referrer
    SELECT ancestor_id INTO v_referrer_id
    FROM public.merchant_tree_paths
    WHERE descendant_id = p_new_merchant_id AND level = 1;

    IF v_referrer_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'No referrer found');
    END IF;

    -- Lock referrer wallet and get current balance
    SELECT wallet_balance_paise INTO v_balance_before
    FROM public.merchants
    WHERE id = v_referrer_id
    FOR UPDATE;

    v_balance_after := v_balance_before + v_prize_paise;

    -- Credit referrer
    UPDATE public.merchants
    SET wallet_balance_paise = v_balance_after
    WHERE id = v_referrer_id;

    -- Insert ledger entry
    INSERT INTO public.merchant_transactions (
        merchant_id,
        transaction_type,
        amount_paise,
        balance_after_paise,
        description
    ) VALUES (
        v_referrer_id,
        'referral_reward',
        v_prize_paise,
        v_balance_after,
        'Merchant referral reward for merchant ' || p_new_merchant_id
    );

    -- Mark as paid for the new merchant
    UPDATE public.merchants
    SET referral_reward_paid = true
    WHERE id = p_new_merchant_id;

    RETURN jsonb_build_object(
        'success', true, 
        'referrer_id', v_referrer_id, 
        'prize_paise', v_prize_paise
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.draft_cart_orders(p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_total_paise        BIGINT := 0;
    v_cart_items         RECORD;
    v_group_id           UUID;
    v_merchant_id        UUID;
    v_is_platform        BOOLEAN;
    v_delivery_address   TEXT;
    v_customer_name      TEXT;
    v_customer_phone     TEXT;
    v_delivery_fee_paise BIGINT;
    v_item               RECORD;
BEGIN
    -- 1. Get Customer Details and Delivery Address from profile
    SELECT full_name, phone, address INTO v_customer_name, v_customer_phone, v_delivery_address
    FROM public.user_profiles
    WHERE id = p_customer_id;

    -- Fallback for address from KYC if profile is incomplete
    IF v_delivery_address IS NULL OR v_delivery_address = '' THEN
        SELECT full_address INTO v_delivery_address
        FROM public.kyc_records
        WHERE user_id = p_customer_id;
    END IF;

    -- 2. Identify Merchant/Platform and Validate Stock
    SELECT is_platform_item INTO v_is_platform
    FROM public.shopping_cart
    WHERE customer_id = p_customer_id
    LIMIT 1;

    IF v_is_platform IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Cart is empty');
    END IF;

    IF NOT v_is_platform THEN
        SELECT mi.merchant_id INTO v_merchant_id
        FROM public.shopping_cart sc
        JOIN public.merchant_inventory mi ON sc.inventory_id = mi.id
        WHERE sc.customer_id = p_customer_id
        LIMIT 1;
    END IF;

    -- Fetch delivery fee dynamically from platform_settings
    SELECT COALESCE(value::BIGINT, 9900) INTO v_delivery_fee_paise
    FROM public.platform_settings
    WHERE key = 'delivery_fee_paise';

    IF v_delivery_fee_paise IS NULL THEN
        v_delivery_fee_paise := 9900;
    END IF;

    -- ── Totalling loop ───────────────────────────────────────────────
    FOR v_cart_items IN
        SELECT
            c.*,
            CASE WHEN c.is_platform_item
                 THEN COALESCE(p.platform_price_paise, p.suggested_retail_price_paise)
                 ELSE COALESCE(mi.retail_price_paise, p.suggested_retail_price_paise)
            END                AS effective_price,
            mi.stock_quantity  AS merchant_stock,
            p.admin_stock      AS platform_stock,
            p.title            AS product_title,
            p.gst_percentage
        FROM public.shopping_cart c
        LEFT JOIN public.merchant_inventory mi ON c.inventory_id = mi.id
        JOIN  public.shopping_products      p  ON c.product_id  = p.id
        WHERE c.customer_id = p_customer_id
    LOOP
        v_total_paise := v_total_paise + (v_cart_items.effective_price * v_cart_items.quantity);

        -- Add GST
        v_total_paise := v_total_paise + ROUND((v_cart_items.effective_price
                            * v_cart_items.quantity
                            * v_cart_items.gst_percentage / 100.0));

        IF v_cart_items.is_platform_item THEN
            IF v_cart_items.platform_stock < v_cart_items.quantity THEN
                RETURN jsonb_build_object('success', false, 'message',
                    'Insufficient platform stock for ' || v_cart_items.product_title);
            END IF;
        ELSE
            IF v_cart_items.merchant_stock < v_cart_items.quantity THEN
                RETURN jsonb_build_object('success', false, 'message',
                    'Insufficient merchant stock for ' || v_cart_items.product_title);
            END IF;
        END IF;
    END LOOP;

    v_total_paise := v_total_paise + v_delivery_fee_paise;

    -- 2.5 Cancel previous pending gateway drafts for this user
    UPDATE public.shopping_order_groups
    SET status = 'cancelled'
    WHERE customer_id = p_customer_id
      AND status = 'pending'
      AND payment_method = 'gateway';

    -- 3. CREATE ORDER GROUP
    INSERT INTO public.shopping_order_groups (
        customer_id, customer_name, customer_phone,
        total_amount_paise, status, delivery_status,
        merchant_id, is_platform_order, delivery_address,
        delivery_fee_paise, payment_method
    )
    VALUES (
        p_customer_id, v_customer_name, v_customer_phone,
        v_total_paise, 'pending', 'pending',
        v_merchant_id, v_is_platform, v_delivery_address,
        v_delivery_fee_paise, 'gateway'
    )
    RETURNING id INTO v_group_id;

    -- 4. PROCESS ITEMS
    FOR v_item IN
        SELECT
            c.*,
            CASE WHEN c.is_platform_item
                 THEN COALESCE(p.platform_price_paise, p.suggested_retail_price_paise)
                 ELSE COALESCE(mi.retail_price_paise, p.suggested_retail_price_paise)
            END                AS effective_price,
            mi.merchant_id,
            p.wholesale_price_paise AS platform_cost
        FROM public.shopping_cart c
        LEFT JOIN public.merchant_inventory mi ON c.inventory_id = mi.id
        JOIN  public.shopping_products      p  ON c.product_id  = p.id
        WHERE c.customer_id = p_customer_id
    LOOP
        IF v_item.is_platform_item AND v_item.merchant_id IS NULL THEN
            INSERT INTO public.shopping_order_items (
                group_id, seller_id, product_id, inventory_id, quantity,
                unit_price_paise, cost_price_paise, profit_paise
            ) VALUES (
                v_group_id, NULL, v_item.product_id, NULL, v_item.quantity,
                v_item.effective_price, v_item.platform_cost,
                (v_item.effective_price - COALESCE(v_item.platform_cost, 0)) * v_item.quantity
            );
        ELSE
            -- Merchant item OR platform item sold through merchant inventory
            INSERT INTO public.shopping_order_items (
                group_id, seller_id, product_id, inventory_id, quantity,
                unit_price_paise, cost_price_paise, profit_paise
            ) VALUES (
                v_group_id, v_item.merchant_id, v_item.product_id, v_item.inventory_id,
                v_item.quantity, v_item.effective_price,
                0,
                0
            );
        END IF;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'group_id', v_group_id, 'total_paise', v_total_paise);
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_request_payout(p_user_id uuid, p_amount_paise bigint, p_source text, p_reference_id uuid, p_idempotency_key text, p_requested_ip text DEFAULT NULL::text, p_requested_user_agent text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_merchant          record;
    v_settings          record;
    v_min_paise         bigint;
    v_max_paise         bigint;
    v_max_day_paise     bigint;
    v_max_month_paise   bigint;
    v_max_pending_count bigint;
    v_existing          uuid;
    v_contract          record;
    v_rows              integer;
    v_request_id        uuid;
    v_new_balance       bigint;
    v_balance_before    bigint;
    v_bank_account      text;
    v_bank_ifsc         text;
    v_bank_holder       text;
    v_bank_name         text;
    v_day_total         bigint;
    v_month_total       bigint;
    v_pending_count     bigint;
BEGIN
    -- =========================================================================
    -- PHASE 1: ALL VALIDATION — no DML until this entire phase passes
    -- =========================================================================

    -- 0. Read all velocity-limit settings in one pass.
    --    NOTE: payout_max_pending_count has NO COALESCE fallback — NULL = unlimited.
    SELECT
        COALESCE(MAX(CASE WHEN key = 'payout_min_amount_paise'    THEN value::bigint END), 10000) AS min_paise,
        MAX(CASE WHEN key = 'payout_max_amount_paise'    THEN value::bigint END)                  AS max_paise,
        MAX(CASE WHEN key = 'payout_max_per_day_paise'   THEN value::bigint END)                  AS max_day_paise,
        MAX(CASE WHEN key = 'payout_max_per_month_paise' THEN value::bigint END)                  AS max_month_paise,
        MAX(CASE WHEN key = 'payout_max_pending_count'   THEN value::bigint END)                  AS max_pending_count
    INTO v_settings
    FROM platform_settings
    WHERE key IN (
        'payout_min_amount_paise', 'payout_max_amount_paise',
        'payout_max_per_day_paise', 'payout_max_per_month_paise',
        'payout_max_pending_count'
    );

    v_min_paise         := v_settings.min_paise;
    v_max_paise         := v_settings.max_paise;         -- NULL means unlimited
    v_max_day_paise     := v_settings.max_day_paise;     -- NULL means unlimited
    v_max_month_paise   := v_settings.max_month_paise;   -- NULL means unlimited
    v_max_pending_count := v_settings.max_pending_count; -- NULL means unlimited

    -- 1. Lock merchant row (FOR UPDATE acquires the row lock for later mutation)
    SELECT id, wallet_balance_paise, bank_verified, bank_data, status
    INTO   v_merchant
    FROM   merchants
    WHERE  user_id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_found');
    END IF;

    -- 2. Merchant must be approved
    IF v_merchant.status <> 'approved' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_approved');
    END IF;

    -- 3. Bank must be verified
    IF v_merchant.bank_verified IS NOT TRUE THEN
        RETURN jsonb_build_object('success', false, 'error', 'bank_not_verified');
    END IF;

    -- 3a. Validate bank data snapshot NOW — before any mutation.
    --     bank_verified=true does NOT guarantee all required keys are present;
    --     validate here so a missing key can never cause a post-mutation RETURN.
    v_bank_account := NULLIF(TRIM((v_merchant.bank_data->>'account_number')::text), '');
    v_bank_ifsc    := NULLIF(TRIM(COALESCE(v_merchant.bank_data->>'ifsc', v_merchant.bank_data->>'ifsc_code', '')), '');
    v_bank_holder  := NULLIF(TRIM(COALESCE(
                        v_merchant.bank_data->>'name',
                        v_merchant.bank_data->>'account_holder_name',
                        v_merchant.bank_data->>'beneficiary_name', ''
                      )), '');
    v_bank_name    := NULLIF(TRIM(COALESCE(v_merchant.bank_data->>'bank_name', '')), '');

    IF v_bank_account IS NULL OR v_bank_ifsc IS NULL OR v_bank_holder IS NULL THEN
        -- Safe RETURN here: no DML has run yet.
        RETURN jsonb_build_object('success', false, 'error', 'invalid_bank_data');
    END IF;

    -- 4. Idempotency check (BEFORE any debit)
    IF p_idempotency_key IS NOT NULL THEN
        SELECT id
        INTO   v_existing
        FROM   payout_requests
        WHERE  merchant_id      = v_merchant.id
          AND  idempotency_key  = p_idempotency_key
        LIMIT  1;

        IF FOUND THEN
            RETURN jsonb_build_object(
                'success',    true,
                'request_id', v_existing,
                'replayed',   true
            );
        END IF;
    END IF;

    -- 5. Velocity: minimum amount
    IF p_amount_paise < v_min_paise THEN
        RETURN jsonb_build_object('success', false, 'error', 'amount_below_min');
    END IF;

    -- 6. Velocity: maximum amount (when configured)
    IF v_max_paise IS NOT NULL AND p_amount_paise > v_max_paise THEN
        RETURN jsonb_build_object('success', false, 'error', 'amount_above_max');
    END IF;

    -- 7. Velocity: daily cap (when configured)
    IF v_max_day_paise IS NOT NULL THEN
        SELECT COALESCE(SUM(amount_paise), 0)
        INTO   v_day_total
        FROM   payout_requests
        WHERE  merchant_id   = v_merchant.id
          AND  status        NOT IN ('rejected')
          AND  requested_at >= date_trunc('day', now() AT TIME ZONE 'UTC');

        IF v_day_total + p_amount_paise > v_max_day_paise THEN
            RETURN jsonb_build_object('success', false, 'error', 'daily_cap_exceeded');
        END IF;
    END IF;

    -- 8. Velocity: monthly cap (when configured)
    IF v_max_month_paise IS NOT NULL THEN
        SELECT COALESCE(SUM(amount_paise), 0)
        INTO   v_month_total
        FROM   payout_requests
        WHERE  merchant_id   = v_merchant.id
          AND  status        NOT IN ('rejected')
          AND  requested_at >= date_trunc('month', now() AT TIME ZONE 'UTC');

        IF v_month_total + p_amount_paise > v_max_month_paise THEN
            RETURN jsonb_build_object('success', false, 'error', 'monthly_cap_exceeded');
        END IF;
    END IF;

    -- 9. Velocity: max simultaneous pending requests (per source) — SKIPPED when cap is NULL (unlimited)
    IF v_max_pending_count IS NOT NULL THEN
        SELECT COUNT(*)
        INTO   v_pending_count
        FROM   payout_requests
        WHERE  merchant_id   = v_merchant.id
          AND  payout_source = p_source
          AND  status        = 'pending';

        IF v_pending_count >= v_max_pending_count THEN
            RETURN jsonb_build_object('success', false, 'error', 'pending_count_exceeded');
        END IF;
    END IF;

    -- 9a. Growth-fund: pre-validate contract BEFORE the debit phase.
    --     FOR UPDATE lock is re-used in phase 2 via the same txn.
    IF p_source = 'growth_fund' THEN
        IF p_reference_id IS NULL THEN
            RETURN jsonb_build_object('success', false, 'error', 'contract_not_found');
        END IF;

        SELECT *
        INTO   v_contract
        FROM   merchant_lockin_balances
        WHERE  id          = p_reference_id
          AND  merchant_id = v_merchant.id
        FOR UPDATE;

        IF NOT FOUND THEN
            RETURN jsonb_build_object('success', false, 'error', 'contract_not_found');
        END IF;

        -- Contract-scoped duplicate guard
        IF v_contract.status = 'payout_requested' THEN
            RETURN jsonb_build_object('success', false, 'error', 'growth_fund_already_requested');
        END IF;

        -- Only matured contracts may be paid out
        IF v_contract.status <> 'matured' THEN
            RETURN jsonb_build_object('success', false, 'error', 'contract_not_matured');
        END IF;

        IF (v_contract.amount_paise + COALESCE(v_contract.accumulated_interest_paise, 0)) <> p_amount_paise THEN
            RETURN jsonb_build_object('success', false, 'error', 'incorrect_maturity_amount');
        END IF;
    END IF;

    -- 9b. Wallet: pre-validate sufficient balance BEFORE the debit phase.
    IF p_source = 'wallet' THEN
        IF v_merchant.wallet_balance_paise < p_amount_paise THEN
            -- Safe RETURN: no DML yet.
            RETURN jsonb_build_object('success', false, 'error', 'insufficient_balance');
        END IF;
        v_balance_before := v_merchant.wallet_balance_paise;
    END IF;

    -- =========================================================================
    -- PHASE 2: MUTATIONS — all validation has passed; failures here RAISE so
    --           Postgres rolls back the entire transaction automatically.
    -- =========================================================================

    -- 10. Source-specific debit / contract lock
    IF p_source = 'wallet' THEN
        -- Double-checked locking: re-assert balance inside the UPDATE predicate
        -- to guard against a concurrent debit between the SELECT FOR UPDATE and here.
        UPDATE merchants
        SET    wallet_balance_paise = wallet_balance_paise - p_amount_paise
        WHERE  id                  = v_merchant.id
          AND  wallet_balance_paise >= p_amount_paise;

        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_rows = 0 THEN
            -- A concurrent transaction drained the balance between validation and debit.
            -- RAISE so the whole txn rolls back — no orphaned debit possible.
            RAISE EXCEPTION 'payout_insufficient_balance_concurrent'
                USING ERRCODE = 'P0001';
        END IF;

        -- Re-read balance after debit for accurate audit trail
        SELECT wallet_balance_paise
        INTO   v_new_balance
        FROM   merchants
        WHERE  id = v_merchant.id;

    ELSIF p_source = 'growth_fund' THEN
        -- Contract already FOR UPDATE locked in phase 1 (step 9a); just flip it.
        UPDATE merchant_lockin_balances
        SET    status = 'payout_requested'
        WHERE  id     = p_reference_id;

        v_balance_before := NULL;
        v_new_balance    := NULL;

    ELSE
        -- Should be unreachable: source was validated in phase 1.
        -- RAISE here to be safe; plain RETURN after a mutation would be wrong.
        RAISE EXCEPTION 'invalid_payout_source: %', p_source
            USING ERRCODE = 'P0001';
    END IF;

    -- 11. Insert payout_requests row
    --     IMPORTANT: amount_paise is a generated column ((amount * 100)::bigint) STORED,
    --     so we must NOT insert into it directly. It will be computed automatically from amount.
    INSERT INTO payout_requests (
        merchant_id, user_id, amount, status,
        bank_account_number, bank_ifsc, bank_account_holder, bank_name,
        payout_source, reference_id,
        idempotency_key, requested_ip, requested_user_agent
    )
    VALUES (
        v_merchant.id, p_user_id, (p_amount_paise::numeric / 100), 'pending',
        v_bank_account, v_bank_ifsc, v_bank_holder, v_bank_name,
        p_source, p_reference_id,
        p_idempotency_key, p_requested_ip, p_requested_user_agent
    )
    RETURNING id INTO v_request_id;

    -- 12. Wallet transaction audit trail (wallet branch only)
    --     balance_before captured in phase 1; balance_after re-read after debit.
    IF p_source = 'wallet' THEN
        INSERT INTO wallet_transactions (
            user_id, merchant_id, transaction_type, amount,
            balance_before, balance_after,
            description, reference_type, reference_id
        )
        VALUES (
            p_user_id,
            v_merchant.id,
            'DEBIT',
            (p_amount_paise::numeric / 100),
            (v_balance_before::numeric / 100),
            (v_new_balance::numeric  / 100),
            'Wallet payout request #' || UPPER(LEFT(v_request_id::text, 8)) || ' submitted',
            'payout_request',
            v_request_id
        );
    END IF;

    -- 13. Audit event
    INSERT INTO payout_request_events (
        payout_id, actor_id, action, from_status, to_status, payload
    )
    VALUES (
        v_request_id, p_user_id, 'requested', NULL, 'pending',
        jsonb_build_object('amount_paise', p_amount_paise, 'source', p_source)
    );

    -- 14. Return success
    RETURN jsonb_build_object(
        'success',             true,
        'request_id',          v_request_id,
        'balance_after_paise', v_new_balance,
        'replayed',            false
    );

EXCEPTION WHEN OTHERS THEN
    -- Re-raise everything so the caller (PostgREST / Supabase JS) sees an
    -- HTTP 500 and the transaction is definitively rolled back.
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.convert_points_to_wallet(p_user_id uuid, p_points bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_caller_uid UUID;
    v_caller_role TEXT;
    v_point_value NUMERIC;
    v_rupee_paise BIGINT;
    v_current_points BIGINT;
    v_min_withdrawal BIGINT;
    v_wallet_id UUID;
    v_wallet_balance BIGINT;
    v_redemption_mode TEXT;
    v_is_admin BOOLEAN := false;
BEGIN
    -- ── Authorization guard ────────────────────────────────────────────────
    -- Allow: service_role (admin API routes) OR the user themselves
    v_caller_uid := auth.uid();

    -- Check if caller is an admin (service_role calls have uid = NULL in SECURITY DEFINER)
    IF v_caller_uid IS NULL THEN
        -- Called from service_role (admin API) — always allowed
        v_is_admin := true;
    ELSE
        -- Check user role
        SELECT role::TEXT INTO v_caller_role
        FROM public.user_profiles
        WHERE id = v_caller_uid;

        IF v_caller_role IN ('admin', 'super_admin') THEN
            v_is_admin := true;
        ELSIF v_caller_uid <> p_user_id THEN
            RETURN jsonb_build_object('success', false, 'message', 'Forbidden: you may only redeem your own points');
        END IF;
    END IF;

    -- ── Business validation ────────────────────────────────────────────────
    SELECT (config_value->>'min_withdrawal_points')::BIGINT INTO v_min_withdrawal
    FROM public.reward_configuration WHERE config_key = 'point_value';

    IF p_points < COALESCE(v_min_withdrawal, 100) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Below minimum withdrawal of ' || COALESCE(v_min_withdrawal, 100) || ' points');
    END IF;

    SELECT current_balance INTO v_current_points
    FROM public.reward_points_balance WHERE user_id = p_user_id;

    IF v_current_points IS NULL OR v_current_points < p_points THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient points. Available: ' || COALESCE(v_current_points, 0));
    END IF;

    SELECT (config_value->>'points_per_rupee')::NUMERIC INTO v_point_value
    FROM public.reward_configuration WHERE config_key = 'point_value';

    v_rupee_paise := ROUND((p_points::NUMERIC / COALESCE(v_point_value, 100)) * 100);

    -- ── Deduct points ──────────────────────────────────────────────────────
    UPDATE public.reward_points_balance
    SET current_balance = current_balance - p_points,
        total_redeemed = total_redeemed + p_points,
        updated_at = now()
    WHERE user_id = p_user_id;

    -- Log reward transaction (debit)
    INSERT INTO public.reward_transactions (
        user_id, event_type, points, points_before, points_after,
        description, metadata
    )
    VALUES (
        p_user_id, 'wallet_conversion', -p_points,
        v_current_points, v_current_points - p_points,
        'Converted ' || p_points || ' Intrust Reward Points to wallet',
        jsonb_build_object('rupee_paise', v_rupee_paise, 'points_per_rupee', COALESCE(v_point_value, 100))
    );

    -- ── Credit customer wallet ─────────────────────────────────────────────
    SELECT id, balance_paise INTO v_wallet_id, v_wallet_balance
    FROM public.customer_wallets WHERE user_id = p_user_id;

    IF v_wallet_id IS NULL THEN
        INSERT INTO public.customer_wallets (user_id, balance_paise)
        VALUES (p_user_id, v_rupee_paise)
        RETURNING id INTO v_wallet_id;
        v_wallet_balance := 0;
    ELSE
        UPDATE public.customer_wallets
        SET balance_paise = balance_paise + v_rupee_paise,
            updated_at = now()
        WHERE id = v_wallet_id;
    END IF;

    -- ── Insert wallet transaction log ──────────────────────────────────────
    INSERT INTO public.customer_wallet_transactions (
        wallet_id, user_id, type, amount_paise, balance_before_paise, balance_after_paise,
        description, reference_type
    )
    VALUES (
        v_wallet_id, p_user_id, 'REWARD', v_rupee_paise,
        COALESCE(v_wallet_balance, 0), COALESCE(v_wallet_balance, 0) + v_rupee_paise,
        'Intrust Reward Points conversion: ' || p_points || ' points = ₹' || ROUND(v_rupee_paise / 100.0, 2),
        'REWARD_CONVERSION'
    );

    RETURN jsonb_build_object(
        'success', true,
        'rupee_paise', v_rupee_paise,
        'points_deducted', p_points,
        'new_wallet_balance_paise', COALESCE(v_wallet_balance, 0) + v_rupee_paise
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.customer_bulk_purchase_v2(p_items jsonb[], p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_item JSONB;
    v_inventory RECORD;
    v_product RECORD;
    v_total_cost BIGINT := 0;
    v_customer_balance BIGINT;
    v_item_cost BIGINT;
    v_price_paise BIGINT;
    v_merchant_balance BIGINT;
BEGIN
    -- 1. Pre-validation and total cost calculation
    SELECT wallet_balance_paise INTO v_customer_balance
    FROM public.user_profiles WHERE id = p_customer_id FOR UPDATE;

    FOREACH v_item IN ARRAY p_items LOOP
        IF (v_item->>'is_platform')::BOOLEAN THEN
            SELECT admin_stock, platform_price_paise, suggested_retail_price_paise, title
            INTO v_product
            FROM public.shopping_products
            WHERE id = (v_item->>'product_id')::UUID;

            IF v_product.admin_stock < (v_item->>'quantity')::INTEGER THEN
                RETURN jsonb_build_object('success', false, 'message', 'Insufficient platform stock for ' || v_product.title);
            END IF;

            v_price_paise := COALESCE(v_product.platform_price_paise, v_product.suggested_retail_price_paise);
            v_total_cost  := v_total_cost + (v_price_paise * (v_item->>'quantity')::INTEGER);
        ELSE
            SELECT stock_quantity, retail_price_paise INTO v_inventory
            FROM public.merchant_inventory WHERE id = (v_item->>'inventory_id')::UUID;

            IF v_inventory.stock_quantity < (v_item->>'quantity')::INTEGER THEN
                RETURN jsonb_build_object('success', false, 'message', 'Insufficient merchant stock');
            END IF;

            v_total_cost := v_total_cost + (v_inventory.retail_price_paise * (v_item->>'quantity')::INTEGER);
        END IF;
    END LOOP;

    IF v_customer_balance < v_total_cost THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient wallet balance');
    END IF;

    -- 2. Processing items
    FOREACH v_item IN ARRAY p_items LOOP
        IF (v_item->>'is_platform')::BOOLEAN THEN
            SELECT id, platform_price_paise, suggested_retail_price_paise
            INTO v_product
            FROM public.shopping_products
            WHERE id = (v_item->>'product_id')::UUID
            FOR UPDATE;

            v_price_paise := COALESCE(v_product.platform_price_paise, v_product.suggested_retail_price_paise);
            v_item_cost   := v_price_paise * (v_item->>'quantity')::INTEGER;

            UPDATE public.shopping_products
            SET admin_stock = admin_stock - (v_item->>'quantity')::INTEGER
            WHERE id = v_product.id;

            INSERT INTO public.shopping_orders (
                buyer_id, buyer_type, seller_id, seller_type,
                product_id, quantity, unit_price_paise, total_price_paise, order_type
            )
            VALUES (
                p_customer_id, 'customer', NULL, 'admin',
                v_product.id, (v_item->>'quantity')::INTEGER, v_price_paise, v_item_cost, 'retail'
            );
        ELSE
            SELECT * INTO v_inventory
            FROM public.merchant_inventory
            WHERE id = (v_item->>'inventory_id')::UUID
            FOR UPDATE;

            v_item_cost := v_inventory.retail_price_paise * (v_item->>'quantity')::INTEGER;

            UPDATE public.merchant_inventory
            SET stock_quantity = stock_quantity - (v_item->>'quantity')::INTEGER
            WHERE id = v_inventory.id;

            UPDATE public.merchants
            SET wallet_balance_paise = wallet_balance_paise + v_item_cost
            WHERE id = v_inventory.merchant_id
            RETURNING wallet_balance_paise INTO v_merchant_balance;

            INSERT INTO public.shopping_orders (
                buyer_id, buyer_type, seller_id, seller_type,
                product_id, quantity, unit_price_paise, total_price_paise, order_type
            )
            VALUES (
                p_customer_id, 'customer', v_inventory.merchant_id, 'merchant',
                v_inventory.product_id, (v_item->>'quantity')::INTEGER, v_inventory.retail_price_paise, v_item_cost, 'retail'
            );

            INSERT INTO public.merchant_transactions (
                merchant_id, transaction_type, amount_paise, balance_after_paise, description, metadata
            )
            VALUES (
                v_inventory.merchant_id, 'sale_earnings', v_item_cost, v_merchant_balance,
                'Product sale to customer',
                jsonb_build_object('buyer_id', p_customer_id, 'product_id', v_inventory.product_id)
            );
        END IF;
    END LOOP;

    -- 3. Update customer balance
    UPDATE public.user_profiles
    SET wallet_balance_paise = wallet_balance_paise - v_total_cost
    WHERE id = p_customer_id;

    RETURN jsonb_build_object('success', true, 'message', 'All orders placed successfully');
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_product_slug()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  base_slug TEXT;
  candidate TEXT;
  counter INT := 2;
BEGIN
  IF NEW.slug IS NULL OR NEW.slug = '' OR (TG_OP = 'UPDATE' AND OLD.title IS DISTINCT FROM NEW.title) THEN
    base_slug := lower(regexp_replace(trim(NEW.title), '[^a-zA-Z0-9]+', '-', 'g'));
    base_slug := trim(both '-' from base_slug);
    IF base_slug = '' THEN base_slug := 'product'; END IF;
    candidate := base_slug;
    WHILE EXISTS (
      SELECT 1 FROM shopping_products WHERE slug = candidate AND id IS DISTINCT FROM NEW.id
    ) LOOP
      candidate := base_slug || '-' || counter;
      counter := counter + 1;
    END LOOP;
    NEW.slug := candidate;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_bulk_purchase_coupons(p_coupon_ids uuid[], p_merchant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID;
    v_merchant_id UUID;
    v_merchant_status TEXT;
    v_merchant_balance BIGINT;
    v_total_purchase_price_paise BIGINT := 0;
    v_total_commission_paise BIGINT := 0;
    v_total_cost_paise BIGINT := 0;
    v_new_balance BIGINT;
    v_transaction_id UUID;
    v_user_role TEXT;
    v_coupon RECORD;
    v_purchased_count INTEGER := 0;
BEGIN
    -- Get current user
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Check user role
    SELECT role INTO v_user_role FROM public.user_profiles WHERE id = v_user_id;

    -- Determine merchant_id
    IF v_user_role = 'admin' AND p_merchant_id IS NOT NULL THEN
        v_merchant_id := p_merchant_id;
    ELSE
        -- Get merchant profile for the user
        SELECT id, status, wallet_balance_paise 
        INTO v_merchant_id, v_merchant_status, v_merchant_balance
        FROM public.merchants
        WHERE user_id = v_user_id;
    END IF;

    -- If we selected by ID (admin case), we need to fetch status and balance
    IF v_user_role = 'admin' AND p_merchant_id IS NOT NULL THEN
        SELECT id, status, wallet_balance_paise
        INTO v_merchant_id, v_merchant_status, v_merchant_balance
        FROM public.merchants
        WHERE id = v_merchant_id;
    END IF;

    IF v_merchant_id IS NULL THEN
        RAISE EXCEPTION 'Merchant profile not found';
    END IF;

    IF v_merchant_status != 'approved' THEN
        RAISE EXCEPTION 'Merchant account not approved. Status: %', v_merchant_status;
    END IF;

    -- Validate and calculate totals for all requested coupons
    FOR v_coupon IN 
        SELECT id, brand, title, selling_price_paise, status, valid_until, is_merchant_owned, merchant_id
        FROM public.coupons
        WHERE id = ANY(p_coupon_ids)
        FOR UPDATE
    LOOP
        IF v_coupon.status != 'available' THEN
            RAISE EXCEPTION 'Coupon % is not available', v_coupon.id;
        END IF;

        IF v_coupon.valid_until <= NOW() THEN
            RAISE EXCEPTION 'Coupon % is expired', v_coupon.id;
        END IF;

        IF v_coupon.is_merchant_owned = TRUE OR v_coupon.merchant_id IS NOT NULL THEN
            RAISE EXCEPTION 'Coupon % is already merchant-owned or assigned', v_coupon.id;
        END IF;

        -- Calculate sum
        v_total_purchase_price_paise := v_total_purchase_price_paise + v_coupon.selling_price_paise;
        v_total_commission_paise := v_total_commission_paise + FLOOR(v_coupon.selling_price_paise * 0.03);

        v_purchased_count := v_purchased_count + 1;
    END LOOP;

    IF v_purchased_count = 0 THEN
        RAISE EXCEPTION 'No valid coupons found to purchase';
    END IF;

    IF v_purchased_count != array_length(p_coupon_ids, 1) THEN
         RAISE EXCEPTION 'Mismatch in requested coupons and available coupons';
    END IF;

    v_total_cost_paise := v_total_purchase_price_paise + v_total_commission_paise;

    -- Check merchant balance
    IF v_merchant_balance < v_total_cost_paise THEN
        RAISE EXCEPTION 'Insufficient balance. Required: %, Available: %', 
            v_total_cost_paise, v_merchant_balance;
    END IF;

    -- Deduct from merchant balance
    v_new_balance := v_merchant_balance - v_total_cost_paise;

    UPDATE public.merchants
    SET 
        wallet_balance_paise = v_new_balance,
        total_commission_paid_paise = total_commission_paid_paise + v_total_commission_paise,
        updated_at = NOW()
    WHERE id = v_merchant_id;

    -- Track running balance for individual transaction records
    DECLARE
        v_running_balance BIGINT := v_merchant_balance;
        v_item_cost_paise BIGINT;
    BEGIN
        -- Update coupons to merchant-owned and record individual transactions
        FOR v_coupon IN 
            SELECT id, brand, title, selling_price_paise
            FROM public.coupons
            WHERE id = ANY(p_coupon_ids)
        LOOP
            v_item_cost_paise := v_coupon.selling_price_paise + FLOOR(v_coupon.selling_price_paise * 0.03);
            v_running_balance := v_running_balance - v_item_cost_paise;

            -- Update coupon
            UPDATE public.coupons
            SET 
                merchant_id = v_merchant_id,
                is_merchant_owned = TRUE,
                merchant_purchase_price_paise = v_coupon.selling_price_paise,
                merchant_selling_price_paise = v_coupon.selling_price_paise,
                merchant_commission_paise = FLOOR(v_coupon.selling_price_paise * 0.03),
                listed_on_marketplace = FALSE,
                purchased_by_merchant_at = NOW(),
                updated_at = NOW()
            WHERE id = v_coupon.id;

            -- Record individual transaction
            INSERT INTO public.merchant_transactions (
                merchant_id,
                transaction_type,
                amount_paise,
                commission_paise,
                balance_after_paise,
                coupon_id,
                description,
                metadata
            ) VALUES (
                v_merchant_id,
                'purchase',
                -v_item_cost_paise,
                FLOOR(v_coupon.selling_price_paise * 0.03),
                v_running_balance,
                v_coupon.id,
                FORMAT('Purchased coupon: %s - %s', v_coupon.brand, v_coupon.title),
                jsonb_build_object(
                    'purchase_price_paise', v_coupon.selling_price_paise,
                    'commission_paise', FLOOR(v_coupon.selling_price_paise * 0.03)
                )
            );
        END LOOP;
    END;

    -- Return success
    RETURN jsonb_build_object(
        'success', true,
        'purchased_count', v_purchased_count,
        'total_purchase_price_paise', v_total_purchase_price_paise,
        'total_commission_paise', v_total_commission_paise,
        'total_cost_paise', v_total_cost_paise,
        'new_balance_paise', v_new_balance
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user_wallet()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
BEGIN
  IF NEW.role = 'user'::user_role THEN
    BEGIN
      INSERT INTO public.customer_wallets (user_id)
      VALUES (NEW.id)
      ON CONFLICT (user_id) DO NOTHING;
    EXCEPTION WHEN OTHERS THEN
      RAISE WARNING 'handle_new_user_wallet: failed to create wallet for %, sqlstate=%, sqlerrm=%',
        NEW.id, SQLSTATE, SQLERRM;
    END;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_convert_lead_to_customer(p_lead_id uuid, p_user_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id       UUID;
    v_caller_role     TEXT;
    v_lead            RECORD;
    v_target_user     RECORD;
    v_prev_status     TEXT;
    v_prev_lifecycle  TEXT;
    v_new_lifecycle   TEXT;
    v_lead_phone_n    TEXT;
    v_user_phone_n    TEXT;
    v_phone_match     BOOLEAN := FALSE;
    v_email_match     BOOLEAN := FALSE;
BEGIN
    -- ── 1. Authentication ──────────────────────────────────────────────────
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Unauthorized: no session');
    END IF;

    -- ── 2. Caller role check ───────────────────────────────────────────────
    SELECT role::TEXT INTO v_caller_role
    FROM public.user_profiles
    WHERE id = v_caller_id;

    IF v_caller_role NOT IN ('relationship_exec', 'relationship_manager', 'admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Forbidden: your role cannot perform lead conversions');
    END IF;

    -- ── 3. Load and lock the lead ──────────────────────────────────────────
    SELECT * INTO v_lead
    FROM public.crm_leads
    WHERE id = p_lead_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Lead not found');
    END IF;

    -- ── 4. RBAC scope check ────────────────────────────────────────────────
    IF v_caller_role = 'relationship_exec' THEN
        IF v_lead.assigned_to IS DISTINCT FROM v_caller_id THEN
            RETURN jsonb_build_object('success', FALSE, 'error', 'Forbidden: this lead is not assigned to you');
        END IF;
    ELSIF v_caller_role = 'relationship_manager' THEN
        DECLARE
            v_caller_team UUID;
        BEGIN
            SELECT team_id INTO v_caller_team FROM public.user_profiles WHERE id = v_caller_id;
            IF v_caller_team IS NULL OR v_lead.assigned_team_id IS DISTINCT FROM v_caller_team THEN
                IF v_lead.assigned_to IS DISTINCT FROM v_caller_id AND v_lead.created_by IS DISTINCT FROM v_caller_id THEN
                    RETURN jsonb_build_object('success', FALSE, 'error', 'Forbidden: lead is outside your team scope');
                END IF;
            END IF;
        END;
    END IF;

    -- ── 5. Lead must not be archived ───────────────────────────────────────
    IF v_lead.archived_at IS NOT NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Cannot convert an archived lead');
    END IF;

    -- ── 6. Lead must not already be converted to a customer ───────────────
    IF v_lead.converted_user_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'This lead has already been converted to a customer',
            'existing_user_id', v_lead.converted_user_id
        );
    END IF;

    -- ── 7. Verify the target user exists ──────────────────────────────────
    SELECT * INTO v_target_user
    FROM public.user_profiles
    WHERE id = p_user_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Target user not found in user_profiles');
    END IF;

    -- ── 8. Verify target is an application customer (role = user) ─────────
    IF v_target_user.role::TEXT <> 'user' THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Target account is not a customer. Only accounts with role=''user'' can be linked as customers.'
        );
    END IF;

    -- ── 9. Identity match: lead phone or email must match user ────────────
    v_lead_phone_n := public.normalize_in_phone(v_lead.phone);
    v_user_phone_n := public.normalize_in_phone(v_target_user.phone);

    IF v_lead_phone_n IS NOT NULL AND v_user_phone_n IS NOT NULL AND v_lead_phone_n = v_user_phone_n THEN
        v_phone_match := TRUE;
    END IF;

    IF NOT v_phone_match
       AND v_lead.email IS NOT NULL
       AND v_lead.email NOT LIKE '%@phone.intrust.internal'
       AND v_target_user.email IS NOT NULL
       AND v_target_user.email NOT LIKE '%@phone.intrust.internal'
       AND lower(v_lead.email) = lower(v_target_user.email)
    THEN
        v_email_match := TRUE;
    END IF;

    IF NOT v_phone_match AND NOT v_email_match THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Identity mismatch: the selected customer''s phone and email do not match this lead. Please verify the correct account.'
        );
    END IF;

    -- ── 10. Compute new lifecycle_status ───────────────────────────────────
    v_prev_lifecycle := v_lead.lifecycle_status;
    v_prev_status    := v_lead.status::TEXT;

    v_new_lifecycle := CASE
        WHEN v_lead.lifecycle_status = 'converted_merchant' THEN 'converted_both'
        ELSE 'converted_customer'
    END;

    -- ── 11. Update crm_leads ───────────────────────────────────────────────
    UPDATE public.crm_leads
    SET
        converted_user_id  = p_user_id,
        converted_at       = NOW(),
        converted_by       = v_caller_id,
        lifecycle_status   = v_new_lifecycle,
        -- Mark as 'won' only if not already in a terminal status
        status             = CASE
                                WHEN status::TEXT IN ('won', 'lost') THEN status
                                ELSE 'won'::lead_status
                             END,
        updated_at         = NOW()
    WHERE id = p_lead_id;

    -- ── 12. Log to crm_lead_activities ────────────────────────────────────
    INSERT INTO public.crm_lead_activities (lead_id, actor_id, action_type, metadata)
    VALUES (
        p_lead_id,
        v_caller_id,
        'converted_to_customer',
        jsonb_build_object(
            'conversion_type',    'customer',
            'customer_id',        p_user_id,
            'customer_name',      v_target_user.full_name,
            'previous_status',    v_prev_status,
            'previous_lifecycle', v_prev_lifecycle,
            'new_lifecycle',      v_new_lifecycle,
            'actor_id',           v_caller_id,
            'match_method',       CASE WHEN v_phone_match THEN 'phone' ELSE 'email' END,
            'notes',              p_notes
        )
    );

    -- ── 13. Return success ─────────────────────────────────────────────────
    RETURN jsonb_build_object(
        'success',         TRUE,
        'lead_id',         p_lead_id,
        'user_id',         p_user_id,
        'lifecycle_status', v_new_lifecycle,
        'converted_at',    NOW(),
        'message',         'Lead successfully converted to customer'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_convert_lead_to_merchant(p_lead_id uuid, p_merchant_id uuid, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
