        BEGIN
            SELECT team_id INTO v_caller_team FROM public.user_profiles WHERE id = v_caller_id;
            IF v_caller_team IS NULL OR v_lead.assigned_team_id IS DISTINCT FROM v_caller_team THEN
                IF v_lead.assigned_to IS DISTINCT FROM v_caller_id AND v_lead.created_by IS DISTINCT FROM v_caller_id THEN
                    RETURN jsonb_build_object('success', FALSE, 'error', 'Forbidden: lead is outside your team scope');
                END IF;
            END IF;
        END;
    END IF;

    -- ── 5. Lead must not be archived ───────────────────────────────────────
    IF v_lead.archived_at IS NOT NULL THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Cannot convert an archived lead');
    END IF;

    -- ── 6. Lead must not already be converted to a merchant ───────────────
    IF v_lead.converted_merchant_id IS NOT NULL THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'This lead has already been converted to a merchant',
            'existing_merchant_id', v_lead.converted_merchant_id
        );
    END IF;

    -- ── 7. Verify the target merchant exists ──────────────────────────────
    SELECT m.*, up.phone AS owner_phone, up.email AS owner_email INTO v_merchant
    FROM public.merchants m
    JOIN public.user_profiles up ON up.id = m.user_id
    WHERE m.id = p_merchant_id;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', FALSE, 'error', 'Merchant not found');
    END IF;

    -- ── 8. Identity match check ────────────────────────────────────────────
    v_lead_phone_n := public.normalize_in_phone(v_lead.phone);
    v_biz_phone_n  := public.normalize_in_phone(v_merchant.business_phone);
    v_own_phone_n  := public.normalize_in_phone(v_merchant.owner_phone);

    -- Phone match: lead phone vs business_phone or owner phone
    IF v_lead_phone_n IS NOT NULL THEN
        IF (v_biz_phone_n IS NOT NULL AND v_lead_phone_n = v_biz_phone_n)
           OR (v_own_phone_n IS NOT NULL AND v_lead_phone_n = v_own_phone_n) THEN
            v_phone_match := TRUE;
        END IF;
    END IF;

    -- Email match: lead email vs business_email or owner email
    IF NOT v_phone_match
       AND v_lead.email IS NOT NULL
       AND v_lead.email NOT LIKE '%@phone.intrust.internal'
    THEN
        IF (v_merchant.business_email IS NOT NULL AND lower(v_lead.email) = lower(v_merchant.business_email))
           OR (v_merchant.owner_email IS NOT NULL AND v_merchant.owner_email NOT LIKE '%@phone.intrust.internal' AND lower(v_lead.email) = lower(v_merchant.owner_email)) THEN
            v_email_match := TRUE;
        END IF;
    END IF;

    IF NOT v_phone_match AND NOT v_email_match THEN
        RETURN jsonb_build_object(
            'success', FALSE,
            'error', 'Identity mismatch: the selected merchant''s phone and email do not match this lead. Please verify the correct merchant.'
        );
    END IF;

    -- ── 9. Compute new lifecycle_status ────────────────────────────────────
    v_prev_lifecycle := v_lead.lifecycle_status;
    v_prev_status    := v_lead.status::TEXT;

    v_new_lifecycle := CASE
        WHEN v_lead.lifecycle_status = 'converted_customer' THEN 'converted_both'
        ELSE 'converted_merchant'
    END;

    -- ── 10. Update crm_leads ───────────────────────────────────────────────
    UPDATE public.crm_leads
    SET
        converted_merchant_id = p_merchant_id,
        converted_at          = NOW(),
        converted_by          = v_caller_id,
        lifecycle_status      = v_new_lifecycle,
        -- Mark as 'won' only if not already in a terminal status
        status                = CASE
                                    WHEN status::TEXT IN ('won', 'lost') THEN status
                                    ELSE 'won'::lead_status
                                 END,
        updated_at            = NOW()
    WHERE id = p_lead_id;

    -- ── 11. Log to crm_lead_activities ────────────────────────────────────
    INSERT INTO public.crm_lead_activities (lead_id, actor_id, action_type, metadata)
    VALUES (
        p_lead_id,
        v_caller_id,
        'converted_to_merchant',
        jsonb_build_object(
            'conversion_type',    'merchant',
            'merchant_id',        p_merchant_id,
            'merchant_name',      v_merchant.business_name,
            'previous_status',    v_prev_status,
            'previous_lifecycle', v_prev_lifecycle,
            'new_lifecycle',      v_new_lifecycle,
            'actor_id',           v_caller_id,
            'match_method',       CASE WHEN v_phone_match THEN 'phone' ELSE 'email' END,
            'notes',              p_notes
        )
    );

    -- ── 12. Return success ─────────────────────────────────────────────────
    RETURN jsonb_build_object(
        'success',          TRUE,
        'lead_id',          p_lead_id,
        'merchant_id',      p_merchant_id,
        'lifecycle_status', v_new_lifecycle,
        'converted_at',     NOW(),
        'message',          'Lead successfully converted to merchant'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.get_my_coupon_code(p_coupon_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID;
    v_encrypted_code TEXT;
BEGIN
    v_user_id := auth.uid();
    
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;
    
    -- Get encrypted code only if user owns it
    SELECT encrypted_code INTO v_encrypted_code
    FROM public.coupons
    WHERE id = p_coupon_id
        AND purchased_by = v_user_id
        AND status = 'sold';
    
    IF v_encrypted_code IS NULL THEN
        RAISE EXCEPTION 'Coupon not found or not owned by you';
    END IF;
    
    -- Return encrypted code (application layer will decrypt using service role)
    RETURN v_encrypted_code;
END;
$function$

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  name_val text;
  avatar_val text;
  provider_val text;
  new_code text;
  code_exists boolean;
BEGIN
  -- 1. Extract metadata
  name_val := COALESCE(NEW.raw_user_meta_data->>'full_name', NEW.raw_user_meta_data->>'name', 'New User');
  avatar_val := NEW.raw_user_meta_data->>'avatar_url';

  -- 2. Determine provider
  provider_val := COALESCE(NEW.raw_app_meta_data->>'provider', 'phone_otp');
  IF provider_val = 'phone' THEN 
    provider_val := 'phone_otp'; 
  END IF;

  -- 3. Generate unique referral code
  LOOP
    new_code := upper(substring(md5(random()::text || clock_timestamp()::text) from 1 for 6));
    SELECT EXISTS (SELECT 1 FROM public.user_profiles WHERE referral_code = new_code) INTO code_exists;
    EXIT WHEN NOT code_exists;
  END LOOP;

  -- 4. Inner block for inserts
  BEGIN
    INSERT INTO public.user_profiles (
      id, phone, full_name, avatar_url, role, referral_code, email, auth_provider, email_verified, email_verified_at
    ) VALUES (
      NEW.id,
      public.normalize_in_phone(NEW.phone),
      name_val,
      avatar_val,
      'user',
      new_code,
      NEW.email,
      provider_val,
      CASE WHEN provider_val = 'google' THEN true ELSE false END,
      CASE WHEN provider_val = 'google' THEN now() ELSE NULL END
    )
    ON CONFLICT (id) DO UPDATE SET
      phone = COALESCE(NULLIF(public.user_profiles.phone, ''), public.normalize_in_phone(EXCLUDED.phone)),
      email = COALESCE(NULLIF(public.user_profiles.email, ''), EXCLUDED.email),
      auth_provider = CASE WHEN public.user_profiles.auth_provider = 'multiple' THEN 'multiple' ELSE EXCLUDED.auth_provider END,
      email_verified = CASE WHEN EXCLUDED.auth_provider = 'google' THEN true ELSE public.user_profiles.email_verified END,
      email_verified_at = CASE WHEN EXCLUDED.auth_provider = 'google' AND public.user_profiles.email_verified_at IS NULL THEN now() ELSE public.user_profiles.email_verified_at END;

    INSERT INTO public.reward_points_balance
      (user_id, current_balance, total_earned, total_redeemed, tier, tree_size, direct_referrals, active_downline)
    VALUES (NEW.id, 0, 0, 0, 'bronze', 0, 0, 0)
    ON CONFLICT (user_id) DO NOTHING;

  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING '[handle_new_user] Failed to upsert user_profiles for user %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_otp_rate_limit(p_phone text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  _norm text;
  _clean text;
BEGIN
  _norm := public.normalize_in_phone(p_phone);
  _clean := right(regexp_replace(p_phone, '\D', '', 'g'), 10);

  -- Delete OTP codes matching either format
  DELETE FROM public.otp_codes 
  WHERE phone = _norm OR phone = _clean;

  -- Delete rate limit store records matching either format
  DELETE FROM public.ip_rate_limit_store 
  WHERE key = 'otp:phone:' || _norm OR key = 'otp:phone:' || _clean;
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_purchase_coupon(p_coupon_id uuid, p_quantity integer DEFAULT 1, p_merchant_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id UUID;
    v_merchant_id UUID;
    v_merchant_status TEXT;
    v_merchant_balance BIGINT;
    v_coupon RECORD;
    v_purchase_price_paise BIGINT;
    v_commission_paise BIGINT;
    v_total_cost_paise BIGINT;
    v_new_balance BIGINT;
    v_transaction_id UUID;
    v_user_role TEXT;
BEGIN
    -- Get current user
    v_user_id := auth.uid();

    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    -- Check user role
    SELECT role INTO v_user_role FROM public.user_profiles WHERE id = v_user_id;

    -- Determine merchant_id
    IF v_user_role = 'admin' AND p_merchant_id IS NOT NULL THEN
        v_merchant_id := p_merchant_id;
    ELSE
        -- Get merchant profile for the user
        SELECT id, status, wallet_balance_paise 
        INTO v_merchant_id, v_merchant_status, v_merchant_balance
        FROM public.merchants
        WHERE user_id = v_user_id;
    END IF;

    -- If we selected by ID (admin case), we need to fetch status and balance
    IF v_user_role = 'admin' AND p_merchant_id IS NOT NULL THEN
        SELECT id, status, wallet_balance_paise
        INTO v_merchant_id, v_merchant_status, v_merchant_balance
        FROM public.merchants
        WHERE id = v_merchant_id;
    END IF;

    IF v_merchant_id IS NULL THEN
        RAISE EXCEPTION 'Merchant profile not found';
    END IF;

    IF v_merchant_status != 'approved' THEN
        RAISE EXCEPTION 'Merchant account not approved. Status: %', v_merchant_status;
    END IF;

    -- Get coupon details
    SELECT id, brand, title, selling_price_paise, status, valid_until, is_merchant_owned
    INTO v_coupon
    FROM public.coupons
    WHERE id = p_coupon_id
    FOR UPDATE;

    IF v_coupon.id IS NULL THEN
        RAISE EXCEPTION 'Coupon not found';
    END IF;

    IF v_coupon.status != 'available' THEN
        RAISE EXCEPTION 'Coupon not available';
    END IF;

    IF v_coupon.valid_until <= NOW() THEN
        RAISE EXCEPTION 'Coupon expired';
    END IF;

    IF v_coupon.is_merchant_owned = TRUE THEN
        RAISE EXCEPTION 'Cannot purchase merchant-owned coupons';
    END IF;

    -- Calculate costs (merchant pays same price as customers + 3% commission)
    v_purchase_price_paise := v_coupon.selling_price_paise;
    v_commission_paise := FLOOR(v_purchase_price_paise * 0.03);
    v_total_cost_paise := v_purchase_price_paise + v_commission_paise;

    -- Check merchant balance
    IF v_merchant_balance < v_total_cost_paise THEN
        RAISE EXCEPTION 'Insufficient balance. Required: %, Available: %', 
            v_total_cost_paise, v_merchant_balance;
    END IF;

    -- Deduct from merchant balance
    v_new_balance := v_merchant_balance - v_total_cost_paise;

    UPDATE public.merchants
    SET 
        wallet_balance_paise = v_new_balance,
        total_commission_paid_paise = total_commission_paid_paise + v_commission_paise,
        updated_at = NOW()
    WHERE id = v_merchant_id;

    -- Update coupon to merchant-owned
    UPDATE public.coupons
    SET 
        merchant_id = v_merchant_id,
        is_merchant_owned = TRUE,
        merchant_purchase_price_paise = v_purchase_price_paise,
        merchant_selling_price_paise = selling_price_paise,
        merchant_commission_paise = v_commission_paise,
        listed_on_marketplace = FALSE,
        updated_at = NOW()
    WHERE id = p_coupon_id;

    -- Record transaction
    INSERT INTO public.merchant_transactions (
        merchant_id,
        transaction_type,
        amount_paise,
        commission_paise,
        balance_after_paise,
        coupon_id,
        description,
        metadata
    ) VALUES (
        v_merchant_id,
        'purchase',
        -v_total_cost_paise,
        v_commission_paise,
        v_new_balance,
        p_coupon_id,
        FORMAT('Purchased coupon at wholesale price: %s - %s', v_coupon.brand, v_coupon.title),
        jsonb_build_object(
            'purchase_price_paise', v_purchase_price_paise,
            'commission_paise', v_commission_paise,
            'total_cost_paise', v_total_cost_paise
        )
    )
    RETURNING id INTO v_transaction_id;

    -- Return success
    RETURN jsonb_build_object(
        'success', true,
        'transaction_id', v_transaction_id,
        'coupon_id', p_coupon_id,
        'purchase_price_paise', v_purchase_price_paise,
        'commission_paise', v_commission_paise,
        'total_cost_paise', v_total_cost_paise,
        'new_balance_paise', v_new_balance
    );

EXCEPTION
    WHEN OTHERS THEN
        RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_update_listing_price(p_coupon_id uuid, p_new_selling_price_paise bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_merchant_id uuid;
BEGIN
  SELECT id INTO v_merchant_id
  FROM public.merchants
  WHERE user_id = auth.uid() AND status = 'approved'
  LIMIT 1;

  IF v_merchant_id IS NULL THEN
    RAISE EXCEPTION 'Merchant not found or not approved';
  END IF;

  IF p_new_selling_price_paise <= 0 THEN
    RAISE EXCEPTION 'Selling price must be greater than 0';
  END IF;

  UPDATE public.coupons
  SET 
    merchant_selling_price_paise = p_new_selling_price_paise,
    selling_price_paise = p_new_selling_price_paise,
    updated_at = NOW()
  WHERE id = p_coupon_id AND merchant_id = v_merchant_id;

  RETURN json_build_object('success', true, 'message', 'Price updated');
END;
$function$

CREATE OR REPLACE FUNCTION public.normalize_in_phone(p_raw text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    stripped text;
BEGIN
    IF p_raw IS NULL THEN
        RETURN NULL;
    END IF;

    stripped := regexp_replace(p_raw, '\D', '', 'g');

    IF length(stripped) < 10 THEN
        RETURN NULL;
    END IF;

    RETURN '+91' || right(stripped, 10);
END;
$function$

CREATE OR REPLACE FUNCTION public.purchase_platform_products_bulk(p_items jsonb[], p_merchant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_item              JSONB;
    v_product_id        UUID;
    v_qty               INTEGER;
    v_item_cost_paise   BIGINT;
    v_total_cost        BIGINT := 0;
    v_merchant_balance  BIGINT;
    v_new_balance       BIGINT;
    v_product           RECORD;
    v_gst_amount_paise  BIGINT;
    v_batch_id          UUID := gen_random_uuid();
    v_merchant_user_id  UUID;
    v_item_count        INTEGER := 0;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.merchants
        WHERE id = p_merchant_id AND user_id = auth.uid()
    ) THEN
        RETURN jsonb_build_object('success', false, 'message', 'Unauthorized: Merchant identity mismatch');
    END IF;

    FOREACH v_item IN ARRAY p_items LOOP
        v_product_id := (v_item->>'product_id')::UUID;
        v_qty        := (v_item->>'quantity')::INTEGER;

        IF v_qty <= 0 THEN
            RETURN jsonb_build_object('success', false, 'message', 'Quantity must be greater than zero');
        END IF;

        SELECT wholesale_price_paise, admin_stock, title, gst_percentage
        INTO v_product
        FROM public.shopping_products WHERE id = v_product_id;

        IF v_product.admin_stock < v_qty THEN
            RETURN jsonb_build_object('success', false, 'message', 'Insufficient stock for ' || v_product.title);
        END IF;

        v_item_cost_paise := v_product.wholesale_price_paise * v_qty
                           + ROUND(v_product.wholesale_price_paise * v_qty * COALESCE(v_product.gst_percentage, 0) / 100.0);
        v_total_cost := v_total_cost + v_item_cost_paise;
        v_item_count := v_item_count + v_qty;
    END LOOP;

    SELECT wallet_balance_paise INTO v_merchant_balance
    FROM public.merchants WHERE id = p_merchant_id FOR UPDATE;

    IF v_merchant_balance < v_total_cost THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient merchant balance');
    END IF;

    v_new_balance := v_merchant_balance;

    FOREACH v_item IN ARRAY p_items LOOP
        v_product_id := (v_item->>'product_id')::UUID;
        v_qty        := (v_item->>'quantity')::INTEGER;

        SELECT wholesale_price_paise, gst_percentage
        INTO v_product
        FROM public.shopping_products WHERE id = v_product_id FOR UPDATE;

        v_item_cost_paise  := v_product.wholesale_price_paise * v_qty
                            + ROUND(v_product.wholesale_price_paise * v_qty * COALESCE(v_product.gst_percentage, 0) / 100.0);
        v_gst_amount_paise := ROUND(v_product.wholesale_price_paise * v_qty * COALESCE(v_product.gst_percentage, 0) / 100.0);

        UPDATE public.shopping_products
        SET admin_stock = admin_stock - v_qty
        WHERE id = v_product_id;

        INSERT INTO public.merchant_inventory (
            merchant_id, product_id, stock_quantity, retail_price_paise,
            is_platform_product, is_active, custom_title, custom_description
        )
        SELECT
            p_merchant_id, v_product_id, v_qty, suggested_retail_price_paise,
            true, false, title, description
        FROM public.shopping_products WHERE id = v_product_id
        ON CONFLICT (merchant_id, product_id) DO UPDATE
        SET stock_quantity      = public.merchant_inventory.stock_quantity + v_qty,
            retail_price_paise  = EXCLUDED.retail_price_paise,
            is_platform_product = true,
            is_active           = EXCLUDED.is_active,
            custom_title        = EXCLUDED.custom_title,
            custom_description  = EXCLUDED.custom_description,
            updated_at          = now();

        INSERT INTO public.shopping_orders (
            buyer_id, buyer_type, seller_id, seller_type,
            product_id, quantity, unit_price_paise, total_price_paise,
            order_type, purchase_batch_id
        )
        VALUES (
            p_merchant_id, 'merchant', NULL, 'admin',
            v_product_id, v_qty, v_product.wholesale_price_paise, v_item_cost_paise,
            'wholesale', v_batch_id
        );

        v_new_balance := v_new_balance - v_item_cost_paise;

        INSERT INTO public.merchant_transactions (
            merchant_id, transaction_type, amount_paise, balance_after_paise,
            description, metadata, purchase_batch_id
        )
        VALUES (
            p_merchant_id, 'purchase', -v_item_cost_paise, v_new_balance,
            'Wholesale bulk purchase (GST-inclusive)',
            jsonb_build_object(
                'product_id',             v_product_id,
                'quantity',               v_qty,
                'wholesale_amount_paise', v_product.wholesale_price_paise * v_qty,
                'gst_amount_paise',       v_gst_amount_paise,
                'gst_percentage',         COALESCE(v_product.gst_percentage, 0),
                'batch_id',               v_batch_id
            ),
            v_batch_id
        );
    END LOOP;

    UPDATE public.merchants SET wallet_balance_paise = v_new_balance WHERE id = p_merchant_id;

    SELECT user_id INTO v_merchant_user_id FROM public.merchants WHERE id = p_merchant_id;

    INSERT INTO public.notifications (
        user_id, title, body, reference_id, reference_type
    )
    VALUES (
        v_merchant_user_id,
        'Wholesale stock purchased',
        'Total across ' || v_item_count::TEXT || ' items — tap to download invoice',
        v_batch_id,
        'wholesale_purchase'
    );

    RETURN jsonb_build_object(
        'success',      true,
        'batch_id',     v_batch_id,
        'total_paise',  v_total_cost,
        'message',      'Bulk purchase successful'
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_leave_policy_year(p_policy_year_id uuid, p_actor_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_actor_id uuid;
    v_actor_role text;
    v_year_rec record;
    v_policy_count int;
    v_emp record;
    v_pol record;
    v_created_count int := 0;
    v_existing_count int := 0;
BEGIN
    IF auth.uid() IS NOT NULL THEN
        v_actor_id := auth.uid();
    ELSE
        v_actor_id := p_actor_id;
    END IF;

    IF v_actor_id IS NULL THEN
        RAISE EXCEPTION 'Unauthorized call.';
    END IF;

    SELECT role::text INTO v_actor_role FROM public.user_profiles WHERE id = v_actor_id;
    IF v_actor_role NOT IN ('admin', 'super_admin') THEN
        RAISE EXCEPTION 'Forbidden: Only Admins can publish policy years.';
    END IF;

    SELECT * INTO v_year_rec FROM public.leave_policy_years WHERE id = p_policy_year_id FOR UPDATE;
    IF v_year_rec.id IS NULL THEN
        RAISE EXCEPTION 'Policy year not found.';
    END IF;

    SELECT COUNT(*) INTO v_policy_count FROM public.leave_policies WHERE policy_year_id = p_policy_year_id AND is_active = true;
    IF v_policy_count = 0 THEN
        RAISE EXCEPTION 'Cannot publish policy year: At least one active leave policy row is required.';
    END IF;

    UPDATE public.leave_policy_years
    SET 
        status = 'published',
        published_by = v_actor_id,
        published_at = now(),
        updated_at = now()
    WHERE id = p_policy_year_id;

    FOR v_emp IN 
        SELECT id FROM public.user_profiles 
        WHERE role IN (
            'employee', 'hr_manager', 'relationship_exec', 'relationship_manager',
            'freelancer', 'video_editor', 'social_media_manager',
            'seo_specialist', 'advertiser', 'support_agent'
        )
    LOOP
        FOR v_pol IN 
            SELECT * FROM public.leave_policies WHERE policy_year_id = p_policy_year_id AND is_active = true
        LOOP
            IF EXISTS (
                SELECT 1 FROM public.employee_leave_balances 
                WHERE employee_id = v_emp.id AND policy_year = v_year_rec.policy_year AND leave_type = v_pol.leave_type_key
            ) THEN
                v_existing_count := v_existing_count + 1;
                UPDATE public.employee_leave_balances
                SET policy_id = v_pol.id,
                    entitled_days = v_pol.annual_entitlement,
                    updated_at = now()
                WHERE employee_id = v_emp.id AND policy_year = v_year_rec.policy_year AND leave_type = v_pol.leave_type_key;
            ELSE
                INSERT INTO public.employee_leave_balances (
                    employee_id, policy_year, leave_type, policy_id, entitled_days
                ) VALUES (
                    v_emp.id, v_year_rec.policy_year, v_pol.leave_type_key, v_pol.id, v_pol.annual_entitlement
                );
                v_created_count := v_created_count + 1;
            END IF;
        END LOOP;
    END LOOP;

    INSERT INTO public.audit_logs_hrm (actor_id, action, table_name, record_id, new_data, module, severity)
    VALUES (
        v_actor_id, 'Policy year published', 'leave_policy_years', p_policy_year_id,
        jsonb_build_object('policy_year', v_year_rec.policy_year, 'created_balances', v_created_count, 'existing_balances', v_existing_count),
        'Leaves', 'high'
    );

    RETURN jsonb_build_object(
        'success', true,
        'policy_year', v_year_rec.policy_year,
        'created_balances', v_created_count,
        'existing_balances', v_existing_count
    );
END;
$function$

