CREATE OR REPLACE FUNCTION public.update_order_status_v2(p_order_id uuid, p_delivery_status text, p_tracking_number text DEFAULT NULL::text, p_estimated_delivery_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_status_notes text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_user_role text;
    v_is_authorized boolean := false;
BEGIN
    -- Get user role
    SELECT role INTO v_user_role FROM public.user_profiles WHERE id = auth.uid();

    -- Get order details
    SELECT * INTO v_order FROM public.shopping_order_groups WHERE id = p_order_id;
    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'Order not found');
    END IF;

    -- Check Authorization: Admin can update anything. Merchant can update their own orders.
    IF v_user_role = 'admin' THEN
        v_is_authorized := true;
    ELSIF v_user_role = 'merchant' AND v_order.merchant_id IS NOT NULL THEN
        -- Check if current user owns the merchant profile
        IF EXISTS (SELECT 1 FROM public.merchants WHERE id = v_order.merchant_id AND user_id = auth.uid()) THEN
            v_is_authorized := true;
        END IF;
    END IF;

    IF NOT v_is_authorized THEN
        RETURN json_build_object('success', false, 'message', 'Unauthorized to update this order');
    END IF;

    -- Validate Status
    IF p_delivery_status NOT IN ('pending', 'packed', 'shipped', 'delivered', 'cancelled') THEN
        RETURN json_build_object('success', false, 'message', 'Invalid status');
    END IF;

    -- Update Order
    UPDATE public.shopping_order_groups
    SET delivery_status = p_delivery_status,
        tracking_number = COALESCE(p_tracking_number, tracking_number),
        estimated_delivery_at = COALESCE(p_estimated_delivery_at, estimated_delivery_at),
        status_notes = COALESCE(p_status_notes, status_notes),
        status_updated_by = auth.uid(),
        -- Automatic timestamps based on status
        packed_at = CASE WHEN p_delivery_status = 'packed' AND packed_at IS NULL THEN now() ELSE packed_at END,
        shipped_at = CASE WHEN p_delivery_status = 'shipped' AND shipped_at IS NULL THEN now() ELSE shipped_at END,
        delivered_at = CASE WHEN p_delivery_status = 'delivered' AND delivered_at IS NULL THEN now() ELSE delivered_at END
    WHERE id = p_order_id;

    RETURN json_build_object('success', true, 'message', 'Order status updated successfully');
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_list_to_marketplace(p_coupon_id uuid, p_selling_price_paise bigint)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_merchant_id uuid;
  v_merchant_name text;
  v_coupon record;
BEGIN
  -- Get merchant
  SELECT id, business_name INTO v_merchant_id, v_merchant_name
  FROM public.merchants
  WHERE user_id = auth.uid() AND status = 'approved'
  LIMIT 1;

  IF v_merchant_id IS NULL THEN
    RAISE EXCEPTION 'Merchant not found or not approved';
  END IF;

  -- Get coupon
  SELECT * INTO v_coupon
  FROM public.coupons
  WHERE id = p_coupon_id
    AND merchant_id = v_merchant_id
    AND status = 'available';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Coupon not found or not available';
  END IF;

  -- Validate price
  IF p_selling_price_paise <= 0 THEN
    RAISE EXCEPTION 'Selling price must be greater than 0';
  END IF;

  -- Update coupon
  UPDATE public.coupons
  SET 
    listed_on_marketplace = true,
    merchant_selling_price_paise = p_selling_price_paise,
    merchant_name = v_merchant_name,
    selling_price_paise = p_selling_price_paise,
    updated_at = NOW()
  WHERE id = p_coupon_id;

  RETURN json_build_object('success', true, 'message', 'Listed successfully');
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_escalate_order(p_order_id uuid, p_merchant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_order            RECORD;
    v_new_platform_cut    bigint;
    v_new_merchant_profit bigint;
    v_merchant_user_id    uuid;
    v_total_product_value bigint;
    v_total_cost_price    bigint;
    v_total_profit        bigint;
BEGIN
    -- Verify ownership and eligibility
    SELECT sog.*, m.user_id INTO v_order
    FROM public.shopping_order_groups sog
    JOIN public.merchants m ON sog.merchant_id = m.id
    WHERE sog.id = p_order_id
      AND sog.merchant_id = p_merchant_id
      AND sog.delivery_status = 'pending'
      AND sog.settlement_status = 'pending'
      AND sog.is_platform_order = false;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Order not eligible for escalation');
    END IF;

    v_merchant_user_id := v_order.user_id;

    -- Commission formula: 70% of profit margin (Escalation penalty)
    v_total_product_value := v_order.total_amount_paise - COALESCE(v_order.delivery_fee_paise, 0);

    SELECT COALESCE(SUM(p.wholesale_price_paise * i.quantity), 0)
    INTO v_total_cost_price
    FROM public.shopping_order_items i
    JOIN public.shopping_products    p ON i.product_id = p.id
    WHERE i.group_id = p_order_id;

    v_total_profit        := GREATEST(0, v_total_product_value - v_total_cost_price);
    v_new_platform_cut    := ROUND(v_total_profit * 70 / 100);
    v_new_merchant_profit := v_total_product_value - v_new_platform_cut;

    -- Update order group
    UPDATE public.shopping_order_groups
    SET commission_rate    = 0.30,
        platform_cut_paise = v_new_platform_cut,
        merchant_profit_paise = v_new_merchant_profit,
        assigned_to        = NULL,
        admin_takeover_at  = NOW(),
        settlement_status  = 'admin_takeover'
    WHERE id = v_order.id;

    -- Update per-item commissions in ledger
    UPDATE public.shopping_order_items soi
    SET commission_amount_paise =
            GREATEST(0, (soi.unit_price_paise - COALESCE(p.wholesale_price_paise, 0)))
            * soi.quantity * 70 / 100,
        profit_paise =
            (soi.unit_price_paise * soi.quantity)
            - GREATEST(0, (soi.unit_price_paise - COALESCE(p.wholesale_price_paise, 0))) * soi.quantity * 70 / 100
            - (COALESCE(p.wholesale_price_paise, 0) * soi.quantity)
    FROM public.shopping_products p
    WHERE soi.product_id = p.id
      AND soi.group_id   = v_order.id;

    -- Credit merchant wallet immediately
    UPDATE public.merchants
    SET wallet_balance_paise        = COALESCE(wallet_balance_paise, 0)        + v_new_merchant_profit,
        total_commission_paid_paise = COALESCE(total_commission_paid_paise, 0) + v_new_platform_cut
    WHERE id = v_order.merchant_id;

    -- Merchant transaction log
    INSERT INTO public.merchant_transactions (
        merchant_id, transaction_type, amount_paise, commission_paise, balance_after_paise, description
    ) VALUES (
        v_order.merchant_id, 'sale', v_new_merchant_profit, v_new_platform_cut,
        (SELECT wallet_balance_paise FROM public.merchants WHERE id = v_order.merchant_id),
        'Order escalated to admin by merchant. Commission adjusted to 70% of profit.'
    );

    -- Notification
    INSERT INTO public.notifications (user_id, title, body, type, reference_id, reference_type)
    VALUES (
        v_merchant_user_id,
        'Order Escalated ✅',
        'Order #' || substring(v_order.id::text from 1 for 8) || ' escalated to admin. Reduced profit has been credited to your wallet.',
        'info',
        v_order.id,
        'shopping_order'
    );

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_cancel_pending_payout(p_user_id uuid, p_request_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_payout record;
BEGIN
    SELECT pr.*, m.id AS mid
    INTO   v_payout
    FROM   payout_requests pr
    JOIN   merchants m ON m.id = pr.merchant_id
    WHERE  pr.id     = p_request_id
      AND  m.user_id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_found');
    END IF;

    IF v_payout.status <> 'pending' THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_cancellable');
    END IF;

    IF v_payout.payout_source = 'wallet' THEN
        UPDATE merchants
        SET    wallet_balance_paise = wallet_balance_paise + v_payout.amount_paise
        WHERE  id = v_payout.merchant_id;
    ELSIF v_payout.payout_source = 'growth_fund' THEN
        UPDATE merchant_lockin_balances SET status = 'matured' WHERE id = v_payout.reference_id;
    END IF;

    UPDATE payout_requests
    SET    status = 'rejected', admin_note = 'Cancelled by merchant'
    WHERE  id = p_request_id;

    INSERT INTO payout_request_events (payout_id, actor_id, action, from_status, to_status, payload)
    VALUES (p_request_id, p_user_id, 'cancelled', 'pending', 'rejected',
            jsonb_build_object('reason', 'Cancelled by merchant'));

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_suspend_user(p_user_id uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_admin_id UUID;
    v_admin_role user_role;
BEGIN
    v_admin_id := auth.uid();
    
    -- Check admin role
    SELECT role INTO v_admin_role
    FROM public.user_profiles
    WHERE id = v_admin_id;
    
    IF v_admin_role != 'admin' THEN
        RAISE EXCEPTION 'Only admins can suspend users';
    END IF;
    
    -- Cannot suspend another admin
    IF EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = p_user_id AND role = 'admin'
    ) THEN
        RAISE EXCEPTION 'Cannot suspend admin users';
    END IF;
    
    -- Suspend user
    UPDATE public.user_profiles
    SET 
        is_suspended = TRUE,
        suspension_reason = p_reason,
        updated_at = NOW()
    WHERE id = p_user_id;
    
    -- Log the action
    INSERT INTO public.audit_logs (
        actor_id, actor_role, action, entity_type, entity_id,
        description, metadata
    ) VALUES (
        v_admin_id, 'admin', 'user_suspended', 'user', p_user_id,
        FORMAT('User suspended: %s', p_reason),
        jsonb_build_object('reason', p_reason)
    );
    
    RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.merchants_block_sensitive_column_updates()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    -- ALLOW BYPASS for:
    --   1. Explicit internal system operations that set app.internal_bypass='true'
    --      (e.g. perform_wallet_adjustment RPC, settlement functions)
    --   2. Service-role connections (Supabase Admin client — createAdminClient())
    --   3. Direct postgres superuser connections (migration runner, perform_wallet_adjustment owner)
    --
    -- ⚠ NOTE (2026-06-06): The service_role and postgres bypasses are broad. A service-role
    --   write carrying a stale wallet_balance_paise will silently succeed and produce no ledger
    --   row. See incident report docs/incident/20260606_jjstore_wallet_lost_update.md.
    IF current_setting('app.internal_bypass', true) = 'true'
       OR current_setting('role', true) = 'service_role'
       OR current_user = 'postgres'
    THEN
        RETURN NEW;
    END IF;

    -- Block financial columns
    IF NEW.wallet_balance_paise IS DISTINCT FROM OLD.wallet_balance_paise THEN
        RAISE EXCEPTION 'Column wallet_balance_paise is protected and cannot be updated directly.';
    END IF;
    IF NEW.total_commission_paid_paise IS DISTINCT FROM OLD.total_commission_paid_paise THEN
        RAISE EXCEPTION 'Column total_commission_paid_paise is protected and cannot be updated directly.';
    END IF;

    -- Block status and subscription columns
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        RAISE EXCEPTION 'Column status is protected and can only be updated by admins.';
    END IF;
    IF NEW.subscription_status IS DISTINCT FROM OLD.subscription_status THEN
        RAISE EXCEPTION 'Column subscription_status is protected and cannot be updated directly.';
    END IF;
    IF NEW.subscription_expires_at IS DISTINCT FROM OLD.subscription_expires_at THEN
        RAISE EXCEPTION 'Column subscription_expires_at is protected and cannot be updated directly.';
    END IF;

    -- Block auto-mode columns
    IF NEW.auto_mode_status IS DISTINCT FROM OLD.auto_mode_status THEN
        RAISE EXCEPTION 'Column auto_mode_status is protected and controlled via RPC.';
    END IF;
    IF NEW.auto_mode_months_paid IS DISTINCT FROM OLD.auto_mode_months_paid THEN
        RAISE EXCEPTION 'Column auto_mode_months_paid is protected and cannot be updated directly.';
    END IF;
    IF NEW.auto_mode_valid_until IS DISTINCT FROM OLD.auto_mode_valid_until THEN
        RAISE EXCEPTION 'Column auto_mode_valid_until is protected and cannot be updated directly.';
    END IF;
    IF NEW.auto_mode IS DISTINCT FROM OLD.auto_mode THEN
        RAISE EXCEPTION 'Column auto_mode is protected and controlled via RPC.';
    END IF;

    -- Block failure tracking and admin columns
    IF NEW.fulfillment_failure_count IS DISTINCT FROM OLD.fulfillment_failure_count THEN
        RAISE EXCEPTION 'Column fulfillment_failure_count is protected and set by admin takeover only.';
    END IF;
    IF NEW.rejection_reason IS DISTINCT FROM OLD.rejection_reason THEN
        RAISE EXCEPTION 'Column rejection_reason is admin-only.';
    END IF;
    IF NEW.suspension_reason IS DISTINCT FROM OLD.suspension_reason THEN
        RAISE EXCEPTION 'Column suspension_reason is admin-only.';
    END IF;

    -- Block audit timestamps
    IF NEW.applied_at IS DISTINCT FROM OLD.applied_at THEN
        RAISE EXCEPTION 'Column applied_at is immutable.';
    END IF;
    IF NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN
        RAISE EXCEPTION 'Column approved_at is immutable.';
    END IF;
    IF NEW.rejected_at IS DISTINCT FROM OLD.rejected_at THEN
        RAISE EXCEPTION 'Column rejected_at is immutable.';
    END IF;

    -- Block KYC columns
    IF NEW.pan_number IS DISTINCT FROM OLD.pan_number THEN
        RAISE EXCEPTION 'Column pan_number is protected and set during onboarding only.';
    END IF;
    IF NEW.pan_verified IS DISTINCT FROM OLD.pan_verified THEN
        RAISE EXCEPTION 'Column pan_verified is protected.';
    END IF;
    IF NEW.pan_data IS DISTINCT FROM OLD.pan_data THEN
        RAISE EXCEPTION 'Column pan_data is protected.';
    END IF;
    IF NEW.gstin_verified IS DISTINCT FROM OLD.gstin_verified THEN
        RAISE EXCEPTION 'Column gstin_verified is protected.';
    END IF;
    IF NEW.gstin_data IS DISTINCT FROM OLD.gstin_data THEN
        RAISE EXCEPTION 'Column gstin_data is protected.';
    END IF;
    IF NEW.bank_verified IS DISTINCT FROM OLD.bank_verified THEN
        RAISE EXCEPTION 'Column bank_verified is protected.';
    END IF;
    IF NEW.bank_data IS DISTINCT FROM OLD.bank_data THEN
        RAISE EXCEPTION 'Column bank_data is protected.';
    END IF;

    -- Block bank details
    IF NEW.bank_account_number IS DISTINCT FROM OLD.bank_account_number THEN
        RAISE EXCEPTION 'Column bank_account_number is protected and requires re-verification.';
    END IF;
    IF NEW.bank_ifsc_code IS DISTINCT FROM OLD.bank_ifsc_code THEN
        RAISE EXCEPTION 'Column bank_ifsc_code is protected and requires re-verification.';
    END IF;
    IF NEW.bank_name IS DISTINCT FROM OLD.bank_name THEN
        RAISE EXCEPTION 'Column bank_name is protected.';
    END IF;
    IF NEW.bank_account_name IS DISTINCT FROM OLD.bank_account_name THEN
        RAISE EXCEPTION 'Column bank_account_name is protected.';
    END IF;

    -- Block slug
    IF NEW.slug IS DISTINCT FROM OLD.slug THEN
        RAISE EXCEPTION 'Column slug is immutable after approval.';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.sync_user_profile_team_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF (TG_OP = 'INSERT') THEN
        UPDATE public.user_profiles
        SET team_id = NEW.team_id
        WHERE id = NEW.user_id;
        RETURN NEW;
    ELSIF (TG_OP = 'DELETE') THEN
        UPDATE public.user_profiles
        SET team_id = NULL
        WHERE id = OLD.user_id AND team_id = OLD.team_id;
        RETURN OLD;
    ELSIF (TG_OP = 'UPDATE') THEN
        IF OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.team_id IS DISTINCT FROM NEW.team_id THEN
            UPDATE public.user_profiles
            SET team_id = NULL
            WHERE id = OLD.user_id AND team_id = OLD.team_id;

            UPDATE public.user_profiles
            SET team_id = NEW.team_id
            WHERE id = NEW.user_id;
        END IF;
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_team_hierarchy_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_parent RECORD;
    v_curr_id UUID;
    v_depth INT := 0;
BEGIN
    -- Normalized name
    NEW.name := TRIM(NEW.name);
    IF LENGTH(NEW.name) = 0 THEN
        RAISE EXCEPTION 'TEAM_NAME_EMPTY: Team name cannot be blank';
    END IF;

    -- Prevent self parenting
    IF NEW.parent_team_id IS NOT NULL AND NEW.parent_team_id = NEW.id THEN
        RAISE EXCEPTION 'HIERARCHY_CYCLE: Team cannot be its own parent';
    END IF;

    -- Validate Region Level & Geography rules
    IF NEW.region_level NOT IN ('state', 'city', 'area') THEN
        RAISE EXCEPTION 'INVALID_LEVEL: Invalid region level %', NEW.region_level;
    END IF;

    IF NEW.region_level = 'state' THEN
        NEW.city := NULL;
        NEW.area := NULL;
    ELSIF NEW.region_level = 'city' THEN
        IF NEW.city IS NULL OR TRIM(NEW.city) = '' THEN
            RAISE EXCEPTION 'INVALID_LOCATION: City is required for city-level teams';
        END IF;
        NEW.area := NULL;

        IF NEW.parent_team_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_PARENT: City team requires a state-level parent team';
        END IF;

        SELECT id, region_level, state INTO v_parent FROM public.teams WHERE id = NEW.parent_team_id AND is_active = true;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'PARENT_NOT_FOUND: Parent state team does not exist or is inactive';
        END IF;
        IF v_parent.region_level != 'state' THEN
            RAISE EXCEPTION 'INVALID_PARENT_LEVEL: Parent of a city team must be a state-level team';
        END IF;
        IF LOWER(TRIM(v_parent.state)) != LOWER(TRIM(NEW.state)) THEN
            RAISE EXCEPTION 'LOCATION_MISMATCH: City team state must match parent state';
        END IF;

    ELSIF NEW.region_level = 'area' THEN
        IF NEW.city IS NULL OR TRIM(NEW.city) = '' OR NEW.area IS NULL OR TRIM(NEW.area) = '' THEN
            RAISE EXCEPTION 'INVALID_LOCATION: City and Area are required for area-level teams';
        END IF;

        IF NEW.parent_team_id IS NULL THEN
            RAISE EXCEPTION 'INVALID_PARENT: Area team requires a city-level parent team';
        END IF;

        SELECT id, region_level, state, city INTO v_parent FROM public.teams WHERE id = NEW.parent_team_id AND is_active = true;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'PARENT_NOT_FOUND: Parent city team does not exist or is inactive';
        END IF;
        IF v_parent.region_level != 'city' THEN
            RAISE EXCEPTION 'INVALID_PARENT_LEVEL: Parent of an area team must be a city-level team';
        END IF;
        IF LOWER(TRIM(v_parent.state)) != LOWER(TRIM(NEW.state)) OR LOWER(TRIM(v_parent.city)) != LOWER(TRIM(NEW.city)) THEN
            RAISE EXCEPTION 'LOCATION_MISMATCH: Area team state and city must match parent team location';
        END IF;
    END IF;

    -- Cycle check using recursive parent check
    IF NEW.parent_team_id IS NOT NULL THEN
        v_curr_id := NEW.parent_team_id;
        WHILE v_curr_id IS NOT NULL LOOP
            v_depth := v_depth + 1;
            IF v_depth > 50 THEN
                RAISE EXCEPTION 'HIERARCHY_CYCLE: Exceeded max depth, cycle detected';
            END IF;
            IF NEW.id IS NOT NULL AND v_curr_id = NEW.id THEN
                RAISE EXCEPTION 'HIERARCHY_CYCLE: Ancestor/descendant cycle detected';
            END IF;
            SELECT parent_team_id INTO v_curr_id FROM public.teams WHERE id = v_curr_id;
        END LOOP;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.merge_duplicate_user_data(p_duplicate_id uuid, p_original_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    -- 1. Merge customer_wallets
    IF EXISTS (SELECT 1 FROM public.customer_wallets WHERE user_id = p_original_id) AND
       EXISTS (SELECT 1 FROM public.customer_wallets WHERE user_id = p_duplicate_id) THEN
        UPDATE public.customer_wallets
        SET balance_paise = balance_paise + (SELECT balance_paise FROM public.customer_wallets WHERE user_id = p_duplicate_id),
            updated_at = now()
        WHERE user_id = p_original_id;

        DELETE FROM public.customer_wallets WHERE user_id = p_duplicate_id;
    ELSE
        UPDATE public.customer_wallets
        SET user_id = p_original_id
        WHERE user_id = p_duplicate_id;
    END IF;

    -- 2. Merge reward_points_balance
    IF EXISTS (SELECT 1 FROM public.reward_points_balance WHERE user_id = p_original_id) AND
       EXISTS (SELECT 1 FROM public.reward_points_balance WHERE user_id = p_duplicate_id) THEN
        UPDATE public.reward_points_balance
        SET total_earned = total_earned + (SELECT total_earned FROM public.reward_points_balance WHERE user_id = p_duplicate_id),
            total_redeemed = total_redeemed + (SELECT total_redeemed FROM public.reward_points_balance WHERE user_id = p_duplicate_id),
            current_balance = current_balance + (SELECT current_balance FROM public.reward_points_balance WHERE user_id = p_duplicate_id),
            tree_size = tree_size + COALESCE((SELECT tree_size FROM public.reward_points_balance WHERE user_id = p_duplicate_id), 0),
            direct_referrals = direct_referrals + COALESCE((SELECT direct_referrals FROM public.reward_points_balance WHERE user_id = p_duplicate_id), 0),
            active_downline = active_downline + COALESCE((SELECT active_downline FROM public.reward_points_balance WHERE user_id = p_duplicate_id), 0),
            updated_at = now()
        WHERE user_id = p_original_id;

        DELETE FROM public.reward_points_balance WHERE user_id = p_duplicate_id;
    ELSE
        UPDATE public.reward_points_balance
        SET user_id = p_original_id
        WHERE user_id = p_duplicate_id;
    END IF;

    -- 3. Merchants
    IF EXISTS (SELECT 1 FROM public.merchants WHERE user_id = p_original_id) THEN
        DELETE FROM public.merchants WHERE user_id = p_duplicate_id;
    ELSE
        UPDATE public.merchants SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    END IF;

    -- 4. Merchant Wallets
    IF EXISTS (SELECT 1 FROM public.merchant_wallets WHERE user_id = p_original_id) THEN
        DELETE FROM public.merchant_wallets WHERE user_id = p_duplicate_id;
    ELSE
        UPDATE public.merchant_wallets SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    END IF;

    -- 5. Employees
    IF EXISTS (SELECT 1 FROM public.employees WHERE user_id = p_original_id) THEN
        DELETE FROM public.employees WHERE user_id = p_duplicate_id;
    ELSE
        UPDATE public.employees SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    END IF;

    -- 6. User Channel Bindings
    IF EXISTS (SELECT 1 FROM public.user_channel_bindings WHERE user_id = p_original_id) THEN
        DELETE FROM public.user_channel_bindings WHERE user_id = p_duplicate_id;
    ELSE
        UPDATE public.user_channel_bindings SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    END IF;

    -- 7. Admin Permissions
    IF EXISTS (SELECT 1 FROM public.admin_permissions WHERE admin_user_id = p_original_id) THEN
        DELETE FROM public.admin_permissions WHERE admin_user_id = p_duplicate_id;
    ELSE
        UPDATE public.admin_permissions SET admin_user_id = p_original_id WHERE admin_user_id = p_duplicate_id;
    END IF;

    -- 8. Reward Daily Caps
    IF EXISTS (SELECT 1 FROM public.reward_daily_caps WHERE user_id = p_original_id) THEN
        DELETE FROM public.reward_daily_caps WHERE user_id = p_duplicate_id;
    ELSE
        UPDATE public.reward_daily_caps SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    END IF;

    -- 9. User Wishlists (prevent unique constraint violations)
    DELETE FROM public.user_wishlists uw_dup
    WHERE user_id = p_duplicate_id
      AND EXISTS (
          SELECT 1 FROM public.user_wishlists uw_orig
          WHERE uw_orig.user_id = p_original_id
            AND uw_orig.product_id = uw_dup.product_id
      );
    UPDATE public.user_wishlists SET user_id = p_original_id WHERE user_id = p_duplicate_id;

    -- 10. Shopping Cart (merge quantity or repoint)
    UPDATE public.shopping_cart sc_orig
    SET quantity = sc_orig.quantity + sc_dup.quantity,
        updated_at = now()
    FROM public.shopping_cart sc_dup
    WHERE sc_orig.customer_id = p_original_id
      AND sc_dup.customer_id = p_duplicate_id
      AND sc_orig.inventory_id = sc_dup.inventory_id;

    DELETE FROM public.shopping_cart sc_dup
    WHERE customer_id = p_duplicate_id
      AND EXISTS (
          SELECT 1 FROM public.shopping_cart sc_orig
          WHERE sc_orig.customer_id = p_original_id
            AND sc_orig.inventory_id = sc_dup.inventory_id
      );
    UPDATE public.shopping_cart SET customer_id = p_original_id WHERE customer_id = p_duplicate_id;

    -- 11. Repoint references that reference user_profiles(id)
    UPDATE public.reward_distribution_log SET source_user_id = p_original_id WHERE source_user_id = p_duplicate_id;
    UPDATE public.reward_redemption_requests SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.udhari_requests SET customer_id = p_original_id WHERE customer_id = p_duplicate_id;
    UPDATE public.wallet_adjustment_logs SET admin_user_id = p_original_id WHERE admin_user_id = p_duplicate_id;
    UPDATE public.wallet_adjustment_logs SET target_user_id = p_original_id WHERE target_user_id = p_duplicate_id;
    UPDATE public.wallet_transactions SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.webchat_messages SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.attendance_logs SET employee_id = p_original_id WHERE employee_id = p_duplicate_id;
    DELETE FROM public.auth_tokens WHERE user_id = p_duplicate_id;
    UPDATE public.kyc_records SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.kyc_records SET reviewed_by = p_original_id WHERE reviewed_by = p_duplicate_id;
    UPDATE public.transactions SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.employee_documents SET employee_id = p_original_id WHERE employee_id = p_duplicate_id;
    UPDATE public.leave_balances SET employee_id = p_original_id WHERE employee_id = p_duplicate_id;
    UPDATE public.kyc_audit_logs SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.payout_pii_access_log SET admin_user_id = p_original_id WHERE admin_user_id = p_duplicate_id;
    UPDATE public.attendance SET employee_id = p_original_id WHERE employee_id = p_duplicate_id;
    UPDATE public.career_applications SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.customer_wallet_transactions SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.lead_interactions SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.leave_requests SET employee_id = p_original_id WHERE employee_id = p_duplicate_id;
    UPDATE public.merchant_ratings SET customer_id = p_original_id WHERE customer_id = p_duplicate_id;
    UPDATE public.nfc_orders SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.notifications SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.webchat_sessions SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.orders SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.payout_requests SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.reward_transactions SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.reward_transactions SET source_user_id = p_original_id WHERE source_user_id = p_duplicate_id;
    UPDATE public.salary_records SET employee_id = p_original_id WHERE employee_id = p_duplicate_id;
    UPDATE public.whatsapp_message_logs SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.shopping_order_groups SET customer_id = p_original_id WHERE customer_id = p_duplicate_id;
    UPDATE public.solar_leads SET user_id = p_original_id WHERE user_id = p_duplicate_id;
    UPDATE public.admin_tasks SET assigned_to = p_original_id WHERE assigned_to = p_duplicate_id;
    UPDATE public.admin_tasks SET assigned_by = p_original_id WHERE assigned_by = p_duplicate_id;
    UPDATE public.crm_tasks SET assigned_to = p_original_id WHERE assigned_to = p_duplicate_id;
    UPDATE public.platform_procurement_orders SET created_by_admin = p_original_id WHERE created_by_admin = p_duplicate_id;

    -- 12. Repoint all references that point directly to auth.users(id)
    UPDATE public.crm_leads SET assigned_to = p_original_id WHERE assigned_to = p_duplicate_id;
    UPDATE public.crm_leads SET created_by = p_original_id WHERE created_by = p_duplicate_id;
    UPDATE public.employees SET reporting_manager_id = p_original_id WHERE reporting_manager_id = p_duplicate_id;
    UPDATE public.flash_sale_items SET created_by = p_original_id WHERE created_by = p_duplicate_id;
    UPDATE public.kyc_records SET verified_by = p_original_id WHERE verified_by = p_duplicate_id;
    UPDATE public.merchant_investments SET admin_id = p_original_id WHERE admin_id = p_duplicate_id;
    UPDATE public.merchant_lockin_balances SET admin_id = p_original_id WHERE admin_id = p_duplicate_id;
    UPDATE public.payout_request_events SET actor_id = p_original_id WHERE actor_id = p_duplicate_id;
    UPDATE public.payout_requests SET approved_by = p_original_id WHERE approved_by = p_duplicate_id;
    UPDATE public.payout_requests SET rejected_by = p_original_id WHERE rejected_by = p_duplicate_id;
    UPDATE public.payout_requests SET released_by = p_original_id WHERE released_by = p_duplicate_id;
    UPDATE public.payout_requests SET reviewed_by = p_original_id WHERE reviewed_by = p_duplicate_id;
    UPDATE public.reward_configuration SET created_by = p_original_id WHERE created_by = p_duplicate_id;
    UPDATE public.reward_configuration_history SET changed_by = p_original_id WHERE changed_by = p_duplicate_id;
    UPDATE public.reward_redemption_requests SET processed_by = p_original_id WHERE processed_by = p_duplicate_id;
    UPDATE public.shopping_order_groups SET assigned_to = p_original_id WHERE assigned_to = p_duplicate_id;
    UPDATE public.shopping_order_groups SET status_updated_by = p_original_id WHERE status_updated_by = p_duplicate_id;
    UPDATE public.shopping_products SET reviewed_by = p_original_id WHERE reviewed_by = p_duplicate_id;
    UPDATE public.training_materials SET created_by = p_original_id WHERE created_by = p_duplicate_id;
    UPDATE public.user_profiles SET referred_by = p_original_id WHERE referred_by = p_duplicate_id;
    UPDATE public.user_profiles SET reward_parent_id = p_original_id WHERE reward_parent_id = p_duplicate_id;

    -- 13. Finally delete the user profile for the duplicate
    DELETE FROM public.user_profiles WHERE id = p_duplicate_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.customer_purchase_from_platform(p_product_id uuid, p_quantity integer, p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_product RECORD;
    v_price_paise BIGINT;
    v_total_cost BIGINT;
    v_customer_balance BIGINT;
BEGIN
    -- 1. Get product details (lock row for update)
    SELECT id, admin_stock, platform_price_paise, suggested_retail_price_paise
    INTO v_product
    FROM public.shopping_products
    WHERE id = p_product_id
    FOR UPDATE;

    IF v_product.admin_stock < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient platform stock');
    END IF;

    -- Use platform_price_paise when set; fall back to suggested_retail_price_paise
    v_price_paise := COALESCE(v_product.platform_price_paise, v_product.suggested_retail_price_paise);
    v_total_cost  := v_price_paise * p_quantity;

    -- 2. Check customer balance
    SELECT wallet_balance_paise INTO v_customer_balance
    FROM public.user_profiles WHERE id = p_customer_id FOR UPDATE;

    IF v_customer_balance < v_total_cost THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient wallet balance');
    END IF;

    -- 3. Update balances and stock
    UPDATE public.user_profiles
    SET wallet_balance_paise = wallet_balance_paise - v_total_cost
    WHERE id = p_customer_id;

    UPDATE public.shopping_products
    SET admin_stock = admin_stock - p_quantity
    WHERE id = p_product_id;

    -- 4. Log Order
    INSERT INTO public.shopping_orders (
        buyer_id, buyer_type, seller_id, seller_type,
        product_id, quantity, unit_price_paise, total_price_paise, order_type
    )
    VALUES (
        p_customer_id, 'customer', NULL, 'admin',
        p_product_id, p_quantity, v_price_paise, v_total_cost, 'retail'
    );

    RETURN jsonb_build_object('success', true, 'message', 'Order placed successfully');
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_reject_payout(p_request_id uuid, p_admin_user_id uuid, p_admin_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_payout         record;
    v_from_status    text;
    v_balance_before bigint;
    v_balance_after  bigint;
    v_actual_admin_id uuid;
    v_admin_role text;
BEGIN
    -- 1. Securely derive the caller identity
    v_actual_admin_id := auth.uid();

    IF v_actual_admin_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    -- Verify the caller has an admin role
    SELECT role::text INTO v_admin_role
    FROM public.user_profiles
    WHERE id = v_actual_admin_id;

    IF v_admin_role NOT IN ('admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin access required');
    END IF;

    -- 2. Lock the payout request row
    SELECT * INTO v_payout
    FROM payout_requests
    WHERE id = p_request_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_found');
    END IF;

    v_from_status := v_payout.status;

    -- 3. Only pending or approved can be rejected
    IF v_payout.status NOT IN ('pending', 'approved') THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_rejectable');
    END IF;

    -- 4. Reverse the source-specific operation (use amount_paise column)
    IF v_payout.payout_source = 'wallet' THEN
        -- Fetch current balance before refund
        SELECT wallet_balance_paise INTO v_balance_before
        FROM merchants
        WHERE id = v_payout.merchant_id
        FOR UPDATE;

        v_balance_after := v_balance_before + v_payout.amount_paise;

        UPDATE merchants
        SET    wallet_balance_paise = v_balance_after
        WHERE  id = v_payout.merchant_id;

        INSERT INTO wallet_transactions (
            user_id, merchant_id, transaction_type, amount,
            balance_before, balance_after,
            description, reference_type, reference_id
        )
        VALUES (
            v_payout.user_id,
            v_payout.merchant_id,
            'CREDIT',
            (v_payout.amount_paise::numeric / 100),
            (v_balance_before::numeric / 100),
            (v_balance_after::numeric / 100),
            'Payout request #' || UPPER(LEFT(p_request_id::text, 8)) || ' rejected — amount refunded to wallet',
            'payout_request',
            p_request_id
        );

    ELSIF v_payout.payout_source = 'growth_fund' THEN
        UPDATE merchant_lockin_balances
        SET    status = 'matured'
        WHERE  id = v_payout.reference_id;
    END IF;

    -- 5. Update the payout request
    UPDATE payout_requests
    SET    status      = 'rejected',
           admin_note  = p_admin_note,
           reviewed_by = v_actual_admin_id, -- SECURE
           reviewed_at = now()
    WHERE  id = p_request_id;

    -- 6. Audit event
    INSERT INTO payout_request_events (
        payout_id, actor_id, action, from_status, to_status, payload
    )
    VALUES (
        p_request_id, v_actual_admin_id, 'rejected', v_from_status, 'rejected', -- SECURE
        jsonb_build_object('admin_note', p_admin_note)
    );

    RETURN jsonb_build_object('success', true);

EXCEPTION WHEN OTHERS THEN
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_update_order_status(p_order_id uuid, p_delivery_status text, p_tracking_number text DEFAULT NULL::text, p_estimated_delivery_date date DEFAULT NULL::date)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_order RECORD;
    v_admin_role TEXT;
BEGIN
    -- Admin check
    SELECT role INTO v_admin_role FROM public.user_profiles WHERE id = auth.uid();
    IF v_admin_role != 'admin' THEN
        RETURN json_build_object('success', false, 'message', 'Unauthorized');
    END IF;

    SELECT * INTO v_order
    FROM public.shopping_order_groups
    WHERE id = p_order_id;

    IF NOT FOUND THEN
        RETURN json_build_object('success', false, 'message', 'Order not found');
    END IF;

    IF p_delivery_status NOT IN ('pending', 'packed', 'shipped', 'delivered', 'cancelled') THEN
        RETURN json_build_object('success', false, 'message', 'Invalid status');
    END IF;

    IF p_delivery_status = 'shipped' THEN
        UPDATE public.shopping_order_groups
        SET delivery_status = p_delivery_status,
            tracking_number = COALESCE(p_tracking_number, tracking_number),
            estimated_delivery_date = COALESCE(p_estimated_delivery_date, estimated_delivery_date)
        WHERE id = p_order_id;
    ELSE
        UPDATE public.shopping_order_groups
        SET delivery_status = p_delivery_status
        WHERE id = p_order_id;
    END IF;

    RETURN json_build_object('success', true, 'message', 'Order status updated');
EXCEPTION WHEN OTHERS THEN
    RETURN json_build_object('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_activate_auto_mode(p_merchant_id uuid, p_price_paise bigint, p_description text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_current_balance BIGINT;
    v_months_paid INTEGER;
    v_new_balance BIGINT;
    v_valid_until TIMESTAMPTZ;
BEGIN
    -- Get merchant and lock row for update to prevent concurrent balance deductions
    SELECT wallet_balance_paise, COALESCE(auto_mode_months_paid, 0)
    INTO v_current_balance, v_months_paid
    FROM public.merchants
    WHERE id = p_merchant_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Merchant record not found');
    END IF;

    -- Atomically check balance
    IF v_current_balance < p_price_paise THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient wallet balance');
    END IF;

    -- Calculate updated values
    v_new_balance := v_current_balance - p_price_paise;
    v_valid_until := NOW() + INTERVAL '30 days';
    v_months_paid := v_months_paid + 1;

    -- Deduct and Activate in a single transaction
    UPDATE public.merchants
    SET 
        wallet_balance_paise = v_new_balance,
        auto_mode = true,
        auto_mode_status = 'active',
        auto_mode_months_paid = v_months_paid,
        auto_mode_valid_until = v_valid_until,
        updated_at = NOW()
    WHERE id = p_merchant_id;

    -- Log transaction to ledger (atomic under the same transaction)
    INSERT INTO public.merchant_transactions (
        merchant_id,
        amount_paise,
        transaction_type,
        description,
        balance_after_paise,
        metadata,
        created_at
    ) VALUES (
        p_merchant_id,
        -p_price_paise,
        'subscription',
        p_description,
        v_new_balance,
        p_metadata,
        NOW()
    );

    RETURN jsonb_build_object(
        'success', true, 
        'message', 'Auto Mode activated successfully',
        'new_balance', v_new_balance,
        'valid_until', v_valid_until,
        'months_paid', v_months_paid
    );

EXCEPTION WHEN OTHERS THEN
    -- Log the error with SQLSTATE for Supabase logs visibility
    RAISE WARNING 'RPC merchant_activate_auto_mode failed. SQLSTATE: %, SQLERRM: %', SQLSTATE, SQLERRM;

    -- Return detailed error message for debugging (Supabase API will see this in the response body)
    RETURN jsonb_build_object(
        'success', false, 
        'message', 'Database error: ' || SQLSTATE || ' - ' || SQLERRM
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_route_lead_territory()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_match RECORD;
    v_rep_id UUID;
    v_team_changed BOOLEAN;
BEGIN
    -- manual_override explicitly bypasses automatic routing
    IF (TG_OP = 'UPDATE' AND NEW.routing_status = 'manual_override') THEN
        RETURN NEW;
    END IF;

    -- Boundary Normalization
    NEW.pincode := NULLIF(btrim(NEW.pincode), '');
    NEW.zone    := NULLIF(btrim(NEW.zone), '');
    NEW.area    := NULLIF(btrim(NEW.area), '');
    NEW.city    := NULLIF(btrim(NEW.city), '');
    NEW.state   := NULLIF(btrim(NEW.state), '');

    -- If it's already auto_matched, only re-route if location changed
    IF TG_OP = 'UPDATE' AND NEW.routing_status = 'auto_matched' THEN
        IF NOT (
            NEW.pincode IS DISTINCT FROM OLD.pincode OR
            NEW.zone IS DISTINCT FROM OLD.zone OR
            NEW.area IS DISTINCT FROM OLD.area OR
            NEW.city IS DISTINCT FROM OLD.city OR
            NEW.state IS DISTINCT FROM OLD.state
        ) THEN
            RETURN NEW; 
        END IF;
    END IF;

    v_match := public.crm_match_team_for_location(NEW.pincode, NEW.zone, NEW.area, NEW.city, NEW.state);

    IF v_match.out_team_id IS NOT NULL THEN
        -- Check if team has changed BEFORE updating NEW
        v_team_changed := (TG_OP = 'UPDATE' AND v_match.out_team_id IS DISTINCT FROM OLD.assigned_team_id) OR (TG_OP = 'INSERT');

        NEW.assigned_team_id     := v_match.out_team_id;
        NEW.territory_match_type := v_match.out_match_type;
        NEW.routing_status       := 'auto_matched';
        NEW.routed_at            := now();

        IF (NEW.assigned_to IS NULL OR v_team_changed) THEN
            v_rep_id := public.crm_pick_team_rep(v_match.out_team_id);
            NEW.assigned_to := v_rep_id;
        END IF;
    ELSE
        NEW.assigned_team_id     := NULL;
        NEW.territory_match_type := NULL;
        NEW.routing_status       := 'unmatched';
        NEW.routed_at            := NULL;
        NEW.assigned_to          := NULL;
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.increment_customer_wallet(p_user_id uuid, p_amount_paise bigint, p_type text, p_description text, p_reference_id text DEFAULT NULL::text, p_reference_type text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_wallet_id UUID;
    v_balance_before BIGINT;
    v_balance_after BIGINT;
    v_tx_id UUID;
BEGIN
    -- 1. Get or create wallet and lock it for update to prevent race conditions
    SELECT id, balance_paise INTO v_wallet_id, v_balance_before
    FROM customer_wallets
    WHERE user_id = p_user_id
    FOR UPDATE;

    IF NOT FOUND THEN
        -- Insert new wallet returning details, implicitly locking it
        INSERT INTO customer_wallets (user_id, balance_paise, status)
        VALUES (p_user_id, 0, 'ACTIVE')
        RETURNING id, balance_paise INTO v_wallet_id, v_balance_before;
    END IF;

    -- 2. Calculate new balance
    v_balance_after := v_balance_before + p_amount_paise;

    -- If decrementing, check for sufficient funds
    IF p_amount_paise < 0 AND v_balance_after < 0 THEN
        RAISE EXCEPTION 'Insufficient wallet balance';
    END IF;

    -- 3. Update wallet
    UPDATE customer_wallets
    SET balance_paise = v_balance_after,
        updated_at = NOW()
    WHERE id = v_wallet_id;

    -- 4. Record transaction
    INSERT INTO customer_wallet_transactions (
        wallet_id, user_id, type, amount_paise,
        balance_before_paise, balance_after_paise,
        description, reference_id, reference_type
    ) VALUES (
        v_wallet_id, p_user_id, p_type, ABS(p_amount_paise),
        v_balance_before, v_balance_after,
        p_description, p_reference_id, p_reference_type
    ) RETURNING id INTO v_tx_id;

    RETURN json_build_object(
        'walletId', v_wallet_id,
        'newBalance', (v_balance_after::numeric / 100.0),
        'transaction_id', v_tx_id
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_takeover_single_order(p_order_id uuid, p_admin_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id        uuid;
    v_caller_role      text;
    v_order            RECORD;
    v_new_platform_cut    bigint;
    v_new_merchant_profit bigint;
    v_merchant_user_id    uuid;
    v_total_product_value bigint;
    v_total_cost_price    bigint;
    v_total_profit        bigint;
BEGIN
    -- Derive actor from session
    v_caller_id := auth.uid();

    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Unauthorized: not authenticated');
    END IF;

    SELECT role INTO v_caller_role
    FROM public.user_profiles
    WHERE id = v_caller_id;

    IF v_caller_role NOT IN ('admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'message', 'Unauthorized: admin role required');
    END IF;

    -- Fetch the eligible order
    SELECT sog.*, m.user_id INTO v_order
    FROM public.shopping_order_groups sog
    JOIN public.merchants m ON sog.merchant_id = m.id
    WHERE sog.id           = p_order_id
      AND sog.delivery_status   = 'pending'
      AND sog.settlement_status = 'pending'
      AND sog.is_platform_order = false;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Order not eligible for takeover');
    END IF;

    v_merchant_user_id := v_order.user_id;

    -- Takeover Penalty Law: 70% of profit goes to platform, 30% to merchant
    v_total_product_value := v_order.total_amount_paise - COALESCE(v_order.delivery_fee_paise, 0);

    SELECT COALESCE(SUM(p.wholesale_price_paise * i.quantity), 0)
    INTO v_total_cost_price
    FROM public.shopping_order_items i
    JOIN public.shopping_products    p ON i.product_id = p.id
    WHERE i.group_id = p_order_id;

    v_total_profit        := GREATEST(0, v_total_product_value - v_total_cost_price);
    v_new_platform_cut    := ROUND(v_total_profit * 70 / 100);
    v_new_merchant_profit := v_total_profit - v_new_platform_cut; -- FIXED: 30% of profit margin

    -- Update order group
    UPDATE public.shopping_order_groups
    SET commission_rate    = 0.70, -- 70% platform SHARE of profit
        platform_cut_paise = v_new_platform_cut,
        merchant_profit_paise = v_new_merchant_profit,
        assigned_to        = v_caller_id,
        admin_takeover_at  = NOW(),
        settlement_status  = 'admin_takeover'
    WHERE id = v_order.id;

    -- Update per-item commissions
    UPDATE public.shopping_order_items soi
    SET commission_amount_paise =
            GREATEST(0, (soi.unit_price_paise - COALESCE(p.wholesale_price_paise, 0)))
            * soi.quantity * 70 / 100,
        profit_paise =
            GREATEST(0, (soi.unit_price_paise - COALESCE(p.wholesale_price_paise, 0)))
            * soi.quantity * 30 / 100 -- FIXED: 30% of per-item margin
    FROM public.shopping_products p
    WHERE soi.product_id = p.id
      AND soi.group_id   = v_order.id;

    -- Credit merchant wallet
    UPDATE public.merchants
    SET wallet_balance_paise        = COALESCE(wallet_balance_paise, 0)        + v_new_merchant_profit,
        total_commission_paid_paise = COALESCE(total_commission_paid_paise, 0) + v_new_platform_cut
    WHERE id = v_order.merchant_id;

    -- Merchant transaction log
    INSERT INTO public.merchant_transactions (
        merchant_id, transaction_type, amount_paise, commission_paise, balance_after_paise, description
    ) VALUES (
        v_order.merchant_id, 'sale', v_new_merchant_profit, v_new_platform_cut,
        (SELECT wallet_balance_paise FROM public.merchants WHERE id = v_order.merchant_id),
        'Admin Takeover: Merchant profit share reduced to 30% (70% platform commission).'
    );

    -- Notification
    INSERT INTO public.notifications (user_id, title, body, type, reference_id, reference_type)
    VALUES (
        v_merchant_user_id,
        'Order Taken Over ⚠️',
        'Order #' || substring(v_order.id::text from 1 for 8) || ' was taken over by admin. Merchant profit share reduced to 30%.',
        'warning',
        v_order.id,
        'shopping_order'
    );

    RETURN jsonb_build_object('success', true);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.procure_from_merchant(p_merchant_id uuid, p_items jsonb, p_idempotency_key uuid, p_admin_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_item                  jsonb;
    v_product_id            uuid;
    v_inv_id                uuid;
    v_qty                   integer;
    v_platform_price_paise  bigint;
    v_product               RECORD;
    v_inv                   RECORD;
    v_existing_id           uuid;
    v_existing_amount       bigint;
    v_existing_gst          bigint;
    v_existing_invoice      text;
    v_cost_paise            bigint;
    v_gst_paise             bigint;
    v_line_total_paise      bigint;
    v_total_cost_paise      bigint  := 0;
    v_total_gst_paise       bigint  := 0;
    v_total_amount_paise    bigint  := 0;
    v_caller_role           text;
    v_effective_admin_id    uuid;
    v_merchant_status       text;
    v_merchant_user_id      uuid;
    v_procurement_id        uuid;
    v_invoice_number        text;
    v_item_count            integer := 0;
BEGIN
    v_effective_admin_id := COALESCE(p_admin_id, auth.uid());

    -- Idempotency check (Bug #6: also fetch invoice_number for replay path)
    SELECT id, total_amount_paise, total_gst_paise, invoice_number
    INTO   v_existing_id, v_existing_amount, v_existing_gst, v_existing_invoice
    FROM   public.platform_procurement_orders
    WHERE  idempotency_key = p_idempotency_key;

    IF FOUND THEN
        RETURN jsonb_build_object(
            'success',            true,
            'idempotent',         true,
            'procurement_id',     v_existing_id,
            'total_amount_paise', v_existing_amount,
            'total_gst_paise',    v_existing_gst,
            'invoice_number',     v_existing_invoice
        );
    END IF;

    SELECT role INTO v_caller_role
    FROM public.user_profiles
    WHERE id = v_effective_admin_id;

    IF v_caller_role NOT IN ('admin', 'super_admin') THEN
        RAISE EXCEPTION 'Unauthorized: admin or super_admin role required';
    END IF;

    SELECT status, user_id INTO v_merchant_status, v_merchant_user_id
    FROM public.merchants
    WHERE id = p_merchant_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Merchant not found: %', p_merchant_id;
    END IF;

    IF v_merchant_status != 'approved' THEN
        RAISE EXCEPTION 'Merchant % is not approved (status: %)', p_merchant_id, v_merchant_status;
    END IF;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_product_id           := (v_item->>'product_id')::uuid;
        v_inv_id               := (v_item->>'merchant_inventory_id')::uuid;
        v_qty                  := (v_item->>'quantity')::integer;
        v_platform_price_paise := (v_item->>'platform_price_paise')::bigint;

        IF v_qty <= 0 THEN
            RAISE EXCEPTION 'Quantity must be greater than zero for product %', v_product_id;
        END IF;

        SELECT id, wholesale_price_paise, gst_percentage, approval_status, submitted_by_merchant_id, admin_stock
        INTO v_product
        FROM public.shopping_products
        WHERE id = v_product_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Product not found: %', v_product_id;
        END IF;

        IF v_product.approval_status != 'live' THEN
            RAISE EXCEPTION 'Product % is not live (status: %)', v_product_id, v_product.approval_status;
        END IF;

        IF v_product.submitted_by_merchant_id != p_merchant_id THEN
            RAISE EXCEPTION 'Product % does not belong to merchant %', v_product_id, p_merchant_id;
        END IF;

        SELECT id, stock_quantity
        INTO v_inv
        FROM public.merchant_inventory
        WHERE id = v_inv_id
        FOR UPDATE;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Merchant inventory row not found: %', v_inv_id;
        END IF;

        IF v_inv.stock_quantity < v_qty THEN
            RAISE EXCEPTION 'Insufficient merchant inventory stock for product % (have %, need %)',
                v_product_id, v_inv.stock_quantity, v_qty;
        END IF;

        v_cost_paise       := v_product.wholesale_price_paise * v_qty;
        v_gst_paise        := ROUND(v_cost_paise * COALESCE(v_product.gst_percentage, 0) / 100.0);
        v_line_total_paise := v_cost_paise + v_gst_paise;

        v_total_cost_paise   := v_total_cost_paise   + v_cost_paise;
        v_total_gst_paise    := v_total_gst_paise    + v_gst_paise;
        v_total_amount_paise := v_total_amount_paise + v_line_total_paise;
        v_item_count         := v_item_count + v_qty;

        UPDATE public.merchant_inventory
        SET stock_quantity = stock_quantity - v_qty
        WHERE id = v_inv_id;

        -- Re-procurement of a previously-delisted product restores platform_listed.
        UPDATE public.shopping_products
        SET admin_stock          = admin_stock + v_qty,
            platform_listed      = true,
            platform_price_paise = v_platform_price_paise
        WHERE id = v_product_id;
    END LOOP;

    PERFORM set_config('app.internal_bypass', 'true', true);

    UPDATE public.merchants
    SET wallet_balance_paise = COALESCE(wallet_balance_paise, 0) + v_total_amount_paise
    WHERE id = p_merchant_id;

    PERFORM set_config('app.internal_bypass', 'false', true);

    INSERT INTO public.merchant_transactions (
        merchant_id, transaction_type, amount_paise, balance_after_paise, description, purchase_batch_id
    )
    SELECT
        p_merchant_id, 'sale_earnings', v_total_amount_paise, wallet_balance_paise,
        'Platform procurement - Rs.' || (v_total_amount_paise / 100)::text
            || ' across ' || v_item_count::text || ' units',
        p_idempotency_key
    FROM public.merchants
    WHERE id = p_merchant_id;

    v_procurement_id := gen_random_uuid();

    -- Bug #6: Generate invoice_number atomically inside this transaction
    v_invoice_number := 'PINV-' || to_char(now(), 'YYYY') || '-'
                        || upper(substring(v_procurement_id::text from 1 for 8));

    -- Bug #3: Replace ORDER BY LIMIT 1 pre-read with aggregate SUM (race-free)
    INSERT INTO public.platform_ledger (
        transaction_id, entry_type, amount_paise, balance_after_paise, description
    ) VALUES (
        v_procurement_id,
        'wholesale_procurement',
        -v_total_amount_paise,
        (SELECT COALESCE(SUM(amount_paise), 0) FROM public.platform_ledger)
            - v_total_amount_paise,
        'Wholesale procurement from merchant ' || p_merchant_id::text
    );

    -- Bug #6: invoice_number inserted atomically with the order
    INSERT INTO public.platform_procurement_orders (
        id, merchant_id, created_by_admin, status, fulfillment_mode,
        total_cost_paise, total_gst_paise, total_amount_paise,
        invoice_number, idempotency_key
    ) VALUES (
        v_procurement_id, p_merchant_id, v_effective_admin_id, 'completed', 'intrust',
        v_total_cost_paise, v_total_gst_paise, v_total_amount_paise,
        v_invoice_number, p_idempotency_key
    );

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
        v_product_id           := (v_item->>'product_id')::uuid;
        v_inv_id               := (v_item->>'merchant_inventory_id')::uuid;
        v_qty                  := (v_item->>'quantity')::integer;
        v_platform_price_paise := (v_item->>'platform_price_paise')::bigint;

        SELECT wholesale_price_paise, gst_percentage
        INTO v_product
        FROM public.shopping_products
        WHERE id = v_product_id;

        v_cost_paise       := v_product.wholesale_price_paise * v_qty;
        v_gst_paise        := ROUND(v_cost_paise * COALESCE(v_product.gst_percentage, 0) / 100.0);
        v_line_total_paise := v_cost_paise + v_gst_paise;

        INSERT INTO public.platform_procurement_items (
            procurement_id, product_id, merchant_inventory_id, quantity,
            unit_wholesale_paise, gst_percentage, gst_amount_paise,
            line_total_paise, platform_price_paise
        ) VALUES (
            v_procurement_id, v_product_id, v_inv_id, v_qty,
            v_product.wholesale_price_paise, COALESCE(v_product.gst_percentage, 0),
            v_gst_paise, v_line_total_paise, v_platform_price_paise
        );
    END LOOP;

    INSERT INTO public.notifications (
        user_id, title, body, type, reference_type, reference_id, read
    ) VALUES (
        v_merchant_user_id,
        'Platform purchased your stock',
        'Rs.' || (v_total_amount_paise / 100)::text
            || ' credited to your wallet for '
            || v_item_count::text || ' units procured by InTrust.',
        'success', 'procurement_sale', v_procurement_id, false
    );

    RETURN jsonb_build_object(
        'success',            true,
        'idempotent',         false,
        'procurement_id',     v_procurement_id,
        'total_amount_paise', v_total_amount_paise,
        'total_gst_paise',    v_total_gst_paise,
        'invoice_number',     v_invoice_number
    );

EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('app.internal_bypass', 'false', true);
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.respond_store_credit_request(p_udhari_request_id uuid, p_merchant_user_id uuid, p_action text, p_duration_days integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_udhari      record;
  v_merchant    record;
  v_due_date    timestamptz;
BEGIN
  -- Resolve merchant from user_id
  SELECT * INTO v_merchant
  FROM merchants
  WHERE user_id = p_merchant_user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'merchant_not_found';
  END IF;

  -- Fetch the pending request
  SELECT * INTO v_udhari
  FROM udhari_requests
  WHERE id = p_udhari_request_id
    AND merchant_id = v_merchant.id
    AND status = 'pending'
    AND source_type = 'shop_order'
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'request_not_found_or_already_processed';
  END IF;

  IF p_action = 'approve' THEN
    v_due_date := NOW() + (COALESCE(p_duration_days, v_udhari.duration_days) || ' days')::interval;

    -- NOTE: The merchant ledger fields (commission_rate, platform_cut_paise,
    -- merchant_profit_paise, per-item cost_price_paise / profit_paise /
    -- commission_amount_paise) are intentionally NOT computed here.
    -- They are populated atomically inside settle_store_credit_for_cart at the
    -- moment the customer's wallet is debited, which is also when we flip
    -- settlement_status to 'settled'. Do not duplicate that work in this RPC.
    UPDATE udhari_requests
    SET status        = 'approved',
        due_date      = v_due_date,
        responded_at  = NOW()
    WHERE id = p_udhari_request_id;

    RETURN jsonb_build_object('success', true, 'action', 'approved', 'due_date', v_due_date);

  ELSIF p_action = 'deny' THEN
    -- Revert the order group back to pending so customer can pick another payment
    UPDATE shopping_order_groups
    SET payment_method  = NULL,
        delivery_status = 'pending'
    WHERE id = v_udhari.shopping_order_group_id;

    UPDATE udhari_requests
    SET status       = 'denied',
        responded_at = NOW()
    WHERE id = p_udhari_request_id;

    RETURN jsonb_build_object('success', true, 'action', 'denied');

  ELSE
    RAISE EXCEPTION 'invalid_action';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.customer_bulk_purchase(p_items jsonb, p_customer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_item RECORD;
    v_total_cost_paise BIGINT := 0;
    v_customer_wallet_balance BIGINT;
    v_inv_price BIGINT;
    v_inv_stock INTEGER;
    v_merchant_id UUID;
    v_new_balance BIGINT;
BEGIN
    -- 1. Calculate total cost and verify stock for all items
    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(inventory_id UUID, quantity INTEGER) LOOP
        SELECT retail_price_paise, stock_quantity, merchant_id
        INTO v_inv_price, v_inv_stock, v_merchant_id
        FROM public.merchant_inventory
        WHERE id = v_item.inventory_id AND is_active = true;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Product % not available', v_item.inventory_id;
        END IF;

        IF v_inv_stock < v_item.quantity THEN
            RAISE EXCEPTION 'Insufficient stock for product %', v_item.inventory_id;
        END IF;

        v_total_cost_paise := v_total_cost_paise + (v_inv_price * v_item.quantity);
    END LOOP;

    -- 2. Check customer wallet balance
    SELECT wallet_balance_paise INTO v_customer_wallet_balance
    FROM public.user_profiles
    WHERE id = p_customer_id;

    IF v_customer_wallet_balance < v_total_cost_paise THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient wallet balance');
    END IF;

    -- 3. Perform transactions for each item
    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(inventory_id UUID, quantity INTEGER) LOOP
        SELECT retail_price_paise, merchant_id INTO v_inv_price, v_merchant_id
        FROM public.merchant_inventory WHERE id = v_item.inventory_id;

        -- Deduct from customer wallet
        UPDATE public.user_profiles 
        SET wallet_balance_paise = wallet_balance_paise - (v_inv_price * v_item.quantity)
        WHERE id = p_customer_id;

        -- Add to merchant wallet
        UPDATE public.merchants
        SET wallet_balance_paise = wallet_balance_paise + (v_inv_price * v_item.quantity)
        WHERE id = v_merchant_id;

        -- Reduce merchant stock
        UPDATE public.merchant_inventory
        SET stock_quantity = stock_quantity - v_item.quantity
        WHERE id = v_item.inventory_id;

        -- Create order record
        INSERT INTO public.shopping_orders (
            customer_id,
            merchant_id,
            inventory_id,
            quantity,
            unit_price_paise,
            total_price_paise,
            status
        )
        VALUES (
            p_customer_id,
            v_merchant_id,
            v_item.inventory_id,
            v_item.quantity,
            v_inv_price,
            (v_inv_price * v_item.quantity),
            'completed'
        );
    END LOOP;

    SELECT wallet_balance_paise INTO v_new_balance FROM public.user_profiles WHERE id = p_customer_id;

    RETURN jsonb_build_object('success', true, 'message', 'Purchase successful', 'new_balance', v_new_balance);
EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$function$

CREATE OR REPLACE FUNCTION public.wallet_buy_gift_card(p_user_id uuid, p_coupon_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_wallet            RECORD;
    v_coupon            RECORD;
    v_purchase_paise    BIGINT;
    v_new_balance       BIGINT;
    v_order_id          UUID;
BEGIN
    SELECT id, balance_paise
    INTO   v_wallet
    FROM   public.customer_wallets
    WHERE  user_id = p_user_id
    FOR    UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Wallet not found');
    END IF;

    SELECT id, status, selling_price_paise, face_value_paise,
           merchant_id, title
    INTO   v_coupon
    FROM   public.coupons
    WHERE  id = p_coupon_id
    FOR    UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'message', 'Gift card not found');
    END IF;

    IF v_coupon.status <> 'available' THEN
        RETURN jsonb_build_object('success', false, 'message', 'Gift card is not available');
    END IF;

    v_purchase_paise := COALESCE(
        NULLIF(v_coupon.selling_price_paise, 0),
        v_coupon.face_value_paise,
        0
    );

    IF v_wallet.balance_paise < v_purchase_paise THEN
        RETURN jsonb_build_object('success', false, 'message', 'Insufficient wallet balance');
    END IF;

    v_new_balance := v_wallet.balance_paise - v_purchase_paise;

    UPDATE public.customer_wallets
    SET    balance_paise = v_new_balance,
           updated_at    = now()
    WHERE  id = v_wallet.id;

    -- reference_id is TEXT in customer_wallet_transactions
    INSERT INTO public.customer_wallet_transactions (
        wallet_id, user_id, type, amount_paise,
        balance_before_paise, balance_after_paise,
        description, reference_id, reference_type
    ) VALUES (
        v_wallet.id, p_user_id, 'DEBIT', v_purchase_paise,
        v_wallet.balance_paise, v_new_balance,
        'Purchased Gift Card: ' || COALESCE(v_coupon.title, 'Gift Card'),
        p_coupon_id::text, 'GIFT_CARD_PURCHASE'
    );

    UPDATE public.coupons
    SET    status       = 'sold',
           purchased_by = p_user_id,
           purchased_at = now()
    WHERE  id = p_coupon_id;

    INSERT INTO public.orders (
        user_id, merchant_id, giftcard_id,
        amount, payment_status, created_at
    ) VALUES (
        p_user_id, v_coupon.merchant_id, p_coupon_id,
        v_purchase_paise, 'paid', now()
    )
    RETURNING id INTO v_order_id;

    RETURN jsonb_build_object(
        'success',               true,
        'order_id',              v_order_id,
        'merchant_id',           v_coupon.merchant_id,
        'coupon_title',          COALESCE(v_coupon.title, 'Gift Card'),
        'new_balance_paise',     v_new_balance,
        'purchase_amount_paise', v_purchase_paise
    );

EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'message', SQLERRM);
END;
$function$

