CREATE OR REPLACE FUNCTION public.merchant_approve_udhari_request(p_request_id uuid, p_duration_days integer, p_merchant_note text, p_disclaimer_accepted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_request               record;
    v_group                 record;
    v_item                  record;
    v_merchant_inventory_stock int;
BEGIN
    -- 1. Lock udhari_request row
    SELECT * INTO v_request
    FROM udhari_requests
    WHERE id = p_request_id
    FOR UPDATE;

    IF v_request IS NULL THEN
        RAISE EXCEPTION 'Udhari request % not found', p_request_id;
    END IF;

    IF v_request.status != 'pending' THEN
        RAISE EXCEPTION 'Udhari request is not in pending status';
    END IF;

    -- 2. Process based on source_type
    IF v_request.source_type = 'shop_order' THEN
        -- Lock shopping_order_groups row
        SELECT * INTO v_group
        FROM shopping_order_groups
        WHERE id = v_request.shopping_order_group_id
        FOR UPDATE;

        IF v_group IS NULL THEN
            RAISE EXCEPTION 'Shopping order group % not found', v_request.shopping_order_group_id;
        END IF;

        -- Decrement stock for every item in the order
        FOR v_item IN
            SELECT * FROM shopping_order_items WHERE group_id = v_group.id
        LOOP
            SELECT stock_quantity INTO v_merchant_inventory_stock
            FROM merchant_inventory
            WHERE id = v_item.inventory_id
            FOR UPDATE;

            IF v_merchant_inventory_stock < v_item.quantity THEN
                RAISE EXCEPTION 'Insufficient stock for merchant_inventory_id %', v_item.inventory_id;
            END IF;

            UPDATE merchant_inventory
            SET stock_quantity = stock_quantity - v_item.quantity
            WHERE id = v_item.inventory_id;
        END LOOP;

        -- Confirm order group
        UPDATE shopping_order_groups
        SET delivery_status  = 'pending',
            payment_method   = 'store_credit'
        WHERE id = v_group.id;

    ELSIF v_request.source_type = 'gift_card' THEN
        -- Reserve the coupon atomically
        UPDATE coupons
        SET status = 'reserved'
        WHERE id = v_request.coupon_id AND status = 'available';

        IF NOT FOUND THEN
            RAISE EXCEPTION 'Coupon % not found or not available', v_request.coupon_id;
        END IF;

    ELSE
        RAISE EXCEPTION 'Unknown source_type %', v_request.source_type;
    END IF;

    -- 3. Mark udhari request as approved
    UPDATE udhari_requests
    SET status               = 'approved',
        due_date             = CURRENT_DATE + p_duration_days,
        duration_days        = p_duration_days,
        disclaimer_accepted  = p_disclaimer_accepted,
        merchant_note        = p_merchant_note,
        responded_at         = NOW()
    WHERE id = p_request_id;

    RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.generate_merchant_slug()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  base_slug TEXT;
  candidate TEXT;
  counter INT := 2;
BEGIN
  -- Only regenerate slug if business_name changed or slug is empty
  IF NEW.slug IS NULL OR NEW.slug = '' OR (TG_OP = 'UPDATE' AND OLD.business_name IS DISTINCT FROM NEW.business_name) THEN
    base_slug := lower(regexp_replace(trim(NEW.business_name), '[^a-zA-Z0-9]+', '-', 'g'));
    base_slug := trim(both '-' from base_slug);
    IF base_slug = '' THEN base_slug := 'merchant'; END IF;
    candidate := base_slug;
    WHILE EXISTS (
      SELECT 1 FROM merchants WHERE slug = candidate AND id IS DISTINCT FROM NEW.id
    ) LOOP
      candidate := base_slug || '-' || counter;
      counter := counter + 1;
    END LOOP;
    NEW.slug := candidate;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_check_customer_for_lead(p_lead_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id      UUID;
    v_caller_role    TEXT;
    v_lead           public.crm_leads%ROWTYPE;
    v_user           public.user_profiles%ROWTYPE;
    v_lead_phone_n   TEXT;
    v_user_phone_n   TEXT;
    v_existing_count INT := 0;
    v_recent_leads   JSONB := '[]'::jsonb;
BEGIN
    -- Auth: get calling user
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('error', 'Unauthorized');
    END IF;

    -- Auth: verify CRM-authorized role
    SELECT role::TEXT INTO v_caller_role
    FROM public.user_profiles
    WHERE id = v_caller_id;

    IF v_caller_role NOT IN ('relationship_exec', 'relationship_manager', 'admin', 'super_admin') THEN
        RETURN jsonb_build_object('error', 'Forbidden: insufficient role');
    END IF;

    -- Load lead
    SELECT * INTO v_lead FROM public.crm_leads WHERE id = p_lead_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'Lead not found');
    END IF;

    -- RBAC scope: exec can only check leads assigned to them
    IF v_caller_role = 'relationship_exec' AND v_lead.assigned_to IS DISTINCT FROM v_caller_id THEN
        RETURN jsonb_build_object('error', 'Forbidden: lead not assigned to you');
    END IF;

    -- Normalize lead phone for comparison
    v_lead_phone_n := public.normalize_in_phone(v_lead.phone);

    -- Search user_profiles by normalized phone (priority 1)
    IF v_lead_phone_n IS NOT NULL THEN
        SELECT * INTO v_user
        FROM public.user_profiles
        WHERE public.normalize_in_phone(phone) = v_lead_phone_n
          AND role = 'user'
        LIMIT 1;
    END IF;

    -- If phone miss, try email (skip pseudo phone emails)
    IF v_user.id IS NULL AND v_lead.email IS NOT NULL AND v_lead.email NOT LIKE '%@phone.intrust.internal' THEN
        SELECT * INTO v_user
        FROM public.user_profiles
        WHERE email = v_lead.email
          AND role = 'user'
          AND email NOT LIKE '%@phone.intrust.internal'
        LIMIT 1;
    END IF;

    IF v_user.id IS NULL THEN
        RETURN jsonb_build_object(
            'found', FALSE,
            'message', 'Customer account not found. The customer must have an InTrust account before this lead can be converted.'
        );
    END IF;

    -- Fetch existing CRM lead history for this customer
    SELECT count(*) INTO v_existing_count
    FROM public.crm_leads
    WHERE converted_user_id = v_user.id
      AND id <> p_lead_id;

    IF v_existing_count > 0 THEN
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', id,
                'status', status,
                'converted_at', converted_at
            )
        ), '[]'::jsonb) INTO v_recent_leads
        FROM (
            SELECT id, status, converted_at
            FROM public.crm_leads
            WHERE converted_user_id = v_user.id
              AND id <> p_lead_id
            ORDER BY converted_at DESC NULLS LAST
            LIMIT 3
        ) sub;
    END IF;

    RETURN jsonb_build_object(
        'found', TRUE,
        'user', jsonb_build_object(
            'id', v_user.id,
            'full_name', v_user.full_name,
            'phone', v_user.phone,
            'email', v_user.email,
            'kyc_status', v_user.kyc_status,
            'role', v_user.role
        ),
        'existing_leads_info', jsonb_build_object(
            'count', v_existing_count,
            'recent_leads', v_recent_leads
        )
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.warn_expiring_reward_points()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_config jsonb;
  v_expiry_days int;
  v_warn_days_before int;
  v_warn_cutoff timestamp;
  v_expiry_cutoff timestamp;
  v_warned_count int := 0;
  v_user_row record;
BEGIN
  -- Read config
  SELECT config_value INTO v_config 
  FROM public.reward_configuration 
  WHERE config_key = 'point_expiry';

  IF v_config IS NULL OR NOT (v_config->>'enabled')::boolean THEN
    RETURN jsonb_build_object('success', false, 'reason', 'disabled');
  END IF;

  v_expiry_days := (v_config->>'expiry_days')::int;
  v_warn_days_before := (v_config->>'warn_days_before')::int;

  -- Compute cutoffs
  v_warn_cutoff := now() - ((v_expiry_days - v_warn_days_before) || ' days')::INTERVAL;
  v_expiry_cutoff := now() - (v_expiry_days || ' days')::INTERVAL;

  -- Loop over qualifying users
  FOR v_user_row IN 
    SELECT user_id, current_balance 
    FROM public.reward_points_balance
    WHERE current_balance > 0 
    AND last_calculated_at < v_warn_cutoff
    AND last_calculated_at >= v_expiry_cutoff
  LOOP
    -- Idempotency guard: check if already warned today
    IF EXISTS (
      SELECT 1 FROM public.notifications
      WHERE user_id = v_user_row.user_id
      AND reference_type = 'reward_expiry_warning'
      AND created_at::date = CURRENT_DATE
    ) THEN
      CONTINUE;
    END IF;

    -- Send warning notification
    INSERT INTO public.notifications (
      user_id, 
      title, 
      body, 
      type, 
      reference_type
    ) VALUES (
      v_user_row.user_id,
      '⚠️ Reward Points Expiring Soon',
      v_user_row.current_balance || ' reward points will expire in ' || v_warn_days_before || ' days. Earn or redeem to keep them active.',
      'warning',
      'reward_expiry_warning'
    );

    v_warned_count := v_warned_count + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'warned_count', v_warned_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.settle_udhari_payment(p_udhari_request_id uuid, p_customer_user_id uuid, p_extra_fee_paise bigint, p_customer_email text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_udhari record;
  v_wallet record;
  v_coupon record;
  v_total_paise bigint;
  v_order_id uuid;
  v_merchant_new_balance bigint;
BEGIN
  SELECT * INTO v_udhari FROM udhari_requests WHERE id = p_udhari_request_id AND customer_id = p_customer_user_id AND status = 'approved' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'udhari_not_found'; END IF;

  SELECT * INTO v_wallet FROM customer_wallets WHERE user_id = p_customer_user_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'wallet_not_found'; END IF;

  v_total_paise := v_udhari.amount_paise + p_extra_fee_paise;
  IF v_wallet.balance_paise < v_total_paise THEN RAISE EXCEPTION 'insufficient_balance:%', v_wallet.balance_paise; END IF;

  SELECT * INTO v_coupon FROM coupons WHERE id = v_udhari.coupon_id AND status = 'reserved' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'coupon_not_reserved'; END IF;

  UPDATE customer_wallets SET balance_paise = balance_paise - v_total_paise WHERE id = v_wallet.id;

  SELECT wallet_balance_paise INTO v_merchant_new_balance FROM merchants WHERE id = v_udhari.merchant_id FOR UPDATE;
  v_merchant_new_balance := COALESCE(v_merchant_new_balance, 0) + v_total_paise;

  UPDATE merchants SET wallet_balance_paise = v_merchant_new_balance, updated_at = NOW() WHERE id = v_udhari.merchant_id;

  UPDATE coupons SET status = 'sold', purchased_by = p_customer_user_id, purchased_at = NOW() WHERE id = v_coupon.id;

  INSERT INTO orders (user_id, merchant_id, giftcard_id, amount, payment_status, created_at) VALUES (
    p_customer_user_id, v_udhari.merchant_id, v_coupon.id, v_total_paise, 'paid', NOW()
  ) RETURNING id INTO v_order_id;

  INSERT INTO customer_wallet_transactions (wallet_id, user_id, type, amount_paise, balance_before_paise, balance_after_paise, description, reference_id, reference_type) VALUES (
    v_wallet.id, p_customer_user_id, 'DEBIT', v_total_paise, v_wallet.balance_paise, v_wallet.balance_paise - v_total_paise,
    'Udhari Settlement: ' || COALESCE(v_coupon.brand, 'Gift Card') || ' - ' || COALESCE(v_coupon.title, '') || CASE WHEN p_extra_fee_paise > 0 THEN ' (incl. ₹' || (p_extra_fee_paise / 100.0)::numeric(10,2)::text || ' fee)' ELSE '' END,
    p_udhari_request_id, 'UDHARI_PAYMENT'
  );

  INSERT INTO merchant_transactions (merchant_id, transaction_type, amount_paise, commission_paise, balance_after_paise, description, metadata) VALUES (
    v_udhari.merchant_id, 'udhari_payment', v_total_paise, 0, v_merchant_new_balance,
    'Udhari Paid: ' || COALESCE(v_coupon.title, 'Gift Card') || COALESCE(' (Cust: ' || p_customer_email || ')', ''),
    jsonb_build_object('udhari_request_id', p_udhari_request_id, 'customer_id', p_customer_user_id, 'coupon_id', v_coupon.id)
  );

  UPDATE udhari_requests SET status = 'completed', completed_at = NOW() WHERE id = p_udhari_request_id;

  RETURN jsonb_build_object('success', true, 'order_id', v_order_id, 'new_balance_paise', v_wallet.balance_paise - v_total_paise);
END;
$function$

CREATE OR REPLACE FUNCTION public.team_get_user_subtree(p_user_id uuid)
 RETURNS TABLE(team_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
 DECLARE
     v_role TEXT;
     v_user_team_id UUID;
 BEGIN
     SELECT user_profiles.role::text, user_profiles.team_id INTO v_role, v_user_team_id
     FROM public.user_profiles WHERE user_profiles.id = p_user_id;

     IF v_role IN ('admin', 'super_admin') THEN
         RETURN QUERY SELECT t.id FROM public.teams t WHERE t.is_active = true;
     ELSIF v_role = 'relationship_manager' THEN
         RETURN QUERY 
         WITH RECURSIVE manager_teams AS (
             -- Base case: teams led by user OR team user belongs to
             SELECT id FROM public.teams 
             WHERE is_active = true AND (team_lead_id = p_user_id OR id = v_user_team_id)
             UNION
             -- Recursive case: active children of manager teams
             SELECT child.id FROM public.teams child
             INNER JOIN manager_teams parent ON child.parent_team_id = parent.id
             WHERE child.is_active = true
         )
         SELECT DISTINCT id FROM manager_teams;
     ELSIF v_role = 'relationship_exec' THEN
         IF v_user_team_id IS NOT NULL THEN
             RETURN QUERY SELECT t.id FROM public.teams t WHERE t.id = v_user_team_id AND t.is_active = true;
         END IF;
     END IF;
     RETURN;
 END;
 $function$

CREATE OR REPLACE FUNCTION public.create_notification(p_user_id uuid, p_title text, p_body text, p_type text, p_priority text, p_action_url text, p_reference_type text, p_reference_id uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_recent_count INT;
BEGIN
    -- Prevent duplicate if idempotency_key is provided
    IF p_idempotency_key IS NOT NULL THEN
        SELECT count(*) INTO v_recent_count
        FROM public.notifications
        WHERE user_id = p_user_id
          AND reference_id = p_reference_id
          AND reference_type = p_reference_type
          AND metadata->>'idempotency_key' = p_idempotency_key;

        IF v_recent_count > 0 THEN
            RETURN;
        END IF;
    ELSE
        -- Time-based duplicate prevention (e.g. within last 1 hour for same event type)
        SELECT count(*) INTO v_recent_count
        FROM public.notifications
        WHERE user_id = p_user_id
          AND reference_id = p_reference_id
          AND reference_type = p_reference_type
          AND created_at > (NOW() - INTERVAL '1 hour');

        IF v_recent_count > 0 THEN
            RETURN;
        END IF;
    END IF;

    -- Insert notification
    INSERT INTO public.notifications (
        user_id, title, body, type, priority, action_url, reference_type, reference_id, metadata
    ) VALUES (
        p_user_id, p_title, p_body, COALESCE(p_type, 'info'), COALESCE(p_priority, 'NORMAL'), p_action_url, p_reference_type, p_reference_id, 
        CASE WHEN p_idempotency_key IS NOT NULL THEN jsonb_build_object('idempotency_key', p_idempotency_key) ELSE NULL END
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.merchant_reject_udhari_request(p_request_id uuid, p_merchant_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_request record;
    v_group   record;
BEGIN
    -- 1. Lock udhari_requests row
    SELECT * INTO v_request
    FROM udhari_requests
    WHERE id = p_request_id
    FOR UPDATE;

    IF v_request IS NULL THEN
        RAISE EXCEPTION 'Udhari request % not found', p_request_id;
    END IF;

    IF v_request.status != 'pending' THEN
        RAISE EXCEPTION 'Udhari request is not in pending status (current: %)', v_request.status;
    END IF;

    -- 2. Revert order-group state if this was a shop_order
    IF v_request.source_type = 'shop_order' AND v_request.shopping_order_group_id IS NOT NULL THEN
        SELECT * INTO v_group
        FROM shopping_order_groups
        WHERE id = v_request.shopping_order_group_id
        FOR UPDATE;

        IF v_group IS NOT NULL THEN
            UPDATE shopping_order_groups
            SET payment_method   = NULL,
                delivery_status  = 'pending'
            WHERE id = v_request.shopping_order_group_id;
        END IF;
    END IF;

    -- gift_card: coupon was never reserved on a pending request, so no revert needed.

    -- 3. Mark udhari request as denied
    UPDATE udhari_requests
    SET status        = 'denied',
        merchant_note = p_merchant_note,
        responded_at  = NOW()
    WHERE id = p_request_id;

    RETURN jsonb_build_object('success', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.crm_check_merchant_for_lead(p_lead_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id      UUID;
    v_caller_role    TEXT;
    v_lead           public.crm_leads%ROWTYPE;
    v_merchant       public.merchants%ROWTYPE;
    v_lead_phone_n   TEXT;
    v_biz_phone_n    TEXT;
    v_existing_count INT := 0;
    v_recent_leads   JSONB := '[]'::jsonb;
BEGIN
    -- Auth: get calling user
    v_caller_id := auth.uid();
    IF v_caller_id IS NULL THEN
        RETURN jsonb_build_object('error', 'Unauthorized');
    END IF;

    -- Auth: verify CRM-authorized role
    SELECT role::TEXT INTO v_caller_role
    FROM public.user_profiles
    WHERE id = v_caller_id;

    IF v_caller_role NOT IN ('relationship_exec', 'relationship_manager', 'admin', 'super_admin') THEN
        RETURN jsonb_build_object('error', 'Forbidden: insufficient role');
    END IF;

    -- Load lead
    SELECT * INTO v_lead FROM public.crm_leads WHERE id = p_lead_id;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'Lead not found');
    END IF;

    -- RBAC scope: exec can only check leads assigned to them
    IF v_caller_role = 'relationship_exec' AND v_lead.assigned_to IS DISTINCT FROM v_caller_id THEN
        RETURN jsonb_build_object('error', 'Forbidden: lead not assigned to you');
    END IF;

    -- Normalize lead phone
    v_lead_phone_n := public.normalize_in_phone(v_lead.phone);

    -- Priority 1: match on normalized business_phone
    IF v_lead_phone_n IS NOT NULL THEN
        SELECT m.* INTO v_merchant
        FROM public.merchants m
        WHERE public.normalize_in_phone(m.business_phone) = v_lead_phone_n
        LIMIT 1;
    END IF;

    -- Priority 2: match on business_email
    IF v_merchant.id IS NULL AND v_lead.email IS NOT NULL AND v_lead.email NOT LIKE '%@phone.intrust.internal' THEN
        SELECT m.* INTO v_merchant
        FROM public.merchants m
        WHERE m.business_email = v_lead.email
        LIMIT 1;
    END IF;

    -- Priority 3: match via owner's user_profiles phone/email
    IF v_merchant.id IS NULL THEN
        SELECT m.* INTO v_merchant
        FROM public.merchants m
        JOIN public.user_profiles up ON up.id = m.user_id
        WHERE (
            (v_lead_phone_n IS NOT NULL AND public.normalize_in_phone(up.phone) = v_lead_phone_n)
            OR
            (v_lead.email IS NOT NULL AND v_lead.email NOT LIKE '%@phone.intrust.internal' AND up.email = v_lead.email)
        )
        LIMIT 1;
    END IF;

    IF v_merchant.id IS NULL THEN
        RETURN jsonb_build_object(
            'found', FALSE,
            'message', 'Merchant account not found. Please complete merchant onboarding before converting this lead.'
        );
    END IF;

    -- Fetch existing CRM lead history for this merchant
    SELECT count(*) INTO v_existing_count
    FROM public.crm_leads
    WHERE converted_merchant_id = v_merchant.id
      AND id <> p_lead_id;

    IF v_existing_count > 0 THEN
        SELECT COALESCE(jsonb_agg(
            jsonb_build_object(
                'id', id,
                'status', status,
                'converted_at', converted_at
            )
        ), '[]'::jsonb) INTO v_recent_leads
        FROM (
            SELECT id, status, converted_at
            FROM public.crm_leads
            WHERE converted_merchant_id = v_merchant.id
              AND id <> p_lead_id
            ORDER BY converted_at DESC NULLS LAST
            LIMIT 3
        ) sub;
    END IF;

    RETURN jsonb_build_object(
        'found', TRUE,
        'merchant', jsonb_build_object(
            'id', v_merchant.id,
            'business_name', v_merchant.business_name,
            'business_phone', v_merchant.business_phone,
            'business_email', v_merchant.business_email,
            'status', v_merchant.status,
            'owner_name', v_merchant.owner_name
        ),
        'existing_leads_info', jsonb_build_object(
            'count', v_existing_count,
            'recent_leads', v_recent_leads
        )
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_unsuspend_user(p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
 DECLARE
     v_admin_id UUID;
     v_admin_role user_role;
 BEGIN
     v_admin_id := auth.uid();

     -- Check admin role
     SELECT role INTO v_admin_role
     FROM public.user_profiles
     WHERE id = v_admin_id;

     IF v_admin_role NOT IN ('admin', 'super_admin') THEN
         RAISE EXCEPTION 'Only admins can unsuspend users';
     END IF;

     -- Unsuspend user
     UPDATE public.user_profiles
     SET 
         is_suspended = FALSE,
         suspension_reason = NULL,
         updated_at = NOW()
     WHERE id = p_user_id;

     -- Log the action
     INSERT INTO public.audit_logs (
         actor_id, actor_role, action, entity_type, entity_id,
         description, metadata
     ) VALUES (
         v_admin_id, v_admin_role, 'user_reactivated', 'user', p_user_id,
         'User unsuspended',
         jsonb_build_object()
     );

     RETURN jsonb_build_object('success', true);
 END;
$function$

CREATE OR REPLACE FUNCTION public.admin_insert_shopping_product(p_title text, p_description text, p_category text, p_category_id uuid, p_wholesale_price bigint, p_retail_price bigint, p_mrp_paise bigint, p_admin_stock integer, p_product_images text[], p_is_active boolean DEFAULT false, p_gst_percentage integer DEFAULT 0, p_hsn_code text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_product_id UUID;
    v_admin_role TEXT;
BEGIN
    -- Check from profiles table
    SELECT role INTO v_admin_role
    FROM public.profiles
    WHERE id = auth.uid();

    IF v_admin_role IS NULL OR v_admin_role != 'admin' THEN
        -- Fallback to user_profiles
        SELECT role INTO v_admin_role
        FROM public.user_profiles
        WHERE id = auth.uid();

        IF v_admin_role IS NULL OR v_admin_role != 'admin' THEN
            RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin role required');
        END IF;
    END IF;

    INSERT INTO public.shopping_products (
        title, description, category, category_id, wholesale_price_paise, suggested_retail_price_paise,
        mrp_paise, admin_stock, product_images, is_active, gst_percentage, hsn_code
    ) VALUES (
        p_title, p_description, p_category, p_category_id, p_wholesale_price, p_retail_price,
        p_mrp_paise, p_admin_stock, p_product_images, p_is_active, p_gst_percentage, p_hsn_code
    )
    RETURNING id INTO v_product_id;

    RETURN jsonb_build_object('success', true, 'id', v_product_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_takeover_stale_orders()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_stale_order RECORD;
    v_count INT := 0;
    v_new_platform_cut BIGINT;
    v_new_merchant_profit BIGINT;
    v_total_product_value BIGINT;
    v_total_cost_price BIGINT;
    v_total_profit BIGINT;
BEGIN
    FOR v_stale_order IN 
        SELECT sog.*, m.user_id as merchant_user_id
        FROM public.shopping_order_groups sog
        JOIN public.merchants m ON sog.merchant_id = m.id
        WHERE sog.delivery_status = 'pending'
          AND sog.settlement_status = 'pending'
          AND sog.is_platform_order = false
          AND sog.payment_status IN ('paid', 'pending')
          AND sog.created_at < NOW() - INTERVAL '2 hours'
          AND sog.merchant_id IS NOT NULL
    LOOP
        v_total_product_value := v_stale_order.total_amount_paise - COALESCE(v_stale_order.delivery_fee_paise, 0);

        SELECT COALESCE(SUM(p.wholesale_price_paise * i.quantity), 0)
        INTO v_total_cost_price
        FROM public.shopping_order_items i
        JOIN public.shopping_products p ON i.product_id = p.id
        WHERE i.group_id = v_stale_order.id;

        v_total_profit := GREATEST(0, v_total_product_value - v_total_cost_price);
        v_new_platform_cut := ROUND(v_total_profit * 70 / 100);
        v_new_merchant_profit := v_total_product_value - v_new_platform_cut;

        UPDATE public.shopping_order_groups
        SET commission_rate = 0.30,
            platform_cut_paise = v_new_platform_cut,
            merchant_profit_paise = v_new_merchant_profit,
            assigned_to = NULL,
            admin_takeover_at = NOW(),
            settlement_status = 'admin_takeover'
        WHERE id = v_stale_order.id;

        UPDATE public.shopping_order_items soi
        SET commission_amount_paise = GREATEST(0, (soi.unit_price_paise - COALESCE(p.wholesale_price_paise, 0))) * soi.quantity * 70 / 100,
            profit_paise = (soi.unit_price_paise * soi.quantity)
                           - GREATEST(0, (soi.unit_price_paise - COALESCE(p.wholesale_price_paise, 0))) * soi.quantity * 70 / 100
                           - (COALESCE(p.wholesale_price_paise, 0) * soi.quantity)
        FROM public.shopping_products p
        WHERE soi.product_id = p.id
          AND soi.group_id = v_stale_order.id;

        UPDATE public.merchants
        SET wallet_balance_paise = COALESCE(wallet_balance_paise, 0) + v_new_merchant_profit,
            total_commission_paid_paise = COALESCE(total_commission_paid_paise, 0) + v_new_platform_cut
        WHERE id = v_stale_order.merchant_id;

        UPDATE public.merchants
        SET fulfillment_failure_count = fulfillment_failure_count + 1
        WHERE id = v_stale_order.merchant_id;

        INSERT INTO public.merchant_transactions (
           merchant_id, transaction_type, amount_paise, commission_paise, balance_after_paise, description
        ) VALUES (
           v_stale_order.merchant_id, 'sale', v_new_merchant_profit, v_new_platform_cut,
           (SELECT wallet_balance_paise FROM public.merchants WHERE id = v_stale_order.merchant_id),
           'Order auto-escalated to admin — merchant did not respond within 2 hours. Commission reduced to 30%.'
        );

        INSERT INTO public.notifications (user_id, title, body, type, reference_id, reference_type)
        VALUES (
            v_stale_order.merchant_user_id, 
            'Order Reassigned ⚠️', 
            'Order #' || substring(v_stale_order.id::text from 1 for 8) || ' was reassigned to admin due to inactivity. Your commission reduced to 30%.', 
            'warning', 
            v_stale_order.id, 
            'shopping_order'
        );

        INSERT INTO public.notifications (user_id, title, body, type, reference_id, reference_type)
        SELECT id, 'Order Takeover 📋', 'Order #' || substring(v_stale_order.id::text from 1 for 8) || ' auto-transferred. Merchant did not respond within 2 hours.', 'info', v_stale_order.id, 'shopping_order'
        FROM public.user_profiles
        WHERE role IN ('admin', 'super_admin');

        v_count := v_count + 1;
    END LOOP;

    RETURN jsonb_build_object('success', true, 'orders_transferred', v_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.atomic_customer_wallet_credit(p_user_id uuid, p_amount_paise bigint, p_type text, p_description text, p_reference_id text, p_reference_type text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_wallet_id      UUID;
    v_balance_before BIGINT;
    v_balance_after  BIGINT;
    v_tx_id          UUID;
BEGIN
    -- ── SECURITY CHECK: Reject direct calls from authenticated users ───────────
    -- This function is designed to be called ONLY by server-side service role
    -- code (Next.js API routes, payment callbacks) or by other SECURITY DEFINER
    -- functions internally. If auth.uid() is non-null, it means an authenticated
    -- user is calling this directly via supabase.rpc() — which is unauthorized.
    --
    -- Legitimate callers (service_role, other SECURITY DEFINER functions) will
    -- have auth.uid() = NULL in the database session context.
    IF auth.uid() IS NOT NULL THEN
        RAISE EXCEPTION 'atomic_customer_wallet_credit: Direct user invocation is not permitted. Use server-side API routes.'
            USING ERRCODE = 'insufficient_privilege';
    END IF;

    -- ── Input validation ───────────────────────────────────────────────────────
    IF p_user_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'p_user_id is required');
    END IF;

    IF p_amount_paise IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'p_amount_paise is required');
    END IF;

    -- 1. Ensure wallet exists and lock it for update
    INSERT INTO public.customer_wallets (user_id, balance_paise, status)
    VALUES (p_user_id, 0, 'ACTIVE')
    ON CONFLICT (user_id) DO NOTHING;

    SELECT id, balance_paise INTO v_wallet_id, v_balance_before
    FROM public.customer_wallets
    WHERE user_id = p_user_id
    FOR UPDATE;

    IF v_wallet_id IS NULL THEN
        RETURN json_build_object('success', false, 'message', 'Wallet not found for user');
    END IF;

    -- 2. Calculate new balance
    v_balance_after := v_balance_before + p_amount_paise;

    -- Guard against negative balance (for debit operations)
    IF v_balance_after < 0 THEN
        RETURN json_build_object(
            'success', false,
            'message', 'Insufficient wallet balance',
            'balance_before', v_balance_before,
            'attempted_debit', p_amount_paise
        );
    END IF;

    -- 3. Update wallet and insert transaction inside a nested block
    -- This ensures that if the unique constraint (e.g. for TOPUPs) fires,
    -- the balance update is atomically rolled back with the insert.
    BEGIN
        UPDATE public.customer_wallets
        SET balance_paise = v_balance_after, updated_at = now()
        WHERE id = v_wallet_id;

        INSERT INTO public.customer_wallet_transactions (
            wallet_id, user_id, type, amount_paise,
            balance_before_paise, balance_after_paise,
            description, reference_id, reference_type
        ) VALUES (
            v_wallet_id, p_user_id, p_type, p_amount_paise,
            v_balance_before, v_balance_after,
            p_description, p_reference_id, p_reference_type
        ) RETURNING id INTO v_tx_id;

    EXCEPTION WHEN unique_violation THEN
        -- Rollback occurs for the nested block only (wallet update and tx insert)
        RETURN json_build_object('success', false, 'duplicate', true, 'message', 'Unique constraint violation');
    END;

    RETURN json_build_object(
        'success', true,
        'duplicate', false,
        'wallet_id', v_wallet_id,
        'transaction_id', v_tx_id,
        'balance_after_paise', v_balance_after
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.admin_approve_payout(p_payout_request_id uuid, p_admin_user_id uuid, p_admin_note text DEFAULT NULL::text, p_utr_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_payout  record;
    v_balance bigint;
    v_actual_admin_id uuid;
    v_admin_role text;
BEGIN
    -- 1. Securely derive the caller identity
    v_actual_admin_id := auth.uid();

    IF v_actual_admin_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
    END IF;

    -- Verify the caller has an admin role
    SELECT role::text INTO v_admin_role
    FROM public.user_profiles
    WHERE id = v_actual_admin_id;

    IF v_admin_role NOT IN ('admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Admin access required');
    END IF;

    -- 2. Lock payout row
    SELECT * INTO v_payout
    FROM payout_requests
    WHERE id = p_payout_request_id
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'Payout request not found');
    END IF;

    -- 3. Guard: must be in 'approved' state
    IF v_payout.status != 'approved' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Payout is not in approved state: ' || v_payout.status);
    END IF;

    -- 4. Update payout status
    UPDATE payout_requests
    SET status        = 'released',
        reviewed_by   = v_actual_admin_id, -- SECURE: Use derived ID
        reviewed_at   = now(),
        admin_note    = COALESCE(p_admin_note, admin_note),
        utr_reference = COALESCE(p_utr_reference, utr_reference)
    WHERE id = p_payout_request_id;

    -- 5. If growth fund, mark contract paid_out atomically
    IF v_payout.payout_source = 'growth_fund' AND v_payout.reference_id IS NOT NULL THEN
        UPDATE merchant_lockin_balances
        SET status = 'paid_out'
        WHERE id = v_payout.reference_id;
    END IF;

    -- 6. Read current (already pre-debited) wallet balance for ledger
    SELECT wallet_balance_paise INTO v_balance
    FROM merchants
    WHERE id = v_payout.merchant_id;

    -- 7. Insert merchant_transactions ledger entry
    INSERT INTO merchant_transactions (
        merchant_id,
        transaction_type,
        amount_paise,
        balance_after_paise,
        description
    ) VALUES (
        v_payout.merchant_id,
        'payout',
        v_payout.amount_paise,
        v_balance,
        'Payout released: ₹' || to_char(v_payout.amount_paise::numeric / 100, 'FM99,99,99,990.00')
    );

    -- 8. Audit event
    INSERT INTO payout_request_events (
        payout_id, actor_id, action, from_status, to_status, payload
    ) VALUES (
        p_payout_request_id, v_actual_admin_id, 'released', 'approved', 'released', -- SECURE: Use derived ID
        jsonb_build_object(
            'utr_reference', p_utr_reference,
            'admin_note',    p_admin_note
        )
    );

    RETURN jsonb_build_object('success', true);

EXCEPTION WHEN OTHERS THEN
    RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.user_profiles_block_sensitive_column_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    -- Allow service_role or postgres to bypass checks
    IF current_setting('role', true) = 'service_role' OR current_user = 'postgres' THEN
        RETURN NEW;
    END IF;

    -- Only allow admins/super_admins or hr_managers (for HR-specific columns)
    -- to change sensitive columns
    IF NOT EXISTS (
        SELECT 1 FROM public.user_profiles
        WHERE id = auth.uid() AND role IN ('admin', 'super_admin')
    ) THEN
        -- Block ALL users (including HR managers via client-side RPC)
        -- from modifying these security-sensitive columns.
        -- Admins must use the admin_update_user_role RPC for role changes.
        NEW.role := OLD.role;
        NEW.kyc_status := OLD.kyc_status;
        NEW.is_suspended := OLD.is_suspended;
        NEW.suspension_reason := OLD.suspension_reason;
        NEW.is_gold_verified := OLD.is_gold_verified;
        NEW.subscription_expiry := OLD.subscription_expiry;
        NEW.total_reward_points_earned := OLD.total_reward_points_earned;
        NEW.reward_parent_id := OLD.reward_parent_id;
        NEW.tree_depth := OLD.tree_depth;
        NEW.reward_tier := OLD.reward_tier;
        NEW.failed_login_attempts := OLD.failed_login_attempts;
        NEW.locked_until := OLD.locked_until;
        NEW.team_id := OLD.team_id;
        NEW.reporting_manager_id := OLD.reporting_manager_id;
        -- NEWLY PROTECTED:
        NEW.is_active := OLD.is_active;        -- Account activation status
        NEW.employee_number := OLD.employee_number;  -- HR identifier
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.award_individual_incentive(p_employee_id uuid, p_incentive_type text, p_amount_paise bigint, p_description text DEFAULT NULL::text, p_internal_note text DEFAULT NULL::text, p_effective_date date DEFAULT CURRENT_DATE, p_payroll_month integer DEFAULT NULL::integer, p_payroll_year integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text, p_caller_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_actor_id UUID;
    v_actor_role TEXT;
    v_actor_name TEXT;
    v_emp_name TEXT;
    v_emp_code TEXT;
    v_emp_role TEXT;
    v_emp_suspended BOOLEAN;
    v_existing_batch_id UUID;
    v_batch_id UUID;
    v_allocation_id UUID;
BEGIN
    -- Derive caller
    v_actor_id := COALESCE(p_caller_id, auth.uid());
    IF v_actor_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'UNAUTHORIZED', 'error', 'Authentication required');
    END IF;

    SELECT role::text, full_name INTO v_actor_role, v_actor_name
    FROM public.user_profiles
    WHERE id = v_actor_id;

    IF v_actor_role NOT IN ('hr_manager', 'admin', 'super_admin') THEN
        RETURN jsonb_build_object('success', false, 'code', 'FORBIDDEN', 'error', 'HR permissions required');
    END IF;

    -- Idempotency check
    IF p_idempotency_key IS NOT NULL THEN
        SELECT id INTO v_existing_batch_id
        FROM public.incentive_batches
        WHERE created_by = v_actor_id AND idempotency_key = p_idempotency_key;

        IF v_existing_batch_id IS NOT NULL THEN
            RETURN jsonb_build_object('success', true, 'code', 'DUPLICATE_IDEMPOTENT', 'batch_id', v_existing_batch_id);
        END IF;
    END IF;

    -- Validate employee
    SELECT full_name, employee_id, role::text, is_suspended INTO v_emp_name, v_emp_code, v_emp_role, v_emp_suspended
    FROM public.user_profiles
    WHERE id = p_employee_id;

    IF v_emp_name IS NULL THEN
        RETURN jsonb_build_object('success', false, 'code', 'EMPLOYEE_NOT_FOUND', 'error', 'Target employee does not exist');
    END IF;

    IF v_emp_suspended THEN
        RETURN jsonb_build_object('success', false, 'code', 'EMPLOYEE_INACTIVE', 'error', 'Cannot award incentive to suspended employee');
    END IF;

    -- Validate amount
    IF p_amount_paise <= 0 OR p_amount_paise > 1000000000 THEN -- Max 1 Crore INR (10,000,000 RS)
        RETURN jsonb_build_object('success', false, 'code', 'AMOUNT_OUT_OF_RANGE', 'error', 'Amount out of allowed policy range');
    END IF;

    -- Validate type
    IF p_incentive_type NOT IN ('performance_bonus', 'referral_bonus', 'festival_bonus', 'spot_award', 'retention_bonus', 'other') THEN
        RETURN jsonb_build_object('success', false, 'code', 'INVALID_TYPE', 'error', 'Unknown incentive type');
    END IF;

    -- Create Batch & Allocation
    INSERT INTO public.incentive_batches (
        recipient_mode, allocation_mode, incentive_type, description, internal_note,
        effective_date, payroll_month, payroll_year, total_amount_paise, per_person_amount_paise,
        eligible_member_count, excluded_member_count, status, created_by, idempotency_key
    ) VALUES (
        'individual', 'per_person', p_incentive_type, p_description, p_internal_note,
        COALESCE(p_effective_date, CURRENT_DATE), p_payroll_month, p_payroll_year, p_amount_paise, p_amount_paise,
        1, 0, 'pending', v_actor_id, p_idempotency_key
    )
    RETURNING id INTO v_batch_id;

    INSERT INTO public.incentive_allocations (
        batch_id, employee_id, employee_name_snapshot, employee_code_snapshot,
        amount_paise, status
    ) VALUES (
        v_batch_id, p_employee_id, v_emp_name, v_emp_code,
        p_amount_paise, 'pending'
    )
    RETURNING id INTO v_allocation_id;

    -- Write Audit Log
    INSERT INTO public.audit_logs_hrm (
        actor_id, actor_name, action, table_name, record_id,
        new_data, module, severity
    ) VALUES (
        v_actor_id, COALESCE(v_actor_name, 'HR Manager'), 'CREATE_INDIVIDUAL_INCENTIVE', 'incentive_batches', v_batch_id,
        jsonb_build_object('batch_id', v_batch_id, 'employee_id', p_employee_id, 'amount_paise', p_amount_paise, 'type', p_incentive_type),
        'Incentives', 'medium'
    );

    -- Create Notification for Employee
    INSERT INTO public.notifications (
        user_id, title, body, type, reference_id, reference_type
    ) VALUES (
        p_employee_id, 'New Incentive Awarded',
        format('You have been awarded a new incentive of ₹%s (%s).', (p_amount_paise::numeric / 100.0)::text, p_incentive_type),
        'info', v_batch_id, 'incentive_batch'
    );

    RETURN jsonb_build_object('success', true, 'batch_id', v_batch_id, 'allocation_id', v_allocation_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.update_solar_leads_mod_time()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    IF NEW.status IS DISTINCT FROM OLD.status THEN
        NEW.status_updated_at = now();
    END IF;
    NEW.version = OLD.version + 1;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.finalize_wholesale_gateway_purchase(p_draft_id uuid, p_amount_paise bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_draft            RECORD;
    v_item             JSONB;
    v_product_id       UUID;
    v_quantity         INT;
    v_unit_price       BIGINT;
    v_merchant_user_id UUID;
    v_batch_id         UUID := gen_random_uuid();
BEGIN
    SELECT * INTO v_draft FROM public.wholesale_order_drafts
    WHERE id = p_draft_id AND status = 'pending'
    FOR UPDATE;

    IF v_draft.id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'message', 'Draft not found or already processed');
    END IF;

    IF v_draft.total_amount_paise != p_amount_paise THEN
        RETURN jsonb_build_object('success', false, 'message', 'Amount mismatch during fulfillment');
    END IF;

    SELECT user_id INTO v_merchant_user_id FROM public.merchants WHERE id = v_draft.merchant_id;

    FOR v_item IN SELECT unnest(v_draft.items)
    LOOP
        v_product_id := (v_item->>'product_id')::UUID;
        v_quantity   := (v_item->>'quantity')::INT;
        v_unit_price := (v_item->>'unit_price_paise')::BIGINT;

        IF NOT EXISTS (
            SELECT 1 FROM public.shopping_products
            WHERE id = v_product_id AND admin_stock >= v_quantity
        ) THEN
            RETURN jsonb_build_object('success', false, 'message', 'Stock ran out for one or more items since draft creation');
        END IF;

        UPDATE public.shopping_products
        SET admin_stock = admin_stock - v_quantity,
            updated_at  = now()
        WHERE id = v_product_id;

        INSERT INTO public.merchant_inventory (
            merchant_id, product_id, stock_quantity, retail_price_paise, updated_at, is_platform_product
        ) VALUES (
            v_draft.merchant_id, v_product_id, v_quantity,
            (SELECT suggested_retail_price_paise FROM public.shopping_products WHERE id = v_product_id),
            now(), true
        )
        ON CONFLICT (merchant_id, product_id) DO UPDATE SET
            stock_quantity      = public.merchant_inventory.stock_quantity + v_quantity,
            retail_price_paise  = EXCLUDED.retail_price_paise,
            is_platform_product = true,
            updated_at          = now();

        INSERT INTO public.shopping_orders (
            buyer_id, buyer_type, seller_id, seller_type,
            product_id, quantity, unit_price_paise, total_price_paise,
            order_type, status, purchase_batch_id
        ) VALUES (
            v_draft.merchant_id, 'merchant', NULL, 'admin',
            v_product_id, v_quantity, v_unit_price, v_quantity * v_unit_price,
            'wholesale', 'completed', v_batch_id
        );
    END LOOP;

    INSERT INTO public.merchant_transactions (
        merchant_id, transaction_type, amount_paise, balance_after_paise,
        description, purchase_batch_id
    ) VALUES (
        v_draft.merchant_id, 'purchase', p_amount_paise,
        (SELECT wallet_balance_paise FROM public.merchants WHERE id = v_draft.merchant_id),
        'Wholesale Inventory Purchase via Gateway (Admin Stock)',
        v_batch_id
    );

    UPDATE public.wholesale_order_drafts
    SET status = 'completed', purchase_batch_id = v_batch_id, updated_at = now()
    WHERE id = p_draft_id;

    RETURN jsonb_build_object('success', true, 'batch_id', v_batch_id);
END;
$function$

CREATE OR REPLACE FUNCTION public.buy_coupon_merchant(p_user_id uuid, p_coupon_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_merchant_id uuid;
  v_balance bigint;
  v_price bigint;
  v_coupon_status text;
BEGIN
  -- 1. Get merchant details and lock for update
  SELECT id, wallet_balance_paise INTO v_merchant_id, v_balance
  FROM merchants
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Merchant profile not found');
  END IF;

  -- 2. Get coupon details and lock for update
  -- Ensure it's not already owned by a merchant
  SELECT selling_price_paise, status INTO v_price, v_coupon_status
  FROM coupons
  WHERE id = p_coupon_id AND merchant_id IS NULL
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Coupon not available or already purchased');
  END IF;

  -- 3. Check balance
  IF v_balance < v_price THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient wallet balance');
  END IF;

  -- 4. Deduct balance
  UPDATE merchants
  SET wallet_balance_paise = wallet_balance_paise - v_price,
      updated_at = now()
  WHERE id = v_merchant_id;

  -- 5. Update coupon ownership
  UPDATE coupons
  SET merchant_id = v_merchant_id,
      purchased_by_merchant_at = now()
  WHERE id = p_coupon_id;

  RETURN jsonb_build_object('success', true, 'message', 'Coupon purchased successfully');
END;
$function$

CREATE OR REPLACE FUNCTION public.expire_stale_reward_points()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_config jsonb;
  v_enabled boolean;
  v_expiry_days int;
  v_cutoff timestamp;
  v_expired_count int := 0;
  v_user_row record;
  v_points_to_expire bigint;
BEGIN
  -- Read config
  SELECT config_value INTO v_config 
  FROM public.reward_configuration 
  WHERE config_key = 'point_expiry';

  IF v_config IS NULL OR NOT (v_config->>'enabled')::boolean THEN
    RETURN jsonb_build_object('success', false, 'reason', 'disabled');
  END IF;

  v_expiry_days := (v_config->>'expiry_days')::int;

  -- Compute cutoff
  v_cutoff := now() - (v_expiry_days || ' days')::INTERVAL;

  -- Loop over qualifying balances
  FOR v_user_row IN 
    SELECT user_id, current_balance 
    FROM public.reward_points_balance
    WHERE current_balance > 0 
    AND last_calculated_at < v_cutoff
  LOOP
    -- Idempotency guard: check if already expired today
    IF EXISTS (
      SELECT 1 FROM public.reward_transactions
      WHERE user_id = v_user_row.user_id
      AND event_type = 'expiry'
      AND created_at::date = CURRENT_DATE
    ) THEN
      CONTINUE;
    END IF;

    v_points_to_expire := v_user_row.current_balance;

    -- Insert expiry transaction
    INSERT INTO public.reward_transactions (
      user_id, 
      event_type, 
      points, 
      points_before, 
      points_after, 
      description
    ) VALUES (
      v_user_row.user_id,
      'expiry',
      -v_points_to_expire,
      v_user_row.current_balance,
      0,
      'Points expired due to inactivity'
    );

    -- Update balance (do not touch last_calculated_at as expiry is not activity)
    UPDATE public.reward_points_balance
    SET 
      current_balance = 0,
      updated_at = now()
    WHERE user_id = v_user_row.user_id;

    -- Send notification
    INSERT INTO public.notifications (
      user_id, 
      title, 
      body, 
      type, 
      reference_type
    ) VALUES (
      v_user_row.user_id,
      '⏰ Reward Points Expired',
      v_points_to_expire || ' reward points have expired due to inactivity.',
      'warning',
      'reward_expiry'
    );

    v_expired_count := v_expired_count + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'expired_count', v_expired_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.calculate_leave_days_breakdown(p_from_date date, p_to_date date, p_employee_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
    v_curr_date date;
    v_cal_days int := 0;
    v_weekend_days int := 0;
    v_holiday_days int := 0;
    v_chargeable_days int := 0;
    v_day_of_week int;
    v_holiday_name text;
    v_holidays_json jsonb := '[]'::jsonb;
    v_weekends_json jsonb := '[]'::jsonb;
BEGIN
    IF p_to_date < p_from_date THEN
        RAISE EXCEPTION 'End date must be greater than or equal to start date.';
    END IF;

    v_curr_date := p_from_date;
    WHILE v_curr_date <= p_to_date LOOP
        v_cal_days := v_cal_days + 1;
        v_day_of_week := EXTRACT(DOW FROM v_curr_date)::int; -- 0=Sunday, 6=Saturday

        -- Check holiday
        SELECT name INTO v_holiday_name 
        FROM public.holidays 
        WHERE holiday_date = v_curr_date AND scope IN ('all', 'employee') AND is_optional = false
        LIMIT 1;

        IF v_holiday_name IS NOT NULL THEN
            v_holiday_days := v_holiday_days + 1;
            v_holidays_json := v_holidays_json || jsonb_build_object('date', v_curr_date, 'name', v_holiday_name);
        ELSIF v_day_of_week = 0 OR v_day_of_week = 6 THEN
            v_weekend_days := v_weekend_days + 1;
            v_weekends_json := v_weekends_json || jsonb_build_object('date', v_curr_date, 'day', TRIM(TO_CHAR(v_curr_date, 'Day')));
        ELSE
            v_chargeable_days := v_chargeable_days + 1;
        END IF;

        v_curr_date := v_curr_date + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'calendar_days', v_cal_days,
        'weekend_days', v_weekend_days,
        'holiday_days', v_holiday_days,
        'chargeable_days', v_chargeable_days,
        'holidays', v_holidays_json,
        'weekends', v_weekends_json
    );
END;
$function$

CREATE OR REPLACE FUNCTION public.create_wholesale_draft(p_merchant_id uuid, p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_item record;
    v_product record;
    v_total_paise bigint := 0;
    v_base_paise bigint;
    v_gst_paise bigint;
    v_validated_items jsonb[] := '{}';
    v_draft_id uuid;
BEGIN
    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_items) AS x(product_id uuid, quantity int)
    LOOP
        SELECT * INTO v_product
        FROM shopping_products
        WHERE id = v_item.product_id
        FOR UPDATE;

        IF v_product IS NULL THEN
            RAISE EXCEPTION 'Product not found: %', v_item.product_id;
        END IF;

        IF v_product.admin_stock < v_item.quantity THEN
            RAISE EXCEPTION 'Insufficient stock for %', v_product.title;
        END IF;

        v_base_paise := v_product.wholesale_price_paise * v_item.quantity;
        v_gst_paise := ROUND(v_base_paise * COALESCE(v_product.gst_percentage, 0) / 100.0);
        v_total_paise := v_total_paise + v_base_paise + v_gst_paise;

        v_validated_items := array_append(v_validated_items, jsonb_build_object(
            'product_id', v_product.id,
            'quantity', v_item.quantity,
            'unit_price_paise', v_product.wholesale_price_paise,
            'gst_amount_paise', v_gst_paise
        ));
    END LOOP;

    INSERT INTO wholesale_order_drafts (
        merchant_id,
        items,
        total_amount_paise,
        expected_amount_paise,
        status
    ) VALUES (
        p_merchant_id,
        v_validated_items,
        v_total_paise,
        v_total_paise,
        'pending'
    ) RETURNING id INTO v_draft_id;

    RETURN jsonb_build_object(
        'success', true,
        'draft_id', v_draft_id,
        'total_amount_paise', v_total_paise
    );
END;
$function$
